window.PLACES = [{"id":"banh-mi-huynh-hoa","region":"hcmc","area":"District 1 (Ben Thanh)","category":"streetfood","name":"Banh Mi Huynh Hoa","nameVi":"Bánh Mì Huỳnh Hoa","lat":10.77152,"lng":106.6924,"address":"26 Lê Thị Riêng, Bến Thành Ward (District 1), HCMC","rating":4.4,"googleRating":4.1,"price":1,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Hailed as Saigon's best bánh mì by Mark Wiens/Migrationology and countless TikTok queue videos","desc":{"en":"Saigon's most famous bánh mì: a brick-heavy baguette stuffed with pâté, a dozen cold cuts, pork floss and butter. The queue snakes down the street, but it moves fast.","uk":"Найвідоміший бань мі Сайгона: багет, що важить як цеглина, щедро начинений паштетом, десятком видів м'ясної нарізки, свинячою «ватою» та маслом. Черга тягнеться вулицею, але рухається швидко."},"tip":{"en":"One sandwich easily feeds two. Order 'bánh mì đặc biệt'; ask 'không cay' if you don't want chilli. Cash only.","uk":"Одного сендвіча вистачить на двох. Замовляйте «bánh mì đặc biệt»; скажіть «không cay», якщо не хочете чилі. Лише готівка."},"hours":"","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/8/8f/B%C3%A1nh_m%C3%AC_%C4%91%E1%BA%B7c_tr%C6%B0ng_S%C3%A0ig%C3%B2n.JPG/960px-B%C3%A1nh_m%C3%AC_%C4%91%E1%BA%B7c_tr%C6%B0ng_S%C3%A0ig%C3%B2n.JPG","https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/2023-12-10_Coffee_and_b%C3%A1nh_m%C3%AC_in_Saigon.jpg/960px-2023-12-10_Coffee_and_b%C3%A1nh_m%C3%AC_in_Saigon.jpg"]},{"id":"pho-hoa-pasteur","region":"hcmc","area":"District 3 (Xuan Hoa)","category":"streetfood","name":"Pho Hoa Pasteur","nameVi":"Phở Hòa Pasteur","lat":10.78669,"lng":106.68926,"address":"260C Pasteur, Xuân Hòa Ward (District 3), HCMC","rating":4.2,"googleRating":4.2,"price":2,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Saigon pho institution since 1968; in nearly every guidebook","desc":{"en":"A bustling, old-school pho hall that has ladled southern-style beef pho on the same corner since the 1960s, with heaps of herbs, bean sprouts and quẩy doughnuts on every table.","uk":"Гамірна старосвітська фо-зала, яка з 1960-х розливає південний яловичий фо на тому самому розі; на кожному столі — гори зелені, паростків і пончиків «куай»."},"tip":{"en":"Go for 'phở tái nạm' (rare steak and flank). The quẩy and herbs on the table are charged if eaten. Busiest 7–9 am.","uk":"Беріть «phở tái nạm» (слабосмажена яловичина та пашина). Пончики й зелень на столі оплачуються окремо, якщо їх з'їсти. Найбільше людей о 7–9 ранку."},"hours":"06:00–22:30","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/Pho_Bo_%28Noodle_with_beef%29_%282656424326%29.jpg/960px-Pho_Bo_%28Noodle_with_beef%29_%282656424326%29.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Pho-Beef-Noodle-Soup-2008.jpg/960px-Pho-Beef-Noodle-Soup-2008.jpg"]},{"id":"com-tam-ba-ghien","region":"hcmc","area":"Phu Nhuan","category":"streetfood","name":"Com Tam Ba Ghien","nameVi":"Cơm Tấm Ba Ghiền","lat":10.79444,"lng":106.66935,"address":"84 Đặng Văn Ngữ, Phú Nhuận Ward, HCMC","rating":4.5,"googleRating":null,"price":1,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Michelin Bib Gourmand (2023–2026); famous for its plate-sized pork chop","desc":{"en":"Broken-rice heaven: a smoky, caramelised pork chop so big it hangs off the plate, with steamed egg meatloaf, shredded pork skin and sweet fish sauce.","uk":"Рай для любителів «битого» рису: димна карамелізована свиняча відбивна, що звисає з тарілки, з паровою яєчною запіканкою, тонкою свинячою шкіркою та солодкуватим рибним соусом."},"tip":{"en":"Order 'cơm sườn bì chả' for the full combo. Lunchtime queues are long; go mid-morning or after 2 pm.","uk":"Замовляйте «cơm sườn bì chả» — повний комплект. В обід довгі черги, тож приходьте до полудня або після 14:00."},"hours":"07:00–21:00","website":"https://guide.michelin.com/vn/en/ho-chi-minh/ho-chi-minh_2978179/restaurant/com-tam-ba-ghien","images":["https://prod-pics.guide.michelin.com/api/public/content/dab4efaeccd847a8a2bcd75ad6e596a3.jpeg","https://prod-pics.guide.michelin.com/api/public/content/bb25266a6f7d426fb6b8df17a6500dab.jpeg"]},{"id":"lunch-lady-saigon","region":"hcmc","area":"District 1 (Da Kao)","category":"streetfood","name":"The Lunch Lady","nameVi":"Bà Bán Bún (Nguyễn Thị Thanh)","lat":10.79174,"lng":106.70442,"address":"23 Hoàng Sa (stall by Lô C1, Nguyễn Đình Chiểu apartments), Sài Gòn Ward (District 1), HCMC","rating":3.9,"googleRating":3.9,"price":1,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Anthony Bourdain's No Reservations (2009)","desc":{"en":"The sidewalk soup stall Anthony Bourdain made world-famous, serving a different noodle soup each day of the week. Founder Nguyễn Thị Thanh passed away in 2025; her family keeps the pots going.","uk":"Вуличний ларьок із супами, який прославив Ентоні Бурден: щодня тут інший суп із локшиною. Засновниця Нгуєн Тхі Тхань померла 2025 року, але її родина продовжує справу."},"tip":{"en":"Lunch only and it sells out — arrive by 11:30. Confirm the price before you eat; some visitors report tourist pricing.","uk":"Працює лише в обід і швидко розпродується — приходьте до 11:30. Уточніть ціну заздалегідь: дехто скаржиться на «туристичні» ціни."},"hours":"10:30–15:30 (closed Sun)","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/B%C3%BAn_b%C3%B2_Hu%E1%BA%BF_-_Ch%E1%BB%A3_%C4%90%C3%B4ng_Ba_%282024%29_-_img_02.jpg/960px-B%C3%BAn_b%C3%B2_Hu%E1%BA%BF_-_Ch%E1%BB%A3_%C4%90%C3%B4ng_Ba_%282024%29_-_img_02.jpg"]},{"id":"bun-cha-145-bui-vien","region":"hcmc","area":"District 1 (Pham Ngu Lao)","category":"streetfood","name":"Bun Cha 145","nameVi":"Bún Chả 145","lat":10.76632,"lng":106.69174,"address":"145 Bùi Viện, Bến Thành Ward (District 1), HCMC","rating":4.1,"googleRating":4.3,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"TripAdvisor favourite in the backpacker quarter","desc":{"en":"A tiny red-brick shop doing proper Hanoi-style bún chả — charcoal-grilled pork patties in a sweet-sour broth with rice noodles and herbs — right on Bùi Viện.","uk":"Крихітний закладчик із червоної цегли, де подають справжній ханойський бун ча — свинячі котлетки на вугіллі в кисло-солодкому бульйоні з рисовою локшиною та зеленню — просто на Буй Вієн."},"tip":{"en":"Add a crispy 'nem rán' (fried spring roll). Go before the evening Bùi Viện crowds arrive.","uk":"Додайте хрусткий «nem rán» (смажений спринг-рол). Приходьте до того, як на Буй Вієн збереться вечірній натовп."},"hours":"11:00–21:00","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/B%C3%BAn_ch%E1%BA%A3_Vietnamese_food.jpg/960px-B%C3%BAn_ch%E1%BA%A3_Vietnamese_food.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/5/56/Bun_cha_Hanoi.jpg/960px-Bun_cha_Hanoi.jpg"]},{"id":"banh-xeo-46a","region":"hcmc","area":"District 1 (Tan Dinh)","category":"streetfood","name":"Banh Xeo 46A","nameVi":"Bánh Xèo 46A","lat":10.78957,"lng":106.69134,"address":"46A Đinh Công Tráng, Tân Định Ward (District 1), HCMC","rating":4.0,"googleRating":3.8,"price":2,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Michelin Bib Gourmand (2023–2026); a staple of food-vlogger Saigon itineraries","desc":{"en":"Giant, lacy turmeric crêpes crackling out of a wall of woks, stuffed with shrimp, pork and bean sprouts and eaten wrapped in mustard greens and herbs.","uk":"Величезні мереживні куркумові млинці, що шкварчать у ряді воків, з креветками, свининою та паростками; їх загортають у листя гірчиці й зелень."},"tip":{"en":"One crêpe is enough for two as a snack. Tear, wrap in a lettuce leaf with herbs, dip in nước chấm.","uk":"Одного млинця вистачить на двох як перекусу. Відривайте шматок, загортайте в салат із зеленню й умочайте в соус «ниок чам»."},"hours":"10:00–21:00","website":"https://guide.michelin.com/vn/en/ho-chi-minh/ho-chi-minh_2978179/restaurant/banh-xeo-46a","images":["https://prod-pics.guide.michelin.com/api/public/content/90562680ae5c47d58578cdfd31914dfc.jpeg","https://prod-pics.guide.michelin.com/api/public/content/1b0cab86897247428cf3abe5afa84e04.jpeg"]},{"id":"oc-oanh","region":"hcmc","area":"District 4 (Khanh Hoi)","category":"streetfood","name":"Oc Oanh","nameVi":"Ốc Oanh","lat":10.76072,"lng":106.70331,"address":"534 Vĩnh Khánh, Khánh Hội Ward (District 4), HCMC","rating":4.3,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Michelin Selected; the star of Vinh Khanh snail street on TikTok","desc":{"en":"The flagship of Saigon's snail street: plastic stools spilling onto the pavement, sizzling grilled scallops with scallion oil and a dozen kinds of ốc stir-fried in butter, tamarind or coconut.","uk":"Флагман сайгонської «равликової вулиці»: пластикові стільчики на тротуарі, гребінці на грилі з зеленою олією та десяток видів равликів «ок», смажених у маслі, тамаринді чи кокосі."},"tip":{"en":"Try 'ốc hương rang muối ớt' (salt-chilli sea snails) and 'sò điệp nướng mỡ hành'. Prices are per plate — check the menu.","uk":"Спробуйте «ốc hương rang muối ớt» (равлики з сіллю та чилі) і «sò điệp nướng mỡ hành» (гребінці). Ціни — за тарілку, дивіться меню."},"hours":"16:00–00:00","website":"https://guide.michelin.com/vn/en/ho-chi-minh/ho-chi-minh_2978179/restaurant/oc-oanh","images":["https://prod-pics.guide.michelin.com/api/public/content/cefd030fd34e484e9cf1f2c28bccbaa3.jpeg","https://prod-pics.guide.michelin.com/api/public/content/ff52951612f64c5baac1ae5d3648bdac.jpeg"]},{"id":"pho-minh-pasteur","region":"hcmc","area":"District 1 (Saigon Ward)","category":"streetfood","name":"Pho Minh","nameVi":"Phở Minh","lat":10.77478,"lng":106.70025,"address":"63/6 Pasteur (in the alley), Sài Gòn Ward (District 1), HCMC","rating":4.4,"googleRating":4.4,"price":1,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Michelin Bib Gourmand; family-run alley pho since the 1960s","desc":{"en":"Hidden down a narrow alley off Pasteur, this decades-old family shop serves a clear, clean northern-leaning broth with tender brisket and beef balls to office workers in the know.","uk":"Захована у вузькому провулку біля вулиці Пастер, ця родинна фо-забігайлівка з багаторічною історією подає прозорий, чистий бульйон північного стилю з ніжною грудинкою та яловичими фрикадельками."},"tip":{"en":"Look for the alley at 63 Pasteur and walk in — the shop is on the left. Go early; it can sell out by early afternoon.","uk":"Шукайте провулок біля будинку 63 на Пастер і заходьте всередину — заклад ліворуч. Приходьте зранку: бульйон може закінчитися вже по обіді."},"hours":"","website":"https://guide.michelin.com/vn/en/ho-chi-minh/ho-chi-minh_2978179/restaurant/pho-minh","images":["https://prod-pics.guide.michelin.com/api/public/content/8eff85a3241042d3b28c52b6a1bd26fb.jpg","https://prod-pics.guide.michelin.com/api/public/content/bf2f5a3e61f54502a1880b011cb73226.jpeg"]},{"id":"hu-tieu-hong-phat","region":"hcmc","area":"District 3 (Ban Co)","category":"streetfood","name":"Hu Tieu Nam Vang Hong Phat","nameVi":"Hủ Tiếu Nam Vang Hồng Phát","lat":10.77051,"lng":106.68484,"address":"389–391 Võ Văn Tần, Bàn Cờ Ward (District 3), HCMC","rating":4.2,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Michelin Bib Gourmand (2024–2026)","desc":{"en":"A bright, busy institution for hủ tiếu Nam Vang — Phnom Penh-style noodles loaded with pork, liver, shrimp and quail eggs, served in broth or 'dry' with the soup on the side.","uk":"Яскравий, завжди повний заклад, де готують хủ тієу Намванг — локшину в пномпеньському стилі зі свининою, печінкою, креветками й перепелиними яйцями, у бульйоні або «сухою» з супом окремо."},"tip":{"en":"Order it 'khô' (dry) with the broth on the side — that's the local favourite. Open from early morning.","uk":"Замовляйте «khô» (суху версію) з бульйоном окремо — так їдять місцеві. Працює з раннього ранку."},"hours":"06:00–22:00","website":"https://hutieuhongphat.com","images":["https://prod-pics.guide.michelin.com/api/public/content/1fc5fb7c414149deb301f0f85cbe1b78.jpg","https://prod-pics.guide.michelin.com/api/public/content/63a95698df4746b9a53157d0986b2520.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Hu_Tieu_Nam_Vang.jpg/960px-Hu_Tieu_Nam_Vang.jpg"]},{"id":"bun-bo-hue-14b","region":"hcmc","area":"District 4 (Vinh Hoi)","category":"streetfood","name":"Bun Bo Hue 14B","nameVi":"Bún Bò Huế 14B","lat":10.75941,"lng":106.69741,"address":"14B Đường 46, Vĩnh Hội Ward (District 4), HCMC","rating":4.3,"googleRating":4.2,"price":1,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Michelin Bib Gourmand","desc":{"en":"A no-frills neighbourhood shop across the canal in District 4 serving a deep, lemongrass-and-shrimp-paste bún bò Huế with pork hock and crab cake that locals cross town for.","uk":"Простий районний заклад за каналом у 4-му окрузі: насичений бун бо Хюе з лемонграсом і креветковою пастою, свинячою рулькою та крабовою котлеткою, заради якого місцеві їдуть через усе місто."},"tip":{"en":"Breakfast is the time — it often closes after lunch. Squeeze in lime and add the shrimp paste gradually.","uk":"Найкраще йти на сніданок — після обіду часто зачиняється. Додайте лайм і креветкову пасту поступово."},"hours":"06:00–14:00","website":"https://guide.michelin.com/vn/en/ho-chi-minh/ho-chi-minh_2978179/restaurant/bun-bo-hue-14b","images":["https://prod-pics.guide.michelin.com/api/public/content/ca3054a1b5af4719ba458a21a7d4bf17.jpg","https://prod-pics.guide.michelin.com/api/public/content/5468df0ffec948aaa05df025ff709c8a.jpg"]},{"id":"banh-mi-hoa-ma","region":"hcmc","area":"District 3 (Ban Co)","category":"streetfood","name":"Banh Mi Hoa Ma","nameVi":"Bánh Mì Hòa Mã","lat":10.77021,"lng":106.68159,"address":"53 Cao Thắng, Bàn Cờ Ward (District 3), HCMC","rating":4.2,"googleRating":4.3,"price":1,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Credited with inventing Saigon's bánh mì breakfast (since the 1950s–60s); Saigoneer 'Hẻm Gems'","desc":{"en":"A pavement breakfast legend serving sizzling 'bánh mì chảo' — eggs, pâté, cold cuts and sausage in a hot skillet with a crusty baguette — on tiny stools since the 1950s.","uk":"Легендарний сніданковий заклад просто на тротуарі: шкварчить «бань мі тяо» — яйця, паштет, нарізка й ковбаски на гарячій сковорідці з хрустким багетом — і так із 1950-х."},"tip":{"en":"Mornings only (roughly 6–11 am). Order the 'ốp la' pan with everything and a cà phê sữa đá from a neighbour.","uk":"Лише вранці (приблизно 6–11). Замовляйте сковорідку «ốp la» з усім і каву з молоком із сусіднього кіоску."},"hours":"06:00–11:00","website":"","images":["https://media.urbanistnetwork.com/saigoneer/article-images/legacy/WWrOAphb.jpg","https://media.urbanistnetwork.com/saigoneer/article-images/legacy/WWrOAphh.jpg"]},{"id":"bo-kho-ganh","region":"hcmc","area":"District 10 (Vuon Lai)","category":"streetfood","name":"Bo Kho Ganh","nameVi":"Bò Kho Gánh","lat":10.76179,"lng":106.673,"address":"Lô H/029, Ngô Gia Tự apartments, Sư Vạn Hạnh, Vườn Lài Ward (District 10), HCMC","rating":4.3,"googleRating":4.1,"price":1,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Michelin Bib Gourmand; started as a carrying-pole street stall","desc":{"en":"Tucked into the ground floor of an old apartment block, this family stall ladles a fragrant star-anise beef stew with fall-apart brisket and tendon, to mop up with baguette or noodles.","uk":"У першому поверсі старого житлового блоку родина розливає ароматне рагу бо кхо з бадьяном, яловичиною, що розпадається, та сухожиллями — його вимочують багетом або їдять із локшиною."},"tip":{"en":"Order 'bò kho bánh mì' and go early — it's a breakfast spot and sells out.","uk":"Беріть «bò kho bánh mì» і приходьте рано — це сніданкове місце, усе швидко розбирають."},"hours":"06:00–11:00","website":"https://www.bokhoganh.com","images":["https://prod-pics.guide.michelin.com/api/public/content/ed5a065b62b542d6a1a1dcc085344c9a.jpeg","https://prod-pics.guide.michelin.com/api/public/content/5318677c6c2d4d07956edbe5013a7e21.jpeg"]},{"id":"xoi-ga-number-one","region":"hcmc","area":"District 1 (Ben Thanh)","category":"streetfood","name":"Xoi Ga Number One","nameVi":"Xôi Gà Number One","lat":10.77379,"lng":106.6992,"address":"15 Nguyễn Trung Trực, Bến Thành Ward (District 1), HCMC","rating":4.2,"googleRating":4.5,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Michelin Selected","desc":{"en":"A decades-old sticky-rice shop near Bến Thành piling glutinous rice with shredded chicken, Chinese sausage, pork floss and fried shallots — Saigon's favourite grab-and-go breakfast.","uk":"Старий заклад клейкого рису біля ринку Бен Тхань: рис із курятиною, китайською ковбаскою, свинячою «ватою» та смаженою цибулькою — улюблений сайгонський сніданок «на бігу»."},"tip":{"en":"Ask for 'xôi gà thập cẩm' (the mixed version). Cheap, quick and great before a market visit.","uk":"Попросіть «xôi gà thập cẩm» (асорті). Дешево, швидко й ідеально перед походом на ринок."},"hours":"06:00–21:00","website":"https://guide.michelin.com/vn/en/ho-chi-minh/ho-chi-minh_2978179/restaurant/xoi-ga-number-one","images":["https://prod-pics.guide.michelin.com/api/public/content/e2fc228b2fa3436ab4d6f03f60907b0f.jpeg","https://prod-pics.guide.michelin.com/api/public/content/fa24ec1a9fe343169bf71cf5274b84d1.jpeg"]},{"id":"ho-thi-ky-food-alley","region":"hcmc","area":"District 10 (Vuon Lai)","category":"streetfood","name":"Ho Thi Ky Food Alley","nameVi":"Hẻm Ẩm Thực Hồ Thị Kỷ","lat":10.76539,"lng":106.67701,"address":"Hẻm 52 Hồ Thị Kỷ (by the flower market), Vườn Lài Ward (District 10), HCMC","rating":4.3,"googleRating":4.4,"price":1,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"TikTok-famous night food alley; stop on most motorbike food tours","desc":{"en":"A maze of alleys behind Saigon's wholesale flower market that turns into a smoky, neon-lit grazing ground at night — Cambodian-style grilled beef, bánh tráng nướng, chè and fruit shakes.","uk":"Лабіринт провулків за оптовим квітковим ринком, який увечері перетворюється на димний неоновий фудкорт: яловичина на грилі по-камбоджійськи, «в'єтнамська піца» бань чанг нионг, десерти че та фруктові шейки."},"tip":{"en":"Come hungry after 6 pm and graze stall by stall; bring small notes. Flower market is liveliest pre-dawn.","uk":"Приходьте голодними після 18:00 і куштуйте від ларька до ларька; майте дрібні купюри. Квітковий ринок найжвавіший перед світанком."},"hours":"15:00–23:00","website":"","images":["https://media.urbanistnetwork.com/saigoneer/article-images/legacy/ZuGzOM7b.jpg","https://media.urbanistnetwork.com/saigoneer/article-images/legacy/y0X8s2Yb.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/20180413_190400Saigon_Hotpot_Night_Food_Tour_Ho_Thi_Ky_Flower_Market.jpg/960px-20180413_190400Saigon_Hotpot_Night_Food_Tour_Ho_Thi_Ky_Flower_Market.jpg"]},{"id":"anan-saigon","region":"hcmc","area":"District 1 (Saigon Ward)","category":"restaurants","name":"Anan Saigon","nameVi":"Ănăn Saigon","lat":10.77192,"lng":106.70287,"address":"89 Tôn Thất Đạm, Sài Gòn Ward (District 1), HCMC","rating":4.9,"googleRating":4.1,"price":4,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"One Michelin Star (2023–2026); Asia's 50 Best Restaurants; Peter Cuong Franklin's viral $100 bánh mì","desc":{"en":"Chef Peter Cuong Franklin's playful reinvention of Vietnamese street food in a narrow shophouse above District 1's last wet market — think bánh xèo tacos and the famous foie-gras-and-truffle bánh mì.","uk":"Шеф Пітер Куонг Франклін грайливо переосмислює в'єтнамський стрітфуд у вузькому будиночку над останнім мокрим ринком 1-го округу: такос із бань се та знаменитий бань мі з фуа-гра й трюфелем."},"tip":{"en":"Book ahead for the tasting menu; finish with a drink upstairs at Nhau Nhau bar.","uk":"Бронюйте дегустаційне меню заздалегідь; завершіть вечір коктейлем у барі Nhau Nhau поверхом вище."},"hours":"17:00–23:00","website":"https://anansaigon.com","images":["https://prod-pics.guide.michelin.com/api/public/content/a48e444cf62f43c9add3aa82c029e66f.jpg","https://prod-pics.guide.michelin.com/api/public/content/31fbaeaf9d724c6997705e99793dd946.jpg","https://prod-pics.guide.michelin.com/api/public/content/53812f4aec4243efb3efd3fc19aaee0e.jpeg"]},{"id":"akuna","region":"hcmc","area":"District 1 (Saigon Ward)","category":"restaurants","name":"Akuna","nameVi":"Akuna","lat":10.77989,"lng":106.70742,"address":"9F, Le Méridien Saigon, 3C Tôn Đức Thắng, Sài Gòn Ward (District 1), HCMC","rating":4.6,"googleRating":4.4,"price":4,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"One Michelin Star (2024–2026)","desc":{"en":"An open-kitchen tasting counter where Australian-born chef Sam Aisbett marries native Australian ingredients with Vietnamese produce, overlooking the Saigon River.","uk":"Дегустаційна стійка з відкритою кухнею, де австралійський шеф Сем Ейсбетт поєднує австралійські інгредієнти з в'єтнамськими продуктами з видом на річку Сайгон."},"tip":{"en":"Dinner only, reservation essential; sit at the counter to watch the kitchen.","uk":"Лише вечеря, бронювання обов'язкове; сідайте за стійку, щоб бачити роботу кухні."},"hours":"18:00–22:30","website":"https://akunarestaurant.com","images":["https://prod-pics.guide.michelin.com/api/public/content/1b7a4e162ef348daa6fbc57dfb48b5b9.jpeg","https://prod-pics.guide.michelin.com/api/public/content/9f1f55c3ecc84d128351b5d1907a0b18.jpeg","https://prod-pics.guide.michelin.com/api/public/content/b92d321095bb4640bdf0fbf7cf39de16.jpeg"]},{"id":"coco-dining","region":"hcmc","area":"District 3 (Xuan Hoa)","category":"restaurants","name":"Coco Dining","nameVi":"Coco Dining","lat":10.78087,"lng":106.69325,"address":"143 Nam Kỳ Khởi Nghĩa, Xuân Hòa Ward (District 3), HCMC","rating":4.5,"googleRating":4.6,"price":4,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"One Michelin Star (2025–2026)","desc":{"en":"An intimate, low-lit dining room serving refined, ingredient-led tasting menus that blend French technique with Vietnamese and Asian flavours.","uk":"Камерна, приглушено освітлена зала з вишуканими дегустаційними сетами, де французька техніка поєднується з в'єтнамськими та азійськими смаками."},"tip":{"en":"Book a few days ahead; the CoCo Bar downstairs (Tatler Best 20 Bars 2026) is great for a pre-dinner drink.","uk":"Бронюйте за кілька днів; CoCo Bar унизу (Tatler Best 20 Bars 2026) — чудове місце для аперитиву."},"hours":"18:00–23:00","website":"https://cocosgn.com","images":["https://prod-pics.guide.michelin.com/api/public/content/408de2427ab94de4be6b7a7b9f16dfe9.jpeg","https://prod-pics.guide.michelin.com/api/public/content/3c6f0eb65c8b4d128d48b34f2ed87d43.jpg","https://prod-pics.guide.michelin.com/api/public/content/8575bdde5cf44aada4f99a4ca542558b.jpeg"]},{"id":"long-trieu","region":"hcmc","area":"District 1 (Saigon Ward)","category":"restaurants","name":"Long Trieu","nameVi":"Long Triều","lat":10.77395,"lng":106.70475,"address":"4F, The Reverie Saigon, 22–36 Nguyễn Huệ, Sài Gòn Ward (District 1), HCMC","rating":4.4,"googleRating":4.4,"price":4,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"One Michelin Star (Cantonese)","desc":{"en":"Opulent Cantonese dining inside the over-the-top Reverie hotel, with polished dim sum at lunch and Peking duck and seafood at dinner.","uk":"Розкішна кантонська кухня в пишному готелі The Reverie: вишукані дім-самі в обід, качка по-пекінськи та морепродукти ввечері."},"tip":{"en":"Weekend dim sum lunch is the best-value way in; book a window table.","uk":"Найвигідніше прийти на дім-сам у вихідні в обід; бронюйте столик біля вікна."},"hours":"11:30–14:30, 18:00–22:00","website":"https://www.thereveriesaigon.com/restaurants-bars/long-trieu","images":["https://prod-pics.guide.michelin.com/api/public/content/4feb5952311e462887534e84f3dbcb1e.jpg","https://prod-pics.guide.michelin.com/api/public/content/ba3a0b6e5e594c7cbf532042674c2205.jpg","https://prod-pics.guide.michelin.com/api/public/content/313853209a264e72b236039e5a486979.jpeg"]},{"id":"esta-saigon","region":"hcmc","area":"District 3 (Tan Dinh)","category":"restaurants","name":"Esta","nameVi":"Esta","lat":10.79337,"lng":106.68822,"address":"27 Trần Quý Khoách, Tân Định Ward (District 1/3 border), HCMC","rating":4.5,"googleRating":4.7,"price":3,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Michelin Selected; wood-fire cooking with Vietnamese produce","desc":{"en":"Chef-driven, fire-centred cooking — dry-aged meats, ember-roasted vegetables and fermented touches — built entirely around local farms and fishermen.","uk":"Авторська кухня навколо живого вогню — витримане м'ясо, овочі, запечені на жарі, ферментовані акценти — усе на продуктах місцевих фермерів і рибалок."},"tip":{"en":"Esta moved from its Đông Du alley to Tân Định — double-check the new address when booking. Order the dry-aged duck.","uk":"Ресторан переїхав із провулку на Донг Зу до Тан Дінь — перевірте нову адресу під час бронювання. Замовте витриману качку."},"hours":"17:30–22:30","website":"https://www.estasaigon.com","images":["https://prod-pics.guide.michelin.com/api/public/content/478a966cc0a64cd8a6421079569565d7.jpg","https://prod-pics.guide.michelin.com/api/public/content/eadc99b8ab1442f1a0e8f5996116f03c.jpg","https://prod-pics.guide.michelin.com/api/public/content/a5b9c79236e6450a9be162c1da920199.jpeg"]},{"id":"cuc-gach-quan","region":"hcmc","area":"District 1 (Tan Dinh)","category":"restaurants","name":"Cuc Gach Quan","nameVi":"Cục Gạch Quán","lat":10.79303,"lng":106.68926,"address":"10 Đặng Tất, Tân Định Ward (District 1), HCMC","rating":4.4,"googleRating":4.3,"price":2,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Michelin Bib Gourmand; famously visited by Brad Pitt and Angelina Jolie","desc":{"en":"Rustic home-style Vietnamese cooking in a lovingly restored 1920s villa full of antiques, vintage furniture and plants — clay-pot fish, fried tofu with lemongrass, flower salads.","uk":"Домашня в'єтнамська кухня в дбайливо відреставрованій віллі 1920-х, повній антикваріату, старовинних меблів і рослин: риба в глиняному горщику, тофу з лемонграсом, салати з квітів."},"tip":{"en":"Reserve for dinner and ask for an upstairs table. Try 'cá kho tộ' and the crispy tofu.","uk":"Бронюйте вечерю й просіть столик нагорі. Спробуйте «cá kho tộ» (рибу в горщику) та хрусткий тофу."},"hours":"09:00–23:00","website":"https://cucgachquan.com","images":["https://prod-pics.guide.michelin.com/api/public/content/adf4f51d94be4a2a943e839f6479bdaa.jpeg","https://prod-pics.guide.michelin.com/api/public/content/5a8223c3a74f4b178c0b1b8882bd53a8.jpeg","https://prod-pics.guide.michelin.com/api/public/content/d6a9ee4c56c24ba49a5f2bb4ff58f0aa.jpeg"]},{"id":"bep-me-in","region":"hcmc","area":"District 1 (Ben Thanh)","category":"restaurants","name":"Bep Me In","nameVi":"Bếp Mẹ Ỉn","lat":10.77386,"lng":106.69808,"address":"136/9 Lê Thánh Tôn (in the alley), Bến Thành Ward (District 1), HCMC","rating":4.4,"googleRating":4.5,"price":2,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Michelin Bib Gourmand; Instagram-favourite alley eatery","desc":{"en":"A cheerful, colourful alley restaurant near Bến Thành turning street-food classics — bánh xèo, cơm tấm, papaya salad — into polished sit-down plates.","uk":"Веселий, яскравий ресторанчик у провулку біля Бен Тхань, де класику стрітфуду — бань се, ком там, салат із папаї — подають у ресторанному форматі."},"tip":{"en":"Book for dinner or go at lunch; the nearby Bánh Mì Mẹ Ỉn counter is a great quick alternative.","uk":"Бронюйте на вечерю або приходьте в обід; сусідня кав'ярня Bánh Mì Mẹ Ỉn — чудовий швидкий варіант."},"hours":"10:00–22:30","website":"https://bep.mein.vn","images":["https://prod-pics.guide.michelin.com/api/public/content/58ca3c105bc740f5bf4edca36bd831ac.jpeg","https://prod-pics.guide.michelin.com/api/public/content/aaa47dad9cb142debd2b149377c8bfb9.jpeg","https://prod-pics.guide.michelin.com/api/public/content/a776aaba47bd459f988f7534c3b3e93d.jpeg"]},{"id":"hum-garden","region":"hcmc","area":"Thu Duc (An Khanh / Thao Dien)","category":"restaurants","name":"Hum Garden","nameVi":"Hum Garden","lat":10.80421,"lng":106.74448,"address":"32 Đường D10, An Khánh Ward (former District 2), HCMC","rating":4.4,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Michelin Bib Gourmand (vegetarian)","desc":{"en":"The garden outpost of Saigon's best-known vegetarian brand: serene, leafy and serving creative plant-based Vietnamese dishes even carnivores rave about.","uk":"Садова філія найвідомішого вегетаріанського бренду Сайгона: спокій, зелень і креативні рослинні в'єтнамські страви, від яких у захваті навіть м'ясоїди."},"tip":{"en":"If you stay central, the sister Hum Signature at 34 Võ Văn Tần (District 3) serves a similar menu.","uk":"Якщо живете в центрі, сестринський Hum Signature на 34 Võ Văn Tần (3-й округ) має схоже меню."},"hours":"10:00–22:00","website":"https://hum-dining.vn","images":["https://prod-pics.guide.michelin.com/api/public/content/da3e91cfabba47b9a6569e725156aa36.jpg","https://prod-pics.guide.michelin.com/api/public/content/5cd004aff0374db7ae0fbb4e7713a60d.jpg","https://prod-pics.guide.michelin.com/api/public/content/c0a9cdc3711e4a3fa1d02bfdde904936.jpeg"]},{"id":"nha-tu","region":"hcmc","area":"District 3 (Xuan Hoa)","category":"restaurants","name":"Nha Tu","nameVi":"Nhà Tú","lat":10.77537,"lng":106.68988,"address":"129/4 Võ Văn Tần (in the alley), Xuân Hòa Ward (District 3), HCMC","rating":4.4,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Michelin Bib Gourmand","desc":{"en":"A homey little house down a District 3 alley cooking soulful family-style Vietnamese dishes, like eating in a friend's grandmother's kitchen.","uk":"Затишний будиночок у провулку 3-го округу з душевною сімейною в'єтнамською кухнею — ніби обідаєте на кухні бабусі вашого друга."},"tip":{"en":"Small and popular with locals — book or arrive early, and order several dishes to share with rice.","uk":"Невеликий і популярний серед місцевих — бронюйте або приходьте рано; замовляйте кілька страв на компанію з рисом."},"hours":"","website":"https://guide.michelin.com/vn/en/ho-chi-minh/ho-chi-minh_2978179/restaurant/nha-tu","images":["https://prod-pics.guide.michelin.com/api/public/content/82c8e41e00334475b654d1b146eb550a.jpg","https://prod-pics.guide.michelin.com/api/public/content/262b10b90bb142f382983034557d8675.jpg","https://prod-pics.guide.michelin.com/api/public/content/2e4fa70465a940a2a33d61919b8cec2c.jpeg"]},{"id":"quince-eatery","region":"hcmc","area":"District 1 (Ben Thanh)","category":"restaurants","name":"Quince Eatery","nameVi":"Quince Eatery","lat":10.76619,"lng":106.69923,"address":"37bis Ký Con, Bến Thành Ward (District 1), HCMC","rating":4.5,"googleRating":4.7,"price":3,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Michelin Selected","desc":{"en":"A moody, industrial-chic dining room built around a wood-fired grill, serving smoky Mediterranean-leaning share plates and an excellent wine list.","uk":"Атмосферна зала в індустріальному стилі навколо дров'яного гриля: димні страви для компанії з середземноморськими нотами та чудова винна карта."},"tip":{"en":"Sit at the counter facing the grill; book on weekends.","uk":"Сідайте за стійку навпроти гриля; у вихідні бронюйте."},"hours":"17:30–23:00","website":"https://www.quincesaigon.com","images":["https://prod-pics.guide.michelin.com/api/public/content/f5dc2efd52ae4e7ab3d24dd5741ce1e2.jpg","https://prod-pics.guide.michelin.com/api/public/content/3134ab4687024bf7a5d26a0b183ab53f.jpg","https://prod-pics.guide.michelin.com/api/public/content/14194098e0eb4ea8bbbab7273dd6fb2a.jpeg"]},{"id":"cafe-apartments-42-nguyen-hue","region":"hcmc","area":"District 1 (Saigon Ward)","category":"cafes","name":"The Cafe Apartments","nameVi":"Chung Cư 42 Nguyễn Huệ","lat":10.77409,"lng":106.70406,"address":"42 Nguyễn Huệ, Sài Gòn Ward (District 1), HCMC","rating":4.5,"googleRating":4.4,"price":2,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Instagram/TikTok icon on Nguyen Hue walking street","desc":{"en":"A faded 1960s apartment block on Nguyễn Huệ boulevard where nearly every flat is now a café or boutique — balconies stacked with tiny terraces overlooking the walking street.","uk":"Старий житловий будинок 1960-х на бульварі Нгуєн Хюе, де майже кожна квартира тепер кав'ярня чи бутик: балкони-тераси одна над одною з видом на пішохідну вулицю."},"tip":{"en":"The lift costs a few thousand dong (or free with a purchase); pick a high-floor café with a balcony for sunset.","uk":"Ліфт коштує кілька тисяч донгів (або безкоштовно з покупкою); оберіть кав'ярню на верхньому поверсі з балконом на захід сонця."},"hours":"08:00–22:00","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/42_Nguyen_Hue_Boulevard%2C_Saigon_%2853547606514%29.jpg/960px-42_Nguyen_Hue_Boulevard%2C_Saigon_%2853547606514%29.jpg","https://cms.vietnamcoracle.com/wp-content/uploads/2016/06/42-Nguyen-Hue-Finished-2755-thumb-final-1024x1024.jpg"]},{"id":"the-workshop-coffee","region":"hcmc","area":"District 1 (Saigon Ward)","category":"cafes","name":"The Workshop Coffee","nameVi":"The Workshop Coffee","lat":10.77348,"lng":106.7056,"address":"2F, 27 Ngô Đức Kế, Sài Gòn Ward (District 1), HCMC","rating":4.4,"googleRating":4.4,"price":2,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Pioneer of Saigon's specialty-coffee scene; #1 on Wanderlog's HCMC café list","desc":{"en":"A light-flooded loft above a colonial street with a central brew bar, where Saigon's third-wave coffee movement began — Vietnamese single-origins via pour-over, siphon and cold brew.","uk":"Залитий світлом лофт над колоніальною вулицею з баром у центрі — саме тут почалася «третя хвиля» кави в Сайгоні: в'єтнамські моносорти у пуровері, сифоні та колд-брю."},"tip":{"en":"Ask the baristas for a Đà Lạt single-origin pour-over; the stairs are easy to miss — look for the sign.","uk":"Попросіть пуровер із моносорту з Далату; вхід на сходи легко пропустити — шукайте вивіску."},"hours":"08:00–21:00","website":"","images":["https://www.brian-coffee-spot.com/wp-content/uploads/2017/06/Header-The-Workshop-Coffee-DSC_2339h.jpg"]},{"id":"okkio-caffe-le-loi","region":"hcmc","area":"District 1 (Ben Thanh)","category":"cafes","name":"Okkio Caffe (Le Loi)","nameVi":"Okkio Caffe Lê Lợi","lat":10.77253,"lng":106.69895,"address":"120–122 Lê Lợi (upstairs), Bến Thành Ward (District 1), HCMC","rating":4.4,"googleRating":4.6,"price":2,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Instagram-favourite specialty roaster","desc":{"en":"A stylish, plant-filled specialty café hidden upstairs in an old building on Lê Lợi, roasting its own beans and serving silky lattes and Vietnamese-style drip.","uk":"Стильна кав'ярня з рослинами, захована на верхньому поверсі старого будинку на Ле Лой: власне обсмаження, оксамитові лате та кава по-в'єтнамськи через фільтр."},"tip":{"en":"Order the 'bạc xỉu' or salted cream coffee. The Duy Tân branch (41 Phạm Ngọc Thạch) is in a gorgeous colonial villa.","uk":"Замовте «бак сіу» або каву з солоними вершками. Філія Duy Tân (41 Phạm Ngọc Thạch) — у чарівній колоніальній віллі."},"hours":"07:00–22:00","website":"","images":["https://vietnamisawesome.com/wp-content/uploads/2023/02/OKKIO-Coffee-Le-Loi.-Photo-by-OKKIO.jpg","https://thesmartlocal.com/vietnam/wp-content/uploads/2022/02/Okkio-Duy-Tan.jpg"]},{"id":"cong-caphe-ly-tu-trong","region":"hcmc","area":"District 1 (Saigon Ward)","category":"cafes","name":"Cong Caphe (Ly Tu Trong)","nameVi":"Cộng Cà Phê Lý Tự Trọng","lat":10.77817,"lng":106.70103,"address":"26 Lý Tự Trọng, Sài Gòn Ward (District 1), HCMC","rating":4.2,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Retro 'communist-chic' chain; its coconut coffee is a social-media staple","desc":{"en":"The Hanoi-born chain's army-green, Soviet-retro café, famous for cà phê cốt dừa — strong coffee blended with frozen coconut milk into a slushy dessert.","uk":"Кав'ярня ханойської мережі в армійсько-зеленому ретро-стилі, відома кавою «cà phê cốt dừa» — міцна кава, збита із замороженим кокосовим молоком у десерт-сорбет."},"tip":{"en":"Order 'cốt dừa cà phê' and grab a balcony seat. Cash is safest.","uk":"Замовте «cốt dừa cà phê» і займіть місце на балконі. Найнадійніше — готівка."},"hours":"07:00–23:00","website":"https://congcaphe.com","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/b/b4/C%C3%A0_Ph%C3%AA_S%E1%BB%AFa_%C4%90%C3%A1_V%E1%BB%8B_Coconut.jpg/960px-C%C3%A0_Ph%C3%AA_S%E1%BB%AFa_%C4%90%C3%A1_V%E1%BB%8B_Coconut.jpg"]},{"id":"little-hanoi-egg-coffee","region":"hcmc","area":"District 3 (Vo Thi Sau)","category":"cafes","name":"Little Hanoi Egg Coffee","nameVi":"Little HaNoi Egg Coffee","lat":10.77952,"lng":106.68655,"address":"258/1 Điện Biên Phủ, Xuân Hòa / Võ Thị Sáu Ward (District 3), HCMC","rating":4.5,"googleRating":4.8,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Saigon's go-to for Hanoi-style egg coffee; TripAdvisor favourite","desc":{"en":"A cosy café bringing Hanoi's legendary cà phê trứng south: strong robusta crowned with a thick, custardy whipped egg-yolk foam.","uk":"Затишна кав'ярня, що привезла на південь легендарну ханойську «cà phê trứng»: міцна робуста під шапкою густої, наче заварний крем, піни зі збитих жовтків."},"tip":{"en":"Have it hot (served in a bowl of warm water) and eat the foam with a spoon first. There is also a branch on Yersin St, District 1.","uk":"Пийте гарячою (подають у мисці з теплою водою) і спершу з'їжте піну ложечкою. Є також філія на вулиці Єрсен у 1-му окрузі."},"hours":"07:00–22:00","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/C%C3%A0_ph%C3%AA_tr%E1%BB%A9ng.jpg/960px-C%C3%A0_ph%C3%AA_tr%E1%BB%A9ng.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/d/de/C%C3%A0_ph%C3%AA_tr%E1%BB%A9ng_%C4%91%C3%A1.jpg/960px-C%C3%A0_ph%C3%AA_tr%E1%BB%A9ng_%C4%91%C3%A1.jpg"]},{"id":"cheo-leo-cafe","region":"hcmc","area":"District 3 (Ban Co)","category":"cafes","name":"Cheo Leo Cafe","nameVi":"Cà Phê Vợt Cheo Leo","lat":10.767,"lng":106.67985,"address":"109/36 Nguyễn Thiện Thuật (alley), Bàn Cờ Ward (District 3), HCMC","rating":4.6,"googleRating":4.4,"price":1,"mustSee":true,"hiddenGem":true,"viral":false,"hype":"Saigon's oldest café (since 1938); Saigoneer 'Hẻm Gems'","desc":{"en":"Saigon's oldest café, deep in a residential alley, still brewing cà phê vợt — coffee steeped through a cloth 'sock' over charcoal-heated kettles, exactly as in 1938.","uk":"Найстаріша кав'ярня Сайгона в глибині житлового провулку досі готує «cà phê vợt» — каву, проціджену крізь тканинну «шкарпетку» над чайниками на вугіллі, точно як у 1938 році."},"tip":{"en":"Go early morning to see the charcoal stoves in action; order 'cà phê sữa đá'. Very cheap, cash only.","uk":"Ідіть рано-вранці, щоб побачити вугільні печі в роботі; замовте «cà phê sữa đá». Дуже дешево, лише готівка."},"hours":"06:00–18:00","website":"","images":["https://media.urbanistnetwork.com/saigoneer/article-images/legacy/bvjIfO6b.jpg","https://media.urbanistnetwork.com/saigoneer/article-images/legacy/bvjIfO6h.jpg"]},{"id":"cafe-apartment-14-ton-that-dam","region":"hcmc","area":"District 1 (Saigon Ward)","category":"cafes","name":"14 Ton That Dam Cafe Apartments","nameVi":"Chung Cư 14 Tôn Thất Đạm","lat":10.7697,"lng":106.70412,"address":"14 Tôn Thất Đạm, Sài Gòn Ward (District 1), HCMC","rating":4.2,"googleRating":4.5,"price":2,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Vietnam Coracle feature; quieter alternative to 42 Nguyen Hue","desc":{"en":"A crumbling old apartment block in the financial district hiding quirky cafés (Things, Mockingbird), vintage shops and the Snuffbox speakeasy behind its grimy stairwells.","uk":"Обшарпаний старий житловий блок у діловому районі, де за пошарпаними сходами ховаються дивакуваті кав'ярні (Things, Mockingbird), вінтажні крамнички та спікізі Snuffbox."},"tip":{"en":"Climb all the floors — Things Café's living-room vibe is the gem. Snuffbox opens in the evening for cocktails.","uk":"Пройдіться всіма поверхами — справжня перлина тут Things Café з атмосферою вітальні. Snuffbox відкривається ввечері для коктейлів."},"hours":"08:00–22:00 (varies by café)","website":"","images":["https://cms.vietnamcoracle.com/wp-content/uploads/2018/10/IMG_5496-copy-blog-1024x768.jpg"]},{"id":"the-old-compass-cafe","region":"hcmc","area":"District 1 (Saigon Ward)","category":"cafes","name":"The Old Compass Cafe","nameVi":"The Old Compass Cafe & Bar","lat":10.77499,"lng":106.7006,"address":"3F, 63/11 Pasteur (alley), Sài Gòn Ward (District 1), HCMC","rating":4.3,"googleRating":4.6,"price":2,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Book-lined hidden café; live music on Friday nights","desc":{"en":"A bookish, wood-panelled hideaway up three flights of stairs in a Pasteur Street alley — coffee and laptops by day, cocktails and live acoustic music by night.","uk":"Затишна схованка з книжками та дерев'яними панелями на третьому поверсі в провулку вулиці Пастер: удень — кава й ноутбуки, увечері — коктейлі та живий акустичний концерт."},"tip":{"en":"Combine with Phở Minh in the same alley complex for a perfect hẻm breakfast-and-coffee combo.","uk":"Поєднайте з Phở Minh у сусідньому провулку — ідеальний сніданок із кавою в стилі «хем»."},"hours":"08:00–23:00","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/e/ec/Ca_Phe_Sua_Da.jpg/960px-Ca_Phe_Sua_Da.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/f/fc/C%C3%80_PH%C3%8A_S%E1%BB%AEA_PHA_PHIN.jpg/960px-C%C3%80_PH%C3%8A_S%E1%BB%AEA_PHA_PHIN.jpg"]},{"id":"layla-eatery-bar","region":"hcmc","area":"District 1 (Saigon Ward)","category":"bars","name":"Layla Eatery & Bar","nameVi":"Layla Eatery & Bar","lat":10.77541,"lng":106.70415,"address":"2F, 63 Đông Du, Sài Gòn Ward (District 1), HCMC","rating":4.6,"googleRating":4.8,"price":3,"mustSee":true,"hiddenGem":false,"viral":false,"hype":"Tatler Best 20 Bars Vietnam 2025 & 2026; Asia-Pacific bar-scene favourite","desc":{"en":"A buzzing, 11-metre-bar cocktail hall upstairs on Đông Du with cocktails on tap, a smoking terrace and one of the best happy hours in town.","uk":"Гамірний коктейль-бар з 11-метровою стійкою на другому поверсі на Донг Зу: коктейлі на крані, тераса для курців і один із найкращих «щасливих годин» у місті."},"tip":{"en":"Happy hour runs until 8 pm; order the bacon tater tots with a tap cocktail.","uk":"«Щаслива година» триває до 20:00; замовте картопляні тоти з беконом і коктейль із крана."},"hours":"16:00–02:00","website":"","images":["https://www.the50.com/discovery/filestore/jpg/Layla%20Eatery%20_%20Bar-Ho%20Chi%20Minh%20City-Vietnam-1.jpg","https://www.the50.com/discovery/filestore/jpg/Layla%20Eatery%20_%20Bar-Ho%20Chi%20Minh%20City-Vietnam-2.jpg"]},{"id":"stir-saigon","region":"hcmc","area":"District 1 (Ben Thanh)","category":"bars","name":"Stir – Modern Classic Cocktail","nameVi":"STIR – Modern Classic Cocktail","lat":10.77375,"lng":106.69805,"address":"1F, 136 Lê Thánh Tôn, Bến Thành Ward (District 1), HCMC","rating":4.6,"googleRating":4.7,"price":3,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Asia's 50 Best Bars 51–100: #58 (2024), #61 (2025), #84 (2026)","desc":{"en":"A sleek retro bar by Bến Thành market with a wall of 80+ house-made ingredients, reworking Vietnamese street drinks into modern classics.","uk":"Стильний ретро-бар біля ринку Бен Тхань зі стіною з понад 80 домашніх інгредієнтів, де в'єтнамські вуличні напої переосмислюють у сучасну класику."},"tip":{"en":"Sit at the long bar and ask for something built on Vietnamese street flavours (kumquat, rau răm, cold-brew).","uk":"Сідайте за довгу стійку й попросіть щось на основі вуличних в'єтнамських смаків (кумкват, рау рам, колд-брю)."},"hours":"18:00–01:00","website":"https://www.instagram.com/stir.saigon/","images":["https://www.the50.com/discovery/filestore/jpg/Stir_fb.jpg"]},{"id":"the-enigma-mansion","region":"hcmc","area":"District 1 (Saigon Ward)","category":"bars","name":"The Enigma Mansion","nameVi":"The Enigma Mansion","lat":10.78104,"lng":106.70713,"address":"5H Tôn Đức Thắng, Sài Gòn Ward (District 1), HCMC","rating":4.7,"googleRating":null,"price":3,"mustSee":true,"hiddenGem":false,"viral":false,"hype":"Asia's 50 Best Bars #55 (2026, biggest climber), #93 (2025); Tatler Vietnam Bar of the Year 2025","desc":{"en":"Saigon's highest-ranked bar, now set in a moody colonial-era mansion by the river, pouring inventive cocktails built on Vietnamese ferments like rice wine.","uk":"Найвище оцінений бар Сайгона, що тепер розташований в атмосферному колоніальному особняку біля річки, з винахідливими коктейлями на в'єтнамських ферментах на кшталт рисового вина."},"tip":{"en":"Reserve on weekends; dress smart-casual.","uk":"У вихідні бронюйте; дрес-код — смарт-кежуал."},"hours":"18:00–02:00","website":"https://www.facebook.com/theenigma.saigon","images":["https://www.the50.com/discovery/filestore/jpg/TheEnigmaMansionDrinkFB.jpg","https://www.the50.com/discovery/filestore/jpg/TheEnigmaMansionInterior1.jpg","https://www.the50.com/discovery/filestore/jpg/TheEnigmaMansionDrink1.jpg"]},{"id":"summer-experiment","region":"hcmc","area":"District 1 (Ben Thanh)","category":"bars","name":"Summer Experiment","nameVi":"Summer Experiment","lat":10.77463,"lng":106.69801,"address":"2F, 77–79 Lý Tự Trọng, Bến Thành Ward (District 1), HCMC","rating":4.6,"googleRating":4.9,"price":2,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"First Saigon bar on Asia's 50 Best Bars extended list (#77, 2021); Tatler Best 20 Bars Vietnam 2026","desc":{"en":"A leafy, sustainability-minded cocktail bar hidden on the second floor of an old building, with living walls and drinks using garden-grown herbs and fermentations.","uk":"Зелений бар з екологічним підходом, захований на другому поверсі старого будинку: живі стіни, коктейлі з власновирощеними травами та ферментаціями."},"tip":{"en":"Look for the narrow staircase; cocktails are surprisingly affordable — try the seasonal menu.","uk":"Шукайте вузькі сходи; коктейлі напрочуд доступні за ціною — спробуйте сезонне меню."},"hours":"17:00–00:00","website":"","images":["https://www.the50.com/discovery/filestore/jpg/Summer%20Experiment-Ho%20Chi%20Minh%20City-Vietnam-2.jpg","https://www.the50.com/discovery/filestore/jpg/Summer%20Experiment-Ho%20Chi%20Minh%20City-Vietnam-3.jpg","https://thedotmagazine.com/wp-content/uploads/2019/11/Summer.jpeg"]},{"id":"firkin-bar","region":"hcmc","area":"District 1 (Saigon Ward)","category":"bars","name":"Firkin Bar","nameVi":"Firkin Bar","lat":10.77585,"lng":106.70496,"address":"20 Mạc Thị Bưởi, Sài Gòn Ward (District 1), HCMC","rating":4.5,"googleRating":4.7,"price":3,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Tatler Best 20 Bars Vietnam 2025 & 2026; hundreds of whiskies","desc":{"en":"A tiny, dark-wood whisky den behind an unmarked door off Đồng Khởi, with hundreds of rare single malts and bourbons and a sharp bespoke-cocktail program.","uk":"Крихітний віскі-бар із темного дерева за непримітними дверима біля Донг Кхой: сотні рідкісних односолодових і бурбонів та чудові авторські коктейлі."},"tip":{"en":"Tell the bartender your preferred flavours and let them build a drink; happy hour early evening.","uk":"Розкажіть бармену, які смаки любите, і довіртеся йому; «щаслива година» — рано ввечері."},"hours":"17:00–01:00","website":"","images":["https://www.asia-bars.com/wp-content/uploads/2021/01/FBar_0284Formula-20.jpg","https://www.asia-bars.com/wp-content/uploads/2021/01/FBar_0303Bronze-Bullet.jpg"]},{"id":"drinking-and-healing","region":"hcmc","area":"District 1 (Saigon Ward)","category":"bars","name":"Drinking & Healing","nameVi":"Drinking & Healing","lat":10.77051,"lng":106.70446,"address":"25 Hồ Tùng Mậu, Sài Gòn Ward (District 1), HCMC","rating":4.3,"googleRating":4.4,"price":2,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"50 Best Discovery listing; speakeasy in a colonial building","desc":{"en":"A Brooklyn-styled speakeasy tucked into a colonial building near the Bitexco tower, with a playful, herb-driven cocktail list and a loyal local crowd.","uk":"Спікізі в бруклінському стилі в колоніальній будівлі біля вежі Bitexco з грайливою трав'яною коктейльною картою та вірною місцевою публікою."},"tip":{"en":"Opening days are limited (often Thu–Sun) — check Instagram before you go.","uk":"Працює не щодня (часто чт–нд) — перевірте Instagram перед візитом."},"hours":"19:00–01:00 (Thu–Sun)","website":"","images":["https://www.the50.com/discovery/filestore/jpg/Drinking%20_%20Healing-Ho%20Chi%20Minh-Vietnam-1.jpg","https://www.the50.com/discovery/filestore/jpg/Drinking%20_%20Healing-Ho%20Chi%20Minh-Vietnam-2.jpg"]},{"id":"nhau-nhau","region":"hcmc","area":"District 1 (Saigon Ward)","category":"bars","name":"Nhau Nhau","nameVi":"Nhậu Nhậu","lat":10.77175,"lng":106.70292,"address":"89 Tôn Thất Đạm (upper floor, above Anan), Sài Gòn Ward (District 1), HCMC","rating":4.3,"googleRating":4.3,"price":2,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Anan Saigon's bar; once on Asia's 50 Best Bars extended list","desc":{"en":"A retro 'nhậu'-culture cocktail bar from the Anan team, with a balcony overlooking District 1's last wet market and drinks riffing on phở and street snacks.","uk":"Ретро-бар у дусі в'єтнамської культури «ньяу» від команди Anan з балконом над останнім мокрим ринком 1-го округу та коктейлями з мотивами фо й вуличних закусок."},"tip":{"en":"Order the phở cocktail; perfect pre- or post-dinner stop if you eat at Anan downstairs.","uk":"Замовте коктейль «фо»; ідеально до або після вечері в Anan поверхом нижче."},"hours":"17:00–00:00","website":"","images":["https://thesmartlocal.com/vietnam/wp-content/uploads/2021/01/nhau-nhau-bar.jpg","https://www.the50.com/discovery/filestore/jpg/Nhau%20Nhau%20Pho%20Bar-Ho%20Chi%20Minh%20City-Vietnam-1.jpg"]},{"id":"chill-skybar","region":"hcmc","area":"District 1 (Ben Thanh)","category":"bars","name":"Chill Skybar","nameVi":"Chill Skybar","lat":10.77057,"lng":106.69438,"address":"26F, AB Tower, 76A Lê Lai, Bến Thành Ward (District 1), HCMC","rating":4.3,"googleRating":4.4,"price":4,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Saigon's best-known party rooftop; Instagram sunset hotspot","desc":{"en":"A glossy 26th-floor rooftop with 360° skyline views, DJs and a see-and-be-seen crowd — the city's classic big-night-out sky bar.","uk":"Гламурний руфтоп на 26-му поверсі з краєвидом на місто на 360°, діджеями та модною публікою — класичний скайбар для великого вечора."},"tip":{"en":"Strict dress code (no shorts or flip-flops for men). Arrive at 5:30–6 pm for sunset and happy hour.","uk":"Суворий дрес-код (чоловікам — жодних шортів і в'єтнамок). Приходьте о 17:30–18:00 на захід сонця й «щасливу годину»."},"hours":"17:30–02:00","website":"https://chillsaigon.com","images":["https://chillsaigon.com/assets/uploads/2026/10/1793013888850_6590822284319630923_g2401747736357764968_d68138255734baced18c295d9795551a-1024x1024.jpg"]},{"id":"social-club-rooftop","region":"hcmc","area":"District 3 (Xuan Hoa)","category":"bars","name":"Social Club Rooftop Bar","nameVi":"Social Club Rooftop Bar","lat":10.78242,"lng":106.69733,"address":"Rooftop, Hôtel des Arts Saigon (MGallery), 76–78 Nguyễn Thị Minh Khai, Xuân Hòa Ward (District 3), HCMC","rating":4.5,"googleRating":4.6,"price":3,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Rooftop infinity pool bar on every 'best rooftops' list","desc":{"en":"A chic rooftop on top of the art-deco-styled Hôtel des Arts, with an infinity pool, city-light views and polished cocktails — more relaxed than the party sky bars.","uk":"Шикарний руфтоп на даху Hôtel des Arts у стилі ар-деко з інфініті-басейном, вогнями міста та вишуканими коктейлями — спокійніший за тусовочні скайбари."},"tip":{"en":"Happy hour (roughly 5–7 pm) is great value; book a sunset table at weekends.","uk":"«Щаслива година» (приблизно 17–19) дуже вигідна; у вихідні бронюйте столик на захід сонця."},"hours":"16:00–00:00","website":"https://www.hoteldesartssaigon.com","images":["https://d2e5ushqwiltxm.cloudfront.net/wp-content/uploads/sites/92/2024/09/13035519/Social-Club-Rooftop-Bar-1-min-1024x683.jpg","https://d2e5ushqwiltxm.cloudfront.net/wp-content/uploads/sites/92/2017/09/28082357/Rooftop-Pool-Bar2-nws-touch-1024x695.jpg"]},{"id":"saigon-saigon-rooftop","region":"hcmc","area":"District 1 (Saigon Ward)","category":"bars","name":"Saigon Saigon Rooftop Bar","nameVi":"Saigon Saigon Rooftop Bar","lat":10.77632,"lng":106.70353,"address":"9F, Caravelle Saigon, 19–23 Công trường Lam Sơn, Sài Gòn Ward (District 1), HCMC","rating":4.2,"googleRating":4.0,"price":3,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Legendary Vietnam War-era correspondents' bar","desc":{"en":"The historic rooftop of the Caravelle hotel, where war correspondents once watched the war from their bar stools; today it's live music and views over the Opera House.","uk":"Історичний руфтоп готелю Caravelle, де колись воєнні кореспонденти спостерігали за війною просто з барних стільців; сьогодні тут жива музика та вид на Оперний театр."},"tip":{"en":"Come for happy hour and the live band; no strict dress code, but smart-casual fits.","uk":"Приходьте на «щасливу годину» та живий гурт; суворого дрес-коду немає, але смарт-кежуал доречний."},"hours":"16:00–00:00","website":"https://www.caravellehotel.com","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/1/13/Caravelle_Hotel_Saigon_2013.jpg/960px-Caravelle_Hotel_Saigon_2013.jpg"]},{"id":"pasteur-street-brewing","region":"hcmc","area":"District 1 (Saigon Ward)","category":"bars","name":"Pasteur Street Brewing Co.","nameVi":"Pasteur Street Brewing Co.","lat":10.77518,"lng":106.70103,"address":"144/3 Pasteur (upstairs in the alley), Sài Gòn Ward (District 1), HCMC","rating":4.5,"googleRating":4.8,"price":2,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Pioneer of Vietnamese craft beer (since 2014); award-winning Jasmine IPA","desc":{"en":"The original upstairs taproom of Vietnam's craft-beer pioneer, pouring a dozen-plus taps built on local ingredients like jasmine, passion fruit and Vietnamese coffee.","uk":"Оригінальний тапрум піонера в'єтнамського крафтового пива на другому поверсі: понад десяток кранів із пивом на місцевих інгредієнтах — жасмин, маракуя, в'єтнамська кава."},"tip":{"en":"Get a tasting flight and include the Jasmine IPA and the Coffee Porter.","uk":"Візьміть дегустаційний сет і обов'язково спробуйте Jasmine IPA та Coffee Porter."},"hours":"11:00–23:00","website":"https://pasteurstreet.com","images":["https://pasteurstreet.com/wp-content/uploads/240405_Pasteur_BiaHoaNhai-2-copy.jpg","https://pasteurstreet.com/wp-content/uploads/coffee-porter.jpg"]},{"id":"heart-of-darkness-brewery","region":"hcmc","area":"District 1 (Saigon Ward)","category":"bars","name":"Heart of Darkness Craft Brewery","nameVi":"Heart of Darkness Craft Brewery","lat":10.77971,"lng":106.7029,"address":"31D Lý Tự Trọng, Sài Gòn Ward (District 1), HCMC","rating":4.4,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"One of Asia's most respected craft breweries; 20+ taps","desc":{"en":"A dark, industrial taproom with 20-odd taps of hazy IPAs, sours and imperial stouts named after Conrad's novel — Saigon's craft-beer heavyweight.","uk":"Темний індустріальний тапрум із двома десятками кранів — мутні IPA, кислі ейли та імперські стаути з назвами за романом Конрада. Важковаговик сайгонського крафту."},"tip":{"en":"Ask for small tasters before committing; the hazy IPAs are the stars.","uk":"Попросіть невеликі дегустаційні порції, перш ніж обрати; головні зірки — мутні IPA."},"hours":"11:00–00:00","website":"https://heartofdarknessbrewery.com","images":["https://www.rustycompass.com/uploads/destinations/heart-of-darkness-craft-brewery-saigon-0418-2-of-8_15244052050.jpg","https://www.rustycompass.com/uploads/destinations/heart-of-darkness-craft-brewery-saigon-0418-4-of-8_15244052053.jpg"]},{"id":"bui-vien-walking-street","region":"hcmc","area":"District 1 (Pham Ngu Lao)","category":"experiences","name":"Bui Vien Walking Street","nameVi":"Phố Đi Bộ Bùi Viện","lat":10.76735,"lng":106.69388,"address":"Bùi Viện, Bến Thành Ward (District 1), HCMC","rating":3.8,"googleRating":4.3,"price":1,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Saigon's backpacker party street; a TikTok/YouTube nightlife staple","desc":{"en":"Saigon's loud, neon-soaked backpacker strip: bars blasting competing sound systems, street performers, plastic stools full of cheap beer and people-watching until late.","uk":"Гучна, залита неоном вулиця бекпекерів: бари з колонками, що перекрикують одна одну, вуличні артисти, пластикові стільчики з дешевим пивом і спостереження за людьми до глибокої ночі."},"tip":{"en":"Goes pedestrian from about 7 pm (busiest Fri–Sun). Watch your phone and wallet, and check beer prices before ordering.","uk":"Стає пішохідною приблизно з 19:00 (найлюдніше пт–нд). Стежте за телефоном і гаманцем, уточнюйте ціну пива перед замовленням."},"hours":"19:00–02:00","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/7/76/Bui_Vien_Street%2C_Ho_Chi_Minh_City%2C_at_night%2C_2023_%2805%29.jpg/960px-Bui_Vien_Street%2C_Ho_Chi_Minh_City%2C_at_night%2C_2023_%2805%29.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/5/5b/Bui_Vien_Street%2C_Ho_Chi_Minh_City%2C_at_night%2C_2023_%2807%29.jpg/960px-Bui_Vien_Street%2C_Ho_Chi_Minh_City%2C_at_night%2C_2023_%2807%29.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/f/ff/Bui_Vien_Street%2C_Ho_Chi_Minh_City%2C_at_night%2C_2023_%2813%29.jpg/960px-Bui_Vien_Street%2C_Ho_Chi_Minh_City%2C_at_night%2C_2023_%2813%29.jpg"]},{"id":"xo-tours-night-food-tour","region":"hcmc","area":"Citywide (hotel pick-up, District 1)","category":"experiences","name":"XO Tours Motorbike Night Food Tour","nameVi":"XO Tours – Tour Ẩm Thực Đêm Bằng Xe Máy","lat":10.776,"lng":106.701,"address":"Hotel pick-up in central HCMC (Districts 1/3); tour visits Districts 4, 5, 8, 10","rating":4.9,"googleRating":null,"price":4,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Vietnam's first all-female motorbike tour company (2010); áo dài-clad riders; perennial TripAdvisor Travellers' Choice","desc":{"en":"Ride pillion behind áo dài-clad local women through Saigon's night traffic to 10+ dishes in districts tourists rarely reach — snails, grilled seafood, broken rice and more.","uk":"Мчіть на задньому сидінні мотобайка за місцевими дівчатами в аозаях крізь нічний трафік Сайгона й скуштуйте понад 10 страв у районах, куди туристи майже не доїжджають: равлики, морепродукти на грилі, ком там тощо."},"tip":{"en":"Book a few days ahead (around US$75–90 incl. all food and beer); come very hungry and tell them about allergies.","uk":"Бронюйте за кілька днів (близько 75–90 дол. США з їжею та пивом); приходьте дуже голодними й попередьте про алергії."},"hours":"Evening tours ~17:30–22:00","website":"https://xotours.vn","images":["https://xotours.b-cdn.net/wp-content/uploads/XO-Banner.png"]},{"id":"hoa-tuc-cooking-class","region":"hcmc","area":"District 1 (Saigon Ward)","category":"experiences","name":"Saigon Cooking Class at Hoa Tuc","nameVi":"Lớp Học Nấu Ăn Hoa Túc","lat":10.7785,"lng":106.70377,"address":"74/7 Hai Bà Trưng (old opium-factory courtyard), Sài Gòn Ward (District 1), HCMC","rating":4.6,"googleRating":4.5,"price":3,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Run by Michelin Selected restaurant Hoa Túc; optional Bến Thành market tour","desc":{"en":"A hands-on cooking class in the courtyard of a former French opium refinery: shop at Bến Thành market with a chef, then cook and eat three or four classic southern dishes.","uk":"Практичний кулінарний клас у дворику колишньої французької опіумної фабрики: закупи з шефом на ринку Бен Тхань, а потім готуєте й з'їдаєте три-чотири класичні південні страви."},"tip":{"en":"Choose the morning class with market tour; book online a few days ahead.","uk":"Обирайте ранковий клас з екскурсією ринком; бронюйте онлайн за кілька днів."},"hours":"Morning & afternoon classes","website":"https://hoatuc.com","images":["https://hoatuc.com/wp-content/uploads/2024/03/CHOA0523-1.jpg","https://prod-pics.guide.michelin.com/api/public/content/e5eb491180a145ca89d22a61734860fa.png","https://prod-pics.guide.michelin.com/api/public/content/2c074983c1804f2fb73da8bc91b39836.png"]},{"id":"vinh-khanh-food-street","region":"hcmc","area":"District 4 (Khanh Hoi)","category":"experiences","name":"Vinh Khanh Food Street","nameVi":"Phố Ẩm Thực Vĩnh Khánh","lat":10.7615,"lng":106.7035,"address":"Vĩnh Khánh St (between Hoàng Diệu and Tôn Đản), Khánh Hội Ward (District 4), HCMC","rating":4.4,"googleRating":null,"price":1,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Official HCMC food street since 2018; TikTok snail-and-seafood hotspot","desc":{"en":"Saigon's snail-and-seafood street: a kilometre of sizzling grills, tanks of shellfish and crowds on plastic stools, buzzing with locals every night.","uk":"Вулиця равликів і морепродуктів: кілометр шкварчащих грилів, акваріуми з молюсками й натовпи на пластикових стільчиках — щовечора тут вирує місцеве життя."},"tip":{"en":"Come after 6 pm with a group; hop between stalls (Ốc Oanh, Ốc Đào 2) and finish with chè. Agree prices for seafood by weight first.","uk":"Приходьте після 18:00 компанією; переходьте від закладу до закладу (Ốc Oanh, Ốc Đào 2) і завершіть десертом че. Ціну морепродуктів на вагу узгоджуйте заздалегідь."},"hours":"16:00–00:00","website":"","images":["https://media.urbanistnetwork.com/saigoneer/article-images/legacy/SnutHL0b.jpg","https://media.urbanistnetwork.com/saigoneer/article-images/legacy/SnutHL0h.jpg"]},{"id":"notre-dame-cathedral-saigon","region":"hcmc","area":"District 1","category":"sights","name":"Notre-Dame Cathedral Basilica of Saigon","nameVi":"Nhà thờ Chính tòa Đức Bà Sài Gòn","lat":10.77974,"lng":106.69905,"address":"01 Công xã Paris, Bến Nghé (District 1)","rating":4.5,"googleRating":4.4,"price":0,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Built 1863–1880 with bricks shipped from Marseille; decade-long restoration crowned by new spire crosses in March 2026","desc":{"en":"Twin 58-metre bell towers of red Marseille brick rise over Paris Square — Saigon's most recognisable building, freshly emerging from a ten-year restoration.","uk":"Дві 58-метрові дзвіниці з червоної марсельської цегли над Паризькою площею — найвпізнаваніша будівля Сайгона, що саме виходить із десятирічної реставрації."},"tip":{"en":"Restoration work may still limit interior access in 2027 — check before going; the exterior is best at golden hour, combined with the Post Office across the square.","uk":"У 2027 році доступ усередину ще може бути обмежений через реставрацію — уточніть заздалегідь; фасад найкращий у «золоту годину», разом із Поштамтом через площу."},"hours":"Exterior 24h; interior at Mass times / limited","website":"https://en.wikipedia.org/wiki/Notre-Dame_Cathedral_Basilica_of_Saigon","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/Bas%C3%ADlica_de_Nuestra_Se%C3%B1ora%2C_Ciudad_Ho_Chi_Minh%2C_Vietnam%2C_2013-08-14%2C_DD_03.JPG/960px-Bas%C3%ADlica_de_Nuestra_Se%C3%B1ora%2C_Ciudad_Ho_Chi_Minh%2C_Vietnam%2C_2013-08-14%2C_DD_03.JPG"]},{"id":"saigon-central-post-office","region":"hcmc","area":"District 1","category":"sights","name":"Saigon Central Post Office","nameVi":"Bưu điện Trung tâm Sài Gòn","lat":10.77996,"lng":106.69999,"address":"2 Công xã Paris, Bến Nghé (District 1)","rating":4.5,"googleRating":4.4,"price":0,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Gustave Eiffel-era colonial hall (1886–1891); often ranked among the world's most beautiful post offices","desc":{"en":"A vaulted French-colonial hall with green iron arches, hand-painted 1890s maps and a giant portrait of Ho Chi Minh — still a working post office.","uk":"Склепінчаста колоніальна зала із зеленими чавунними арками, мальованими мапами 1890-х і величезним портретом Хо Ші Міна — і досі діюча пошта."},"tip":{"en":"Send a postcard home from the counters inside; come before 9:00 to photograph the hall without tour groups.","uk":"Надішліть листівку додому просто звідси; приходьте до 9:00, щоб сфотографувати залу без туристичних груп."},"hours":"07:00–19:00","website":"https://en.wikipedia.org/wiki/Saigon_Central_Post_Office","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Saigon_Central_Post_Office_%2852681461470%29.jpg/960px-Saigon_Central_Post_Office_%2852681461470%29.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Saigon_Central_Post_Office_Lobby.jpg/960px-Saigon_Central_Post_Office_Lobby.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/1/1f/City_Post_Office_2020_IMG_4343.jpg/960px-City_Post_Office_2020_IMG_4343.jpg"]},{"id":"independence-palace","region":"hcmc","area":"District 1","category":"sights","name":"Independence Palace (Reunification Palace)","nameVi":"Dinh Độc Lập","lat":10.77703,"lng":106.69549,"address":"135 Nam Kỳ Khởi Nghĩa, Bến Thành (District 1)","rating":4.6,"googleRating":4.5,"price":1,"mustSee":true,"hiddenGem":false,"viral":false,"hype":"Special National Monument; where NVA tank No. 843 crashed the gates on 30 April 1975","desc":{"en":"A 1960s modernist palace frozen in time: retro state rooms, a rooftop helipad and a warren of war-command bunkers, with the tanks that ended the war on the lawn.","uk":"Модерністський палац 1960-х, застиглий у часі: ретро-зали, вертолітний майданчик на даху й лабіринт командних бункерів, а на газоні — танки, що завершили війну."},"tip":{"en":"Adult ticket ~80,000 VND (palace + exhibition, from May 2026); the basement bunker is the highlight — allow 1.5–2 hours.","uk":"Квиток для дорослих ~80 000 донгів (палац + виставка, з травня 2026); найцікавіше — бункер у підвалі, закладіть 1,5–2 години."},"hours":"08:00–16:30","website":"https://dinhdoclap.gov.vn/en/","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/20190923_Independence_Palace-10.jpg/960px-20190923_Independence_Palace-10.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Palacio_de_la_Reunificaci%C3%B3n%2C_Ciudad_Ho_Chi_Minh%2C_Vietnam%2C_2013-08-14%2C_DD_03.JPG/960px-Palacio_de_la_Reunificaci%C3%B3n%2C_Ciudad_Ho_Chi_Minh%2C_Vietnam%2C_2013-08-14%2C_DD_03.JPG"]},{"id":"saigon-opera-house","region":"hcmc","area":"District 1","category":"sights","name":"Saigon Opera House & AO Show","nameVi":"Nhà hát Thành phố Hồ Chí Minh","lat":10.77674,"lng":106.70325,"address":"7 Công trường Lam Sơn, Bến Nghé (District 1)","rating":4.4,"googleRating":4.6,"price":2,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"1900 Flamboyant-style Municipal Theatre; home of Lune Production's acclaimed bamboo-circus AO Show","desc":{"en":"A wedding-cake Belle Époque theatre at the head of Lam Son Square; inside, the AO Show tumbles through Mekong village life with bamboo poles and baskets.","uk":"Театр у стилі Бель Епок, схожий на весільний торт, на чолі площі Лам Шон; усередині AO Show розповідає про життя дельти Меконгу за допомогою бамбукових жердин і кошиків."},"tip":{"en":"There are no regular daytime tours — the way inside is a show; AO Show runs most evenings at 18:00 (≈800k–1.75m VND), book on luneproduction.com.","uk":"Регулярних денних екскурсій немає — потрапити всередину можна лише на виставу; AO Show іде майже щовечора о 18:00 (≈800 тис.–1,75 млн донгів), бронюйте на luneproduction.com."},"hours":"Exterior 24h; shows usually 18:00","website":"https://luneproduction.com","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Lascar_Municipal_Theatre_%284608017466%29.jpg/960px-Lascar_Municipal_Theatre_%284608017466%29.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Ho_Chi_Minh_City_Opera_House.jpg/960px-Ho_Chi_Minh_City_Opera_House.jpg"]},{"id":"nguyen-hue-walking-street","region":"hcmc","area":"District 1","category":"sights","name":"Nguyen Hue Walking Street & City Hall","nameVi":"Phố đi bộ Nguyễn Huệ","lat":10.77425,"lng":106.70335,"address":"Nguyễn Huệ Boulevard, from City Hall to Bạch Đằng wharf (District 1)","rating":4.5,"googleRating":4.7,"price":0,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Saigon's main promenade; Tet Flower Street, musical fountain shows and New Year countdowns go viral every year","desc":{"en":"A 670-metre pedestrian boulevard running from the lit-up colonial City Hall and Ho Chi Minh statue to the river — Saigon's evening living room of buskers, skaters and families.","uk":"670-метровий пішохідний бульвар від підсвіченої колоніальної Ратуші та пам'ятника Хо Ші Міну до річки — вечірня «вітальня» Сайгона з вуличними музикантами, скейтерами й родинами."},"tip":{"en":"Come after 19:00 on Friday–Sunday when the fountain lights up and crowds peak; during Tet (late Jan/Feb) it becomes the famous Flower Street.","uk":"Приходьте після 19:00 у п'ятницю–неділю, коли вмикається фонтан і найбільше людей; на Тет (кінець січня/лютий) тут влаштовують знамениту Вулицю квітів."},"hours":"24h (liveliest 18:00–23:00)","website":"https://en.wikipedia.org/wiki/Nguy%E1%BB%85n_Hu%E1%BB%87_Boulevard","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/7/75/Nguyen_Hue_Street_2020.jpg/960px-Nguyen_Hue_Street_2020.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/Ho_Chi_Minh_City%2C_City_Hall%2C_2020-01_CN-02.jpg/960px-Ho_Chi_Minh_City%2C_City_Hall%2C_2020-01_CN-02.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/d/db/20180413_215356Nguy%E1%BB%85n_Hu%E1%BB%87_Walking_Street.jpg/960px-20180413_215356Nguy%E1%BB%85n_Hu%E1%BB%87_Walking_Street.jpg"]},{"id":"saigon-skydeck-bitexco","region":"hcmc","area":"District 1","category":"sights","name":"Saigon Skydeck (Bitexco Financial Tower)","nameVi":"Đài quan sát Saigon Skydeck – Tòa tháp Bitexco","lat":10.77172,"lng":106.70453,"address":"36 Hồ Tùng Mậu / 2 Hải Triều, Bến Nghé (District 1)","rating":4.1,"googleRating":4.4,"price":2,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Lotus-bud tower (2010) with a helipad that juts from the 52nd floor; was Vietnam's tallest until 2011","desc":{"en":"A 49th-floor 360° observation deck in the lotus-shaped Bitexco tower, looking straight down the Saigon River bend and across to the new Thu Thiem skyline.","uk":"Оглядовий майданчик на 49-му поверсі вежі Bitexco у формі бутона лотоса з видом на вигин річки Сайгон і нову панораму Тху Тхієм."},"tip":{"en":"Still operating (≈09:30–21:30). For the same view with a drink, the EON51 bar a few floors up is often better value than the deck ticket.","uk":"Працює (≈09:30–21:30). Той самий краєвид із напоєм у барі EON51 на кілька поверхів вище часто вигідніший за квиток на майданчик."},"hours":"09:30–21:30","website":"https://www.saigonskydeck.com","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/c/c4/DJI_0550-HDR-Pano_Bitexco_Financial_Tower.jpg/960px-DJI_0550-HDR-Pano_Bitexco_Financial_Tower.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Ho_Chi_Minh_City_from_the_Saigon_Skydeck.jpg/960px-Ho_Chi_Minh_City_from_the_Saigon_Skydeck.jpg"]},{"id":"landmark-81-skyview","region":"hcmc","area":"Binh Thanh","category":"sights","name":"Landmark 81 SkyView","nameVi":"Landmark 81 SkyView","lat":10.79503,"lng":106.72191,"address":"720A Điện Biên Phủ, Vinhomes Central Park (Bình Thạnh)","rating":4.4,"googleRating":4.6,"price":2,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Vietnam's tallest building (461 m, 2018); SkyView glass-floor deck on floors 79–81 is an Instagram staple","desc":{"en":"Vietnam's tallest skyscraper, shaped like a bundle of bamboo; the SkyView deck near the top has glass-floor ledges and sunset views over the whole riverside city.","uk":"Найвищий хмарочос В'єтнаму у формі пучка бамбуку; оглядовий майданчик SkyView біля вершини має скляну підлогу й захід сонця над усім прибережним містом."},"tip":{"en":"Tickets ≈ US$16+ (cheaper online, weekdays); arrive ~1 hour before sunset, then stroll the riverside Vinhomes Central Park below.","uk":"Квитки ≈ від 16 доларів (дешевше онлайн і в будні); приходьте за годину до заходу сонця, а потім прогуляйтеся набережним парком Vinhomes Central Park унизу."},"hours":"≈10:00–22:00","website":"https://en.wikipedia.org/wiki/Landmark_81","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/The_Landmark_81_at_night.jpg/960px-The_Landmark_81_at_night.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Landmark_81_view_from_Saigon_River.jpg/960px-Landmark_81_view_from_Saigon_River.jpg"]},{"id":"saigon-book-street","region":"hcmc","area":"District 1","category":"sights","name":"Nguyen Van Binh Book Street","nameVi":"Đường sách Nguyễn Văn Bình","lat":10.78057,"lng":106.69969,"address":"Nguyễn Văn Bình street, beside the Central Post Office (District 1)","rating":4.3,"googleRating":4.6,"price":0,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Car-free street of bookshops and kiosks opened in 2016","desc":{"en":"A shady, car-free lane of bookshops, vintage-poster stalls and little cafés tucked behind the Post Office — a calm breather in the busy centre.","uk":"Тінистий пішохідний провулок із книгарнями, лотками зі старими плакатами та маленькими кав'ярнями за Поштамтом — спокійна перерва в галасливому центрі."},"tip":{"en":"Look for English-language Vietnam history titles and propaganda-art postcards; pairs naturally with the Cathedral and Post Office.","uk":"Шукайте англомовні книжки з історії В'єтнаму та листівки з пропагандистськими плакатами; зручно поєднати з Собором і Поштамтом."},"hours":"08:00–22:00","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Nguyen_Van_Binh_Street_%2852681309899%29.jpg/960px-Nguyen_Van_Binh_Street_%2852681309899%29.jpg"]},{"id":"ba-son-bridge-thu-thiem-views","region":"hcmc","area":"District 1 / Thu Thiem","category":"sights","name":"Ba Son Bridge & Thu Thiem Riverside Views","nameVi":"Cầu Ba Son & bờ sông Thủ Thiêm","lat":10.78041,"lng":106.70851,"address":"Ba Son Bridge (Thủ Thiêm 2), Tôn Đức Thắng – Thủ Thiêm","rating":4.4,"googleRating":null,"price":0,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Cable-stayed bridge opened 2022; its sunset and blue-hour skyline shots flood TikTok and Instagram","desc":{"en":"The single-pylon Ba Son Bridge links downtown with the Thu Thiem riverside park, from where the whole District 1 skyline and Landmark 81 line up across the water.","uk":"Однопілонний міст Ба Шон з'єднує центр із набережним парком Тху Тхієм, звідки вся панорама Першого району та Landmark 81 вибудовуються над водою."},"tip":{"en":"Walk across at sunset and stay for blue hour on the Thu Thiem bank; bring mosquito repellent and water — there is little shade.","uk":"Перейдіть міст на заході сонця й залишайтеся на «синю годину» на березі Тху Тхієм; візьміть репелент і воду — тіні майже немає."},"hours":"24h","website":"https://vi.wikipedia.org/wiki/C%E1%BA%A7u_Ba_Son","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/a/a9/C%E1%BA%A7u_Ba_Son%2C_TP.HCM%2C_042022.jpg/960px-C%E1%BA%A7u_Ba_Son%2C_TP.HCM%2C_042022.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Saigon_at_Blue_Hour.jpg/960px-Saigon_at_Blue_Hour.jpg"]},{"id":"saigon-waterbus","region":"hcmc","area":"District 1","category":"experiences","name":"Saigon Waterbus River Ride","nameVi":"Buýt đường sông Sài Gòn","lat":10.77524,"lng":106.707,"address":"Bạch Đằng Station, 10B Tôn Đức Thắng (District 1)","rating":4.2,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"City river-bus line (since 2017) — the cheapest Saigon River cruise","desc":{"en":"A public river bus that chugs 11 km upstream from Bach Dang past the skyline, Thao Dien villas and coconut-lined banks to Linh Dong — a sightseeing cruise for pocket change.","uk":"Міський річковий автобус, що проходить 11 км угору річкою від Бах Данг повз хмарочоси, вілли Тхао Дієн і береги з кокосовими пальмами до Лінь Донг — круїз за копійки."},"tip":{"en":"Fare ≈15,000 VND one way; take a late-afternoon departure to come back at sunset, and check the timetable on saigonwaterbus.com.","uk":"Квиток ≈15 000 донгів в один бік; беріть рейс наприкінці дня, щоб повертатися на заході сонця, а розклад перевіряйте на saigonwaterbus.com."},"hours":"≈07:00–19:00 (several departures)","website":"https://saigonwaterbus.com","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Saigon_water_bus_%2820230705_1509%29.jpg/960px-Saigon_water_bus_%2820230705_1509%29.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/Checkin_door_in_the_Bach_Dang_Station_-_Sai_Gon_Water_Bus.jpg/960px-Checkin_door_in_the_Bach_Dang_Station_-_Sai_Gon_Water_Bus.jpg"]},{"id":"tan-dinh-church","region":"hcmc","area":"District 3","category":"temples","name":"Tan Dinh Church (the Pink Church)","nameVi":"Nhà thờ Tân Định","lat":10.78836,"lng":106.69064,"address":"289 Hai Bà Trưng, Tân Định (District 3)","rating":4.5,"googleRating":4.4,"price":0,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Bubblegum-pink 1876 Gothic-Romanesque church — one of Vietnam's most Instagrammed buildings","desc":{"en":"A candy-pink Romanesque-Gothic church from 1876, its spires and arches painted the colour of strawberry ice cream — Saigon's favourite selfie backdrop.","uk":"Рожевий, наче полуничне морозиво, романсько-готичний храм 1876 року — улюблене тло для селфі в Сайгоні."},"tip":{"en":"Best photographed from across Hai Ba Trung in morning light; the gate is usually shut outside Mass times, so time a visit for a service (Sunday is busy) and dress modestly.","uk":"Найкраще фотографувати з протилежного боку вулиці Хай Ба Чунг у ранковому світлі; поза службами ворота зазвичай зачинені, тож приходьте на месу (у неділю людно) й одягайтеся скромно."},"hours":"Exterior 24h; interior at Mass times","website":"https://en.wikipedia.org/wiki/T%C3%A2n_%C4%90%E1%BB%8Bnh_Church","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/T%C3%A2n_%C4%90%E1%BB%8Bnh_Church_20190922.jpg/960px-T%C3%A2n_%C4%90%E1%BB%8Bnh_Church_20190922.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Tan_Dinh_Church_27_December_2020.jpg/960px-Tan_Dinh_Church_27_December_2020.jpg"]},{"id":"war-remnants-museum","region":"hcmc","area":"District 3","category":"museums","name":"War Remnants Museum","nameVi":"Bảo tàng Chứng tích Chiến tranh","lat":10.77936,"lng":106.69228,"address":"28 Võ Văn Tần, Võ Thị Sáu (District 3)","rating":4.8,"googleRating":4.5,"price":1,"mustSee":true,"hiddenGem":false,"viral":false,"hype":"One of Vietnam's most-visited museums; perennial TripAdvisor top attraction in HCMC","desc":{"en":"A harrowing, unforgettable account of the American War — Agent Orange, the 'Requiem' war-photographer gallery and recreated 'tiger cages', with US tanks and jets in the yard.","uk":"Важка, але незабутня розповідь про Американську війну — «Агент Оранж», галерея фронтових фотографів «Реквієм» і відтворені «тигрові клітки», а у дворі — американські танки й літаки."},"tip":{"en":"Ticket 60,000 VND (from Oct 2026); go at 07:30 opening to beat the tour buses, start on the top floor and work down. Emotionally heavy — not ideal for young kids.","uk":"Квиток 60 000 донгів (з жовтня 2026); приходьте до відкриття о 07:30, щоб випередити автобуси, починайте з верхнього поверху. Емоційно важко — не для малих дітей."},"hours":"07:30–17:30","website":"https://baotangchungtichchientranh.vn","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/War_Remnants_Museum%2C_HCMC%2C_front.JPG/960px-War_Remnants_Museum%2C_HCMC%2C_front.JPG","https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/War_Remnants_Museum_%2845314136394%29.jpg/960px-War_Remnants_Museum_%2845314136394%29.jpg"]},{"id":"ho-chi-minh-city-museum","region":"hcmc","area":"District 1","category":"museums","name":"Ho Chi Minh City Museum (Gia Long Palace)","nameVi":"Bảo tàng Thành phố Hồ Chí Minh","lat":10.77591,"lng":106.69962,"address":"65 Lý Tự Trọng, Bến Nghé (District 1)","rating":4.2,"googleRating":4.2,"price":1,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"1890 neo-classical Gia Long Palace; the city's go-to wedding-photo backdrop","desc":{"en":"A grand 1890 colonial palace with a sweeping staircase and tiled floors, telling Saigon's story from Funan relics to 1975 — couples in ao dai pose on its steps all day.","uk":"Величний колоніальний палац 1890 року з парадними сходами й кахляною підлогою, що розповідає історію Сайгона від реліквій Фунані до 1975 року; на сходах цілий день позують пари в аозаях."},"tip":{"en":"Entry ≈30,000 VND; the building itself is the star — find the staircase and the rear garden with planes and tanks; a 5-minute walk from Ben Thanh.","uk":"Вхід ≈30 000 донгів; головна зірка — сама будівля: парадні сходи й задній двір із літаками та танками; 5 хвилин пішки від ринку Бен Тхань."},"hours":"08:00–17:00","website":"https://en.wikipedia.org/wiki/Museum_of_Ho_Chi_Minh_City","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/B%E1%BA%A3o_t%C3%A0ng_Th%C3%A0nh_ph%E1%BB%91_H%E1%BB%93_Ch%C3%AD_Minh_7.jpg/960px-B%E1%BA%A3o_t%C3%A0ng_Th%C3%A0nh_ph%E1%BB%91_H%E1%BB%93_Ch%C3%AD_Minh_7.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/Museum_of_Ho_Chi_Minh_City_%28formerly_Gia_Long_Palace%29.jpg/960px-Museum_of_Ho_Chi_Minh_City_%28formerly_Gia_Long_Palace%29.jpg"]},{"id":"fine-arts-museum","region":"hcmc","area":"District 1","category":"museums","name":"Ho Chi Minh City Museum of Fine Arts","nameVi":"Bảo tàng Mỹ thuật Thành phố Hồ Chí Minh","lat":10.7696,"lng":106.69927,"address":"97A Phó Đức Chính, Nguyễn Thái Bình (District 1)","rating":4.4,"googleRating":4.4,"price":1,"mustSee":false,"hiddenGem":true,"viral":true,"hype":"1929 mansion of tycoon Hui Bon Hoa with stained glass and one of Saigon's first lifts; photographers' favourite","desc":{"en":"A faded yellow 1929 tycoon's mansion of stained glass, Art Deco tiles and courtyards, filled with lacquer paintings, Cham sculpture and wartime propaganda art.","uk":"Вицвілий жовтий особняк магната 1929 року з вітражами, ар-деко плиткою та внутрішніми двориками, де зібрано лакові картини, чамську скульптуру й воєнне агітаційне мистецтво."},"tip":{"en":"Entry ≈30,000 VND; rarely crowded — come in the late afternoon when sun pours through the coloured windows onto the stairwell.","uk":"Вхід ≈30 000 донгів; людей мало — приходьте надвечір, коли сонце світить крізь кольорові вікна на сходи."},"hours":"08:00–17:00","website":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_City_Museum_of_Fine_Arts","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/B%E1%BA%A3o_t%C3%A0ng_M%E1%BB%B9_thu%E1%BA%ADt_Tp_%28ki%E1%BA%BFn_tr%C3%BAc_t%E1%BB%95ng_th%E1%BB%83%29_%282%29.jpg/960px-B%E1%BA%A3o_t%C3%A0ng_M%E1%BB%B9_thu%E1%BA%ADt_Tp_%28ki%E1%BA%BFn_tr%C3%BAc_t%E1%BB%95ng_th%E1%BB%83%29_%282%29.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/e/e8/Museum_of_Fine_Arts%2C_HCMC.jpg/960px-Museum_of_Fine_Arts%2C_HCMC.jpg"]},{"id":"museum-of-vietnamese-history","region":"hcmc","area":"District 1","category":"museums","name":"Museum of Vietnamese History","nameVi":"Bảo tàng Lịch sử Thành phố Hồ Chí Minh","lat":10.78797,"lng":106.70496,"address":"2 Nguyễn Bỉnh Khiêm, inside the Zoo gates (District 1)","rating":4.3,"googleRating":4.5,"price":1,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"1929 Indochinese-style building; best Champa and Oc Eo collections in the south","desc":{"en":"A pagoda-roofed 1929 building holding 4,000 years of Vietnamese history — Dong Son drums, Cham sandstone goddesses and a mummified 19th-century noblewoman.","uk":"Будівля 1929 року з пагодовим дахом, що вміщує 4000 років історії В'єтнаму — бронзові барабани Донгшон, чамські богині з пісковику та мумію знатної жінки XIX століття."},"tip":{"en":"Ticket ≈30,000 VND; closed Mondays and at lunchtime; catch the short water-puppet show held in the museum on some days.","uk":"Квиток ≈30 000 донгів; вихідний — понеділок, обідня перерва; іноді в музеї показують коротку виставу водяних ляльок."},"hours":"08:00–11:30, 13:00–17:00 (closed Mon)","website":"https://en.wikipedia.org/wiki/Museum_of_Vietnamese_History","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/Sandstone_Lakshmi_statue_%2810th_century%29%2C_Museum_of_Vietnamese_History%2C_Ho_Chi_Minh_City_-_20121014.JPG/960px-Sandstone_Lakshmi_statue_%2810th_century%29%2C_Museum_of_Vietnamese_History%2C_Ho_Chi_Minh_City_-_20121014.JPG"]},{"id":"ao-dai-museum","region":"hcmc","area":"Thu Duc (Long Phuoc)","category":"museums","name":"Ao Dai Museum","nameVi":"Bảo tàng Áo dài","lat":10.80975,"lng":106.84976,"address":"206/19/30 Long Thuận, Long Phước (former District 9 / Thủ Đức)","rating":4.2,"googleRating":4.4,"price":1,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Vietnam's first private ao dai museum (2014) by designer Sĩ Hoàng; named among HCMC's '100 most interesting things'","desc":{"en":"Wooden southern-style houses in a leafy garden display centuries of the ao dai, from royal gowns to dresses worn by famous Vietnamese women.","uk":"Дерев'яні будинки південного стилю в зеленому саду показують століття історії аозая — від королівських шат до суконь відомих в'єтнамок."},"tip":{"en":"It's ~25 km from the centre — go by Grab (≈45 min); adults ≈50,000 VND; usually closed Mondays; you can rent an ao dai for photos.","uk":"Це ~25 км від центру — їдьте Grab (≈45 хв); дорослий квиток ≈50 000 донгів; зазвичай вихідний — понеділок; можна взяти аозай напрокат для фото."},"hours":"08:30–17:30 (closed Mon)","website":"","images":[]},{"id":"saigon-zoo-botanical-gardens","region":"hcmc","area":"District 1","category":"nature","name":"Saigon Zoo & Botanical Gardens","nameVi":"Thảo Cầm Viên Sài Gòn","lat":10.78806,"lng":106.70472,"address":"2B Nguyễn Bỉnh Khiêm, Bến Nghé (District 1)","rating":3.8,"googleRating":4.3,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Founded 1864 — one of the oldest zoos in the world","desc":{"en":"A 19th-century botanical garden of giant century-old trees and lily ponds, popular with local families; the animal enclosures, however, are dated and often criticised.","uk":"Ботанічний сад XIX століття з велетенськими столітніми деревами й ставками з лататтям, улюблений місцевими родинами; утім, вольєри застарілі й часто зазнають критики."},"tip":{"en":"Worth it mainly for the shady old trees and as a combo with the History Museum inside the gates; skip if animal welfare matters to you.","uk":"Варто йти передусім заради тінистих старих дерев і разом з Історичним музеєм за тими ж воротами; пропустіть, якщо для вас важливий добробут тварин."},"hours":"07:00–18:30","website":"https://en.wikipedia.org/wiki/Saigon_Zoo_and_Botanical_Gardens","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/H%E1%BB%93_n%C6%B0%E1%BB%9Bc_%E1%BB%9F_Th%E1%BA%A3o_C%E1%BA%A7m_Vi%C3%AAn.JPG/960px-H%E1%BB%93_n%C6%B0%E1%BB%9Bc_%E1%BB%9F_Th%E1%BA%A3o_C%E1%BA%A7m_Vi%C3%AAn.JPG"]},{"id":"jade-emperor-pagoda","region":"hcmc","area":"District 1 (Da Kao)","category":"temples","name":"Jade Emperor Pagoda","nameVi":"Chùa Ngọc Hoàng (Phước Hải Tự)","lat":10.79153,"lng":106.69769,"address":"73 Mai Thị Lựu, Đa Kao (District 1)","rating":4.7,"googleRating":4.7,"price":0,"mustSee":true,"hiddenGem":false,"viral":false,"hype":"1909 Cantonese Taoist temple visited by Barack Obama in 2016","desc":{"en":"A smoky, atmospheric Taoist temple crammed with carved wooden deities, the King of Hell's chamber and a turtle pond where locals release animals for luck.","uk":"Задимлений, атмосферний даоський храм, заповнений різьбленими дерев'яними божествами, залою Царя пекла та ставком із черепахами, куди місцеві відпускають тварин на щастя."},"tip":{"en":"Free; come early morning or on the 1st/15th of the lunar month for the most incense and worshippers; women pray here for fertility in the side hall.","uk":"Вхід вільний; приходьте зранку або 1-го/15-го дня місячного місяця, коли найбільше пахощів і вірян; у бічній залі жінки моляться про дітей."},"hours":"07:00–18:00","website":"https://en.wikipedia.org/wiki/Jade_Emperor_Pagoda","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Jade_Emperor_Pagoda_Saigon.jpg/960px-Jade_Emperor_Pagoda_Saigon.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/4/4c/Ph%C6%B0%E1%BB%9Bc_H%E1%BA%A3i_T%E1%BB%B1.jpg/960px-Ph%C6%B0%E1%BB%9Bc_H%E1%BA%A3i_T%E1%BB%B1.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Jade_Emperor_Pagoda_-_Altar.jpg/960px-Jade_Emperor_Pagoda_-_Altar.jpg"]},{"id":"thien-hau-temple","region":"hcmc","area":"District 5 (Cholon)","category":"temples","name":"Thien Hau Temple","nameVi":"Chùa Bà Thiên Hậu (Hội quán Tuệ Thành)","lat":10.75356,"lng":106.66119,"address":"710 Nguyễn Trãi, Chợ Lớn (District 5)","rating":4.7,"googleRating":4.6,"price":0,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"1760 Cantonese assembly hall to the sea goddess Mazu; its hanging incense coils are a classic photo","desc":{"en":"Cholon's most beautiful temple: porcelain dioramas line the roof, and giant spiral incense coils hang from the ceiling, filling the hall with shafts of smoky light.","uk":"Найкрасивіший храм Чолона: дах прикрашають порцелянові діорами, а зі стелі звисають велетенські спіральні пахощі, наповнюючи залу димними променями світла."},"tip":{"en":"Free; visit around 9–10 am when sunbeams cut through the incense smoke; combine with Binh Tay Market and Hao Si Phuong alley for a Chinatown half-day.","uk":"Вхід вільний; приходьте близько 9–10 ранку, коли промені сонця прорізають дим; поєднайте з ринком Бінь Тай і провулком Хао Ши Фионг для півдня в Чайнатауні."},"hours":"06:00–17:00","website":"https://en.wikipedia.org/wiki/Thien_Hau_Temple","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Thien_Hau_Pagoda_%2810017896294%29.jpg/960px-Thien_Hau_Pagoda_%2810017896294%29.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/3/37/Thien_Hau_Temple%2C_Ho_Chi_Minh_City_PB309850.jpg/960px-Thien_Hau_Temple%2C_Ho_Chi_Minh_City_PB309850.jpg"]},{"id":"giac-lam-pagoda","region":"hcmc","area":"Tan Binh","category":"temples","name":"Giac Lam Pagoda","nameVi":"Chùa Giác Lâm","lat":10.77826,"lng":106.64921,"address":"565 Lạc Long Quân (entrance alley 118), Tân Bình","rating":4.5,"googleRating":4.6,"price":0,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Founded 1744 — the oldest pagoda in Ho Chi Minh City","desc":{"en":"Saigon's oldest pagoda, a hushed sanctuary of 98 carved jackfruit-wood pillars, 100+ gilded statues and a seven-storey stupa rising over a garden of bodhi trees.","uk":"Найстаріша пагода Сайгона — тихе святилище з 98 різьбленими колонами з дерева джекфрута, понад сотнею позолочених статуй і семиярусною ступою над садом із деревами бодхі."},"tip":{"en":"Free; climb the stupa if it's open for city views; it's out in Tan Binh, so pair it with the airport run or Phung Son Pagoda.","uk":"Вхід вільний; якщо ступа відкрита — підніміться заради краєвиду; храм у Тан Біні, тож зручно поєднати з поїздкою в аеропорт або пагодою Фунг Шон."},"hours":"06:00–12:00, 14:00–20:00","website":"https://en.wikipedia.org/wiki/Gi%C3%A1c_L%C3%A2m_Pagoda","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/ChuaGiacLam02.jpg/960px-ChuaGiacLam02.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/ChuaGiacLam01.jpg/960px-ChuaGiacLam01.jpg"]},{"id":"phung-son-pagoda","region":"hcmc","area":"District 11","category":"temples","name":"Phung Son Pagoda","nameVi":"Chùa Phụng Sơn (Chùa Gò)","lat":10.75682,"lng":106.64475,"address":"1408 Đường 3 Tháng 2, Minh Phụng (District 11)","rating":4.2,"googleRating":null,"price":0,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Early-19th-century pagoda built on the ruins of an ancient Funan-era site; Lonely Planet pick","desc":{"en":"A low-key, little-visited pagoda on a mound where archaeologists found Funan-era remains, full of gilded Buddhas, lacquered altars and drifting incense.","uk":"Скромна, маловідвідувана пагода на пагорбі, де археологи знайшли залишки епохи Фунань, сповнена позолочених Будд, лакованих вівтарів і пахощів."},"tip":{"en":"Free; dress modestly and remove shoes in the main hall; easy to add to a Cholon/Giac Lam loop by Grab.","uk":"Вхід вільний; одягайтеся скромно й знімайте взуття в головній залі; легко додати до маршруту Чолон/Зіак Лам на Grab."},"hours":"06:00–18:00","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/d/de/Phung_Son_Pagoda_%2810017915374%29.jpg/960px-Phung_Son_Pagoda_%2810017915374%29.jpg"]},{"id":"sri-mariamman-temple","region":"hcmc","area":"District 1","category":"temples","name":"Mariamman Hindu Temple","nameVi":"Đền Bà Mariamman","lat":10.77229,"lng":106.69556,"address":"45 Trương Định, Bến Thành (District 1)","rating":4.3,"googleRating":4.7,"price":0,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Late-19th-century Tamil temple, revered by Hindus and Vietnamese alike","desc":{"en":"A colourful Tamil Hindu temple with a tower of painted deities, just three blocks from Ben Thanh — a surprising slice of South India in central Saigon.","uk":"Барвистий тамільський індуїстський храм із вежею розмальованих божеств за три квартали від Бен Тхань — несподіваний шматочок Південної Індії в центрі Сайгона."},"tip":{"en":"Free; remove shoes at the entrance and avoid photographing worshippers at the altar; quick 15-minute stop between Ben Thanh and the Independence Palace.","uk":"Вхід вільний; знімайте взуття біля входу й не фотографуйте вірян біля вівтаря; 15-хвилинна зупинка між Бен Тхань і Палацом Незалежності."},"hours":"07:00–19:00","website":"https://en.wikipedia.org/wiki/Mariamman_Temple,_Ho_Chi_Minh_City","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/SriMariammanSaigon.jpg/960px-SriMariammanSaigon.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/2/23/Decorations_at_Mariamman_Temple_HCMC.JPG/960px-Decorations_at_Mariamman_Temple_HCMC.JPG"]},{"id":"hao-si-phuong","region":"hcmc","area":"District 5 (Cholon)","category":"sights","name":"Hao Si Phuong Alley","nameVi":"Hẻm Hào Sĩ Phường","lat":10.75299,"lng":106.66623,"address":"206 Trần Hưng Đạo (District 5)","rating":4.1,"googleRating":null,"price":0,"mustSee":false,"hiddenGem":true,"viral":true,"hype":"19th-century Chinese tenement alley with red lanterns; trending with photographers on Instagram/TikTok","desc":{"en":"Behind an unassuming gate on Tran Hung Dao, a narrow 19th-century Chinese tenement alley of mint-green walls, wooden balconies and red lanterns — Cholon frozen in time.","uk":"За непримітною брамою на вулиці Чан Хинг Дао — вузький провулок китайських житлових будинків XIX століття з м'ятними стінами, дерев'яними балконами й червоними ліхтарями: Чолон, застиглий у часі."},"tip":{"en":"It's a residential lane — come in daylight, keep voices down, ask before photographing people and don't block doorways.","uk":"Це житловий провулок — приходьте вдень, говоріть тихо, питайте дозволу перед фото людей і не загороджуйте двері."},"hours":"Daytime (residential)","website":"","images":[]},{"id":"ben-thanh-market","region":"hcmc","area":"District 1","category":"markets","name":"Ben Thanh Market","nameVi":"Chợ Bến Thành","lat":10.77253,"lng":106.69804,"address":"Lê Lợi / Quách Thị Trang Square, Bến Thành (District 1)","rating":4.0,"googleRating":4.0,"price":1,"mustSee":true,"hiddenGem":false,"viral":false,"hype":"1914 clock-tower market — symbol of Saigon; facade refreshed for Tet 2026","desc":{"en":"Saigon's iconic 1914 market under its clock tower: a maze of lacquerware, coffee, ao dai fabric and a buzzing food hall, freshly repainted for Tet 2026.","uk":"Знаковий ринок 1914 року під годинниковою вежею: лабіринт лакових виробів, кави, тканин для аозаїв і гамірного фудкорту, свіжо пофарбований до Тету 2026."},"tip":{"en":"Prices start high for tourists — bargain hard (aim for 50–60% of the first price) and compare with fixed-price shops; watch your phone in the crowded aisles.","uk":"Ціни для туристів завищені — торгуйтеся завзято (ціль — 50–60 % від першої ціни) й порівнюйте з магазинами з фіксованими цінами; пильнуйте телефон у тісних проходах."},"hours":"07:00–19:00","website":"https://en.wikipedia.org/wiki/B%E1%BA%BFn_Th%C3%A0nh_Market","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Ben_Thanh_market_2.jpg/960px-Ben_Thanh_market_2.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/f/f5/Ben_Thanh%2C_Ciudad_Ho_Chi_Minh%2C_Vietnam%2C_2013-08-14%2C_DD_01.JPG/960px-Ben_Thanh%2C_Ciudad_Ho_Chi_Minh%2C_Vietnam%2C_2013-08-14%2C_DD_01.JPG","https://upload.wikimedia.org/wikipedia/commons/thumb/b/ba/Ben_Thanh_Market1.jpg/960px-Ben_Thanh_Market1.jpg"]},{"id":"binh-tay-market","region":"hcmc","area":"District 6 (Cholon)","category":"markets","name":"Binh Tay Market","nameVi":"Chợ Bình Tây","lat":10.7493,"lng":106.65073,"address":"57A Tháp Mười, Bình Tây (District 6)","rating":4.3,"googleRating":4.4,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"1928 Chinatown wholesale market built by merchant Quách Đàm; restored and reopened 2020","desc":{"en":"Cholon's grand 1928 wholesale market with a pagoda-style clock tower and a courtyard dragon fountain — a real working market of spices, dried goods and wholesale chaos.","uk":"Величний гуртовий ринок Чолона 1928 року з годинниковою вежею у стилі пагоди та фонтаном із драконом у дворі — справжній робочий ринок спецій, сушених продуктів і гуртового хаосу."},"tip":{"en":"Go early (7–10 am) when trading is busiest; far fewer tourists and lower prices than Ben Thanh — great for dried fruit and tea.","uk":"Приходьте рано (7–10 ранку), коли торгівля найжвавіша; туристів значно менше, а ціни нижчі, ніж на Бен Тхань — добре для сухофруктів і чаю."},"hours":"06:00–18:00","website":"https://en.wikipedia.org/wiki/B%C3%ACnh_T%C3%A2y_Market","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/b/bf/Vn-hcm-cho-binh-tay-27-07-07.JPG/960px-Vn-hcm-cho-binh-tay-27-07-07.JPG","https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Binh_Tay_market_3.jpg/960px-Binh_Tay_market_3.jpg"]},{"id":"saigon-square","region":"hcmc","area":"District 1","category":"markets","name":"Saigon Square","nameVi":"Saigon Square","lat":10.7728,"lng":106.70019,"address":"77–89 Nam Kỳ Khởi Nghĩa, Bến Thành (District 1)","rating":3.8,"googleRating":4.1,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Backpacker favourite for cheap 'brand' clothing and bags","desc":{"en":"A cramped, air-conditioned bazaar of stalls selling knock-off backpacks, sportswear and sunglasses — handy for travel gear, not for authenticity.","uk":"Тісний базар із кондиціонером, де продають копії рюкзаків, спортивного одягу й окулярів — зручно для туристичного спорядження, але не за автентичністю."},"tip":{"en":"Haggle — start at about a third of the asking price; goods are mostly replicas, so check stitching and zippers before paying.","uk":"Торгуйтеся — починайте приблизно з третини запитаної ціни; товари здебільшого репліки, тож перевіряйте шви та блискавки перед оплатою."},"hours":"09:00–21:00","website":"","images":[]},{"id":"ho-thi-ky-flower-market","region":"hcmc","area":"District 10","category":"markets","name":"Ho Thi Ky Flower Market & Food Alley","nameVi":"Chợ hoa Hồ Thị Kỷ","lat":10.76577,"lng":106.67727,"address":"Hẻm 52 Hồ Thị Kỷ / 401 Trần Bình Trọng (District 10)","rating":4.3,"googleRating":4.4,"price":0,"mustSee":false,"hiddenGem":true,"viral":true,"hype":"City's biggest wholesale flower market; its night street-food alley trends on TikTok","desc":{"en":"Lanes buried under roses, lilies and orchids where florists work through the night, opening onto a smoky alley of Khmer-Vietnamese street-food stalls.","uk":"Провулки, засипані трояндами, ліліями та орхідеями, де флористи працюють усю ніч, а поруч — димна алея кхмерсько-в'єтнамської вуличної їжі."},"tip":{"en":"Flowers are at their freshest from very early morning; come 18:00–22:00 to combine the blooms with the food alley.","uk":"Найсвіжіші квіти — дуже рано-вранці; приходьте о 18:00–22:00, щоб поєднати квіти з алеєю вуличної їжі."},"hours":"24h (busiest early morning & evening)","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/20180413_190400Saigon_Hotpot_Night_Food_Tour_Ho_Thi_Ky_Flower_Market.jpg/960px-20180413_190400Saigon_Hotpot_Night_Food_Tour_Ho_Thi_Ky_Flower_Market.jpg"]},{"id":"dan-sinh-market","region":"hcmc","area":"District 1","category":"markets","name":"Dan Sinh War Surplus Market","nameVi":"Chợ Dân Sinh","lat":10.76655,"lng":106.69799,"address":"104 Yersin, Nguyễn Thái Bình (District 1)","rating":4.0,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Known to travellers as the 'American market' for its war-surplus gear","desc":{"en":"A gritty hardware market whose back corner sells dog tags, Zippos, army jackets and helmets — some genuine, most reproduction — next to stalls of nuts, bolts and tools.","uk":"Шорсткий ринок інструментів, у дальньому куті якого продають жетони, запальнички Zippo, армійські куртки й шоломи — дещо справжнє, більшість — репліки — поруч із гвинтами й інструментами."},"tip":{"en":"Assume 'vintage' items are replicas and price accordingly; next door is the tiny Phung Son Tu temple — worth a peek.","uk":"Вважайте «вінтажні» речі репліками й торгуйтеся відповідно; поруч — крихітний храм Фунг Шон Ту, варто зазирнути."},"hours":"07:00–18:00","website":"https://en.wikipedia.org/wiki/D%C3%A2n_Sinh_Market","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/5/5a/Dan_Sinh_Market.jpg/960px-Dan_Sinh_Market.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/Ch%E1%BB%A3_D%C3%A2n_Sinh_C%E1%BB%95ng_1.jpg/960px-Ch%E1%BB%A3_D%C3%A2n_Sinh_C%E1%BB%95ng_1.jpg"]},{"id":"cu-chi-tunnels-ben-dinh","region":"hcmc","area":"Cu Chi","category":"sights","name":"Cu Chi Tunnels – Ben Dinh","nameVi":"Địa đạo Củ Chi – Bến Đình","lat":11.06141,"lng":106.52765,"address":"Provincial Road 15, Phú Hiệp – Nhuận Đức (Củ Chi), ~60 km NW of centre","rating":4.7,"googleRating":4.6,"price":1,"mustSee":true,"hiddenGem":false,"viral":false,"hype":"250 km wartime guerrilla tunnel network; Special National Relic; the #1 day trip from Saigon","desc":{"en":"Crawl through (widened) sections of the legendary 250-km guerrilla tunnel network, see hidden trapdoors, booby traps and underground kitchens in the jungle.","uk":"Проповзіть (розширеними) ділянками легендарної 250-кілометрової партизанської мережі тунелів, подивіться на приховані люки, пастки й підземні кухні в джунглях."},"tip":{"en":"Entry ≈110,000–135,000 VND; leave Saigon by 7:30 to beat heat and crowds, or go by speedboat along the river; wear clothes you don't mind getting muddy.","uk":"Вхід ≈110 000–135 000 донгів; виїжджайте із Сайгона до 7:30, щоб уникнути спеки й натовпу, або пливіть швидкісним катером річкою; вдягніть одяг, який не шкода забруднити."},"hours":"07:00–17:00","website":"https://en.wikipedia.org/wiki/C%E1%BB%A7_Chi_tunnels","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/1/14/C%E1%BB%A7_Chi_tunnels_entrance.JPG/960px-C%E1%BB%A7_Chi_tunnels_entrance.JPG","https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/W_C%E1%BB%A7_Chi_%C4%90%E1%BB%8Ba_%C4%91%E1%BA%A1o_C%E1%BB%A7_Chi_ng%E1%BB%A5y_trang.JPG/960px-W_C%E1%BB%A7_Chi_%C4%90%E1%BB%8Ba_%C4%91%E1%BA%A1o_C%E1%BB%A7_Chi_ng%E1%BB%A5y_trang.JPG"]},{"id":"cu-chi-tunnels-ben-duoc","region":"hcmc","area":"Cu Chi","category":"sights","name":"Cu Chi Tunnels – Ben Duoc","nameVi":"Địa đạo Củ Chi – Bến Dược","lat":11.14637,"lng":106.4594,"address":"Provincial Road 15, Phú Hiệp, An Nhơn Tây (Củ Chi), ~70 km NW of centre","rating":4.5,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"The original command-base section of the tunnels; the 'less touristy' alternative recommended by small-group tours","desc":{"en":"The quieter, more original part of the Cu Chi network with the regional command base, a memorial temple to tens of thousands of fallen and recreated liberated-zone villages.","uk":"Тихіша й автентичніша частина мережі Кучі з регіональним командним пунктом, меморіальним храмом десяткам тисяч загиблих і відтвореними селами «звільненої зони»."},"tip":{"en":"Entry ≈90,000–135,000 VND; noticeably fewer groups than Ben Dinh — book a small-group or private tour, as public transport is slow.","uk":"Вхід ≈90 000–135 000 донгів; груп помітно менше, ніж у Бен Дінь — бронюйте тур у малій групі чи приватний, громадський транспорт повільний."},"hours":"07:00–17:00","website":"https://en.wikipedia.org/wiki/C%E1%BB%A7_Chi_tunnels","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/6/66/Ben_Duoc_Temple_Cu_Chi_tunnel_%2839514032832%29.jpg/960px-Ben_Duoc_Temple_Cu_Chi_tunnel_%2839514032832%29.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/%C4%90%E1%BB%81n_B%E1%BA%BFn_D%C6%B0%E1%BB%A3c_%E1%BB%9F_C%E1%BB%A7_Chi.jpg/960px-%C4%90%E1%BB%81n_B%E1%BA%BFn_D%C6%B0%E1%BB%A3c_%E1%BB%9F_C%E1%BB%A7_Chi.jpg"]},{"id":"cai-rang-floating-market","region":"hcmc","area":"Can Tho","category":"markets","name":"Cai Rang Floating Market","nameVi":"Chợ nổi Cái Răng","lat":10.0024,"lng":105.74439,"address":"Cần Thơ River, Cái Răng ward, Cần Thơ (≈170 km SW of HCMC)","rating":4.4,"googleRating":null,"price":2,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Largest floating market in the Mekong Delta; national intangible cultural heritage (2016)","desc":{"en":"At dawn hundreds of boats gather on the Can Tho River, hoisting pineapples and pumelos on bamboo poles to advertise their wares while noodle boats serve breakfast on the water.","uk":"На світанку сотні човнів збираються на річці Кантхо, піднімаючи на бамбукових жердинах ананаси та помело як рекламу товару, а човни з локшиною подають сніданок просто на воді."},"tip":{"en":"Stay overnight in Can Tho and take a boat at 5:00–5:30 — the market is mostly over by 9:00 and has shrunk in recent years; a day trip from Saigon arrives too late.","uk":"Заночуйте в Кантхо й вирушайте човном о 5:00–5:30 — до 9:00 ринок майже згортається і з роками зменшився; одноденна поїздка із Сайгона приїжджає запізно."},"hours":"05:00–09:00","website":"https://en.wikipedia.org/wiki/C%C3%A1i_R%C4%83ng_Floating_Market","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/6/62/M%E1%BB%99t_c%E1%BA%A3nh_%E1%BB%9F_ch%E1%BB%A3_n%E1%BB%95i_C%C3%A1i_R%C4%83ng.jpg/960px-M%E1%BB%99t_c%E1%BA%A3nh_%E1%BB%9F_ch%E1%BB%A3_n%E1%BB%95i_C%C3%A1i_R%C4%83ng.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/f/fb/Cai_Rang_Floating_Market_1.jpg/960px-Cai_Rang_Floating_Market_1.jpg"]},{"id":"my-tho-ben-tre-mekong","region":"hcmc","area":"My Tho / Ben Tre","category":"experiences","name":"My Tho & Ben Tre Mekong Day Trip","nameVi":"Mỹ Tho – Bến Tre (Cồn Thới Sơn)","lat":10.33241,"lng":106.3207,"address":"Thới Sơn Island (Unicorn Island), Mekong River between Mỹ Tho and Bến Tre (≈75 km from HCMC)","rating":4.0,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"The classic one-day Mekong Delta tour from Saigon — Ben Tre is Vietnam's 'coconut kingdom'","desc":{"en":"Sampans paddle through narrow palm-fringed canals on Thoi Son island, with stops for coconut candy workshops, honey tea, fruit orchards and southern folk music (đờn ca tài tử).","uk":"Сампани пливуть вузькими каналами під пальмами на острові Тхой Шон із зупинками в майстернях кокосових цукерок, на медовому чаї, у фруктових садах і на південній народній музиці (донкатайту)."},"tip":{"en":"It's touristy but easy; add Vinh Trang Pagoda in My Tho, or choose a tour that cycles Ben Tre's back lanes for a more authentic day.","uk":"Туристично, але просто; додайте пагоду Вінь Чанг у Мітхо або оберіть тур із велопрогулянкою провулками Бенче для автентичнішого дня."},"hours":"Tours ≈07:30–17:30","website":"https://en.wikipedia.org/wiki/M%E1%BB%B9_Tho","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/L%C3%A0m_k%E1%BA%B9o_d%E1%BB%ABa_tr%C3%AAn_c%E1%BB%93n_Ph%E1%BB%A5ng.jpg/960px-L%C3%A0m_k%E1%BA%B9o_d%E1%BB%ABa_tr%C3%AAn_c%E1%BB%93n_Ph%E1%BB%A5ng.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/Ch%C3%B9a_V%C4%A9nh_Tr%C3%A0ng_%E1%BB%9F_M%E1%BB%B9_Tho.jpg/960px-Ch%C3%B9a_V%C4%A9nh_Tr%C3%A0ng_%E1%BB%9F_M%E1%BB%B9_Tho.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/3/3c/T%C3%A0u_du_l%E1%BB%8Bch_c%E1%BA%B7p_b%E1%BA%BFn_c%E1%BB%93n_Ph%E1%BB%A5ng.jpg/960px-T%C3%A0u_du_l%E1%BB%8Bch_c%E1%BA%B7p_b%E1%BA%BFn_c%E1%BB%93n_Ph%E1%BB%A5ng.jpg"]},{"id":"cao-dai-holy-see","region":"hcmc","area":"Tay Ninh","category":"temples","name":"Cao Dai Holy See","nameVi":"Tòa Thánh Tây Ninh","lat":11.304,"lng":106.13357,"address":"Phạm Hộ Pháp, Long Hoa, Hòa Thành, Tây Ninh (≈95 km NW of HCMC)","rating":4.6,"googleRating":null,"price":0,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Mother temple of Caodaism (built 1933–1955), the faith that venerates Buddha, Jesus and Victor Hugo","desc":{"en":"A psychedelic cathedral-pagoda of pastel dragons and the all-seeing Divine Eye, where white-robed worshippers in coloured ranks chant at the daily noon ceremony.","uk":"Психоделічний собор-пагода з пастельними драконами та Божественним Оком, де віряни в білих шатах, вишикувані кольоровими рядами, співають під час щоденної полуденної церемонії."},"tip":{"en":"Free; arrive before 12:00 to watch the noon prayer from the upper balcony, stay silent and don't enter the nave; combine with Cu Chi or Ba Den Mountain the same day.","uk":"Вхід вільний; приїжджайте до 12:00, щоб подивитися полуденну молитву з верхнього балкона, мовчіть і не заходьте в неф; поєднайте з Кучі чи горою Ба Ден того ж дня."},"hours":"Ceremonies 06:00, 12:00, 18:00, 24:00","website":"https://en.wikipedia.org/wiki/Caodaism","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/T%C3%B2a_Th%C3%A1nh_T%C3%A2y_Ninh_042013.JPG/960px-T%C3%B2a_Th%C3%A1nh_T%C3%A2y_Ninh_042013.JPG","https://upload.wikimedia.org/wikipedia/commons/thumb/9/9d/Cao_Dai_Holy_See%2C_Tay_Ninh.jpg/960px-Cao_Dai_Holy_See%2C_Tay_Ninh.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/f/fe/The_Cao_%C4%90%C3%A0i_T%C3%A2y_Ninh_Holy_See_%2812110031855%29.jpg/960px-The_Cao_%C4%90%C3%A0i_T%C3%A2y_Ninh_Holy_See_%2812110031855%29.jpg"]},{"id":"ba-den-mountain","region":"hcmc","area":"Tay Ninh","category":"nature","name":"Ba Den Mountain (Sun World cable car)","nameVi":"Núi Bà Đen","lat":11.38254,"lng":106.1723,"address":"Sun World Ba Den Mountain, Ninh Sơn, Tây Ninh (≈100 km NW of HCMC)","rating":4.4,"googleRating":null,"price":3,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Highest peak in southern Vietnam (986 m); record-setting cable car and a giant bronze Buddha on the summit","desc":{"en":"The 'Black Lady Mountain' towers over the Tay Ninh plain; cable cars whisk you past cave pagodas to a cloud-wrapped summit crowned by a huge bronze Buddha statue.","uk":"«Гора Чорної Пані» здіймається над рівниною Тайнінь; канатна дорога несе вас повз печерні пагоди до вершини в хмарах, увінчаної величезною бронзовою статуєю Будди."},"tip":{"en":"Summit (Van Son) round-trip ≈US$20–50 depending on route/combo; go on a weekday — weekends and Lunar January festival are packed; carry a light jacket for the windy top.","uk":"Підйом на вершину (Ван Шон) ≈20–50 доларів залежно від маршруту/комбо; їдьте в будень — вихідні та свято першого місячного місяця дуже людні; візьміть легку куртку на вітряну вершину."},"hours":"≈06:00–21:00 (weekends from 05:30)","website":"https://badenmountain.sunworld.vn/en","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/d/dc/Tay_Bo_Da_Son_Buddha_statue_sunset_Ba_Den_Mountain_Tay_Ninh_Vietnam.jpg/960px-Tay_Bo_Da_Son_Buddha_statue_sunset_Ba_Den_Mountain_Tay_Ninh_Vietnam.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/C%C3%A1p_treo_n%C3%BAi_B%C3%A0_%C4%90en.JPG/960px-C%C3%A1p_treo_n%C3%BAi_B%C3%A0_%C4%90en.JPG"]},{"id":"vung-tau-christ-statue","region":"hcmc","area":"Vung Tau","category":"sights","name":"Christ the King Statue, Vung Tau","nameVi":"Tượng Chúa Kitô Vua (Vũng Tàu)","lat":10.3265,"lng":107.08452,"address":"Núi Nhỏ, Hạ Long street, Vũng Tàu (≈100 km SE of HCMC)","rating":4.3,"googleRating":null,"price":0,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"32 m statue (1974–1993) — one of Asia's tallest Christ statues; shoulder viewpoints are a social-media classic","desc":{"en":"A 32-metre Christ with outstretched arms crowns Small Mountain above the South China Sea; climb 800+ steps and up inside the statue to stand on its shoulders.","uk":"32-метровий Христос із розпростертими руками височіє на Малій горі над Південнокитайським морем; подолайте понад 800 сходинок і підніміться всередині статуї аж на її плечі."},"tip":{"en":"Free; shoulders and knees must be covered or you'll be refused at the statue; go early morning to avoid heat, and take the fast ferry or a 2-hour drive from Saigon.","uk":"Вхід вільний; плечі та коліна мають бути закриті, інакше до статуї не пустять; ідіть зранку, поки не спекотно, і добирайтеся швидкісним поромом чи 2 години машиною із Сайгона."},"hours":"07:00–17:00","website":"https://en.wikipedia.org/wiki/Christ_of_V%C5%A9ng_T%C3%A0u","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/7/75/Statue_of_Jesus_in_Vung_Tau.jpg/960px-Statue_of_Jesus_in_Vung_Tau.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Statue_of_Jesus_in_Vungtau.jpg/960px-Statue_of_Jesus_in_Vungtau.jpg"]},{"id":"can-gio-mangrove-monkey-island","region":"hcmc","area":"Can Gio","category":"nature","name":"Can Gio Mangrove Forest & Monkey Island","nameVi":"Rừng ngập mặn Cần Giờ & Đảo Khỉ","lat":10.40478,"lng":106.88977,"address":"Rừng Sác road, Cần Giờ (≈55 km SE of centre, via Bình Khánh bridge/ferry)","rating":4.0,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"UNESCO Mangrove Biosphere Reserve (2000) — Saigon's 'green lung'","desc":{"en":"Vast replanted mangroves inside HCMC's city limits, with cheeky long-tailed macaques on Monkey Island and boat rides to the Vam Sat crocodile farm and bat swamp.","uk":"Величезні відновлені мангри в межах самого Хошиміна, з нахабними довгохвостими макаками на Острові мавп і човновими прогулянками до крокодилячої ферми та болота кажанів Вам Шат."},"tip":{"en":"Keep sunglasses, hats and snacks out of sight — the monkeys snatch them; a guided tour (≈US$40–75) is easiest as public transport is sparse.","uk":"Сховайте окуляри, капелюхи й перекуси — мавпи їх викрадають; найпростіше їхати з гідом (≈40–75 доларів), бо громадський транспорт ходить рідко."},"hours":"07:30–17:00","website":"https://en.wikipedia.org/wiki/C%E1%BA%A7n_Gi%E1%BB%9D_Mangrove_Forest","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/e/e5/Mangrove_in_Can_Gio_forest.jpg/960px-Mangrove_in_Can_Gio_forest.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/Lo_ren_river.jpg/960px-Lo_ren_river.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Kh%E1%BB%89_Vi%E1%BB%87t_Nam_%E1%BB%9F_%C4%91%E1%BA%A3o_kh%E1%BB%89_C%E1%BA%A7n_Gi%E1%BB%9D%2C_ng%C3%A0y_28_th%C3%A1ng_9_n%C4%83m_2017.jpg/960px-Kh%E1%BB%89_Vi%E1%BB%87t_Nam_%E1%BB%9F_%C4%91%E1%BA%A3o_kh%E1%BB%89_C%E1%BA%A7n_Gi%E1%BB%9D%2C_ng%C3%A0y_28_th%C3%A1ng_9_n%C4%83m_2017.jpg"]},{"id":"con-dao-islands","region":"hcmc","area":"Con Dao (optional far trip)","category":"beaches","name":"Con Dao Islands (optional far trip)","nameVi":"Côn Đảo","lat":8.68897,"lng":106.61484,"address":"Côn Sơn town, Côn Đảo special zone (45-min flight from HCMC)","rating":4.6,"googleRating":null,"price":3,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Former French/US-era prison island turned national park; turtle-nesting beaches and pilgrimage to Võ Thị Sáu's grave","desc":{"en":"A remote archipelago where haunting colonial 'tiger cage' prisons sit beside empty white-sand beaches, coral reefs and a national park where sea turtles nest.","uk":"Віддалений архіпелаг, де моторошні колоніальні в'язниці з «тигровими клітками» сусідять із безлюдними білими пляжами, кораловими рифами та нацпарком, де гніздяться морські черепахи."},"tip":{"en":"Needs at least 2–3 nights (fly from Tan Son Nhat); go March–September for calm seas and turtle season; the night visit to Hang Duong cemetery is a local ritual.","uk":"Потрібно щонайменше 2–3 ночі (переліт із Таншоннят); їдьте в березні–вересні — спокійне море й сезон черепах; нічне відвідування кладовища Хангзионг — місцевий ритуал."},"hours":"","website":"https://en.wikipedia.org/wiki/C%C3%B4n_%C4%90%E1%BA%A3o","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/C%C3%B4n_%C4%90%E1%BA%A3o_National_Park.jpg/960px-C%C3%B4n_%C4%90%E1%BA%A3o_National_Park.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/4/4f/Pulo_Condore_island_beach.jpg/960px-Pulo_Condore_island_beach.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/a/a8/C%C3%B4n_%C4%90%E1%BA%A3o_Prison_%2833361003538%29.jpg/960px-C%C3%B4n_%C4%90%E1%BA%A3o_Prison_%2833361003538%29.jpg"]},{"id":"golden-bridge-ba-na-hills","region":"central","area":"Ba Na Hills","category":"sights","name":"Golden Bridge (Ba Na Hills)","nameVi":"Cầu Vàng – Bà Nà Hills","lat":15.99509,"lng":107.99641,"address":"Sun World Ba Na Hills, Hoa Vang, Da Nang (cable car from base station)","rating":4.6,"googleRating":null,"price":3,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Instagram icon; named one of TIME's World's Greatest Places 2019","desc":{"en":"A 150 m golden footbridge held aloft by two giant moss-covered stone hands, floating 1,400 m up in the clouds above Da Nang.","uk":"150-метровий золотий міст, який підтримують дві велетенські замшілі кам'яні руки, ширяє в хмарах на висоті 1400 м над Дананґом."},"tip":{"en":"Take the first cable car (~07:00–07:30) to get the bridge before the tour crowds; bring a jacket, it is 10–15 °C cooler on top.","uk":"Сідайте на першу канатку (~07:00–07:30), щоб побачити міст до натовпу туристів; візьміть куртку — нагорі на 10–15 °C прохолодніше."},"hours":"07:00–22:00 (cable cars ~07:00–17:30)","website":"https://en.wikipedia.org/wiki/Golden_Bridge_(Vietnam)","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Golden_Bridge_at_Ba_Na_Hills_20250718.jpg/960px-Golden_Bridge_at_Ba_Na_Hills_20250718.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/Golden_Bridge_Ba_Na_Hills_aerial_sunset_Da_Nang_Vietnam.jpg/960px-Golden_Bridge_Ba_Na_Hills_aerial_sunset_Da_Nang_Vietnam.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/3/34/Da_Nang_Golden_Bridge%2C_Sun_World_Ba_Na_Hills.jpg/960px-Da_Nang_Golden_Bridge%2C_Sun_World_Ba_Na_Hills.jpg"]},{"id":"marble-mountains","region":"central","area":"Da Nang","category":"nature","name":"Marble Mountains","nameVi":"Ngũ Hành Sơn","lat":16.00402,"lng":108.26277,"address":"81 Huyen Tran Cong Chua, Ngu Hanh Son, Da Nang","rating":4.6,"googleRating":null,"price":1,"mustSee":true,"hiddenGem":false,"viral":false,"hype":"","desc":{"en":"Five limestone-and-marble karsts riddled with caves, Buddhist grottoes and pagodas; Huyen Khong cave glows with shafts of sunlight falling on hidden shrines.","uk":"П'ять вапняково-мармурових скель, пронизаних печерами, буддійськими гротами та пагодами; у печері Хуєн Конґ сонячні промені падають просто на приховані святилища."},"tip":{"en":"Go at opening (07:00) and take the elevator up Thuy Son, then walk down via Huyen Khong cave; wear shoes with grip — the steps get slippery.","uk":"Приходьте до відкриття (07:00), підніміться ліфтом на гору Тхуй Шон, а вниз ідіть повз печеру Хуєн Конґ; взуйте нековзке взуття — сходинки слизькі."},"hours":"07:00–17:30","website":"https://en.wikipedia.org/wiki/Marble_Mountains_(Vietnam)","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/c/ce/Ngu_hanh_son_toan_canh.jpg/960px-Ngu_hanh_son_toan_canh.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/5/5d/Hiking_at_Marble_Mountains%2C_Da_Nang%2C_Vietnam.jpg/960px-Hiking_at_Marble_Mountains%2C_Da_Nang%2C_Vietnam.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/Da_Nang_Marble_Mountains_2020_IMG_4008.jpg/960px-Da_Nang_Marble_Mountains_2020_IMG_4008.jpg"]},{"id":"lady-buddha-linh-ung-pagoda","region":"central","area":"Da Nang","category":"temples","name":"Lady Buddha – Linh Ung Pagoda (Son Tra)","nameVi":"Chùa Linh Ứng Sơn Trà","lat":16.10016,"lng":108.27841,"address":"Hoang Sa St, Son Tra Peninsula, Da Nang","rating":4.7,"googleRating":null,"price":0,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Vietnam's tallest Lady Buddha (67 m), a staple of Da Nang travel reels","desc":{"en":"A serene 67 m white statue of Quan Am, goddess of mercy, gazes over the East Sea and the curve of Da Nang's beaches from the slopes of Son Tra.","uk":"Спокійна 67-метрова біла статуя Куан Ам, богині милосердя, дивиться на Східне море та вигин пляжів Дананґа зі схилів півострова Шонча."},"tip":{"en":"Come in late afternoon for golden light on the statue and the city; dress modestly (shoulders and knees covered).","uk":"Приїжджайте ближче до вечора — статуя й місто в золотому світлі; одягайтеся скромно (плечі й коліна прикриті)."},"hours":"06:00–21:00","website":"https://en.wikipedia.org/wiki/Linh_Ung_Pagoda","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Son-Tra-Peninsula_Da-Nang_Vietnam_Linh-Ung-Pagoda-03.jpg/960px-Son-Tra-Peninsula_Da-Nang_Vietnam_Linh-Ung-Pagoda-03.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Son-Tra-Peninsula_Da-Nang_Vietnam_Statue-of-the-Bodhisattva-of-Mercy-01.jpg/960px-Son-Tra-Peninsula_Da-Nang_Vietnam_Statue-of-the-Bodhisattva-of-Mercy-01.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/f/fe/Son-Tra-Peninsula_Da-Nang_Vietnam_Linh-Ung-Pagoda-01.jpg/960px-Son-Tra-Peninsula_Da-Nang_Vietnam_Linh-Ung-Pagoda-01.jpg"]},{"id":"son-tra-peninsula-ban-co-peak","region":"central","area":"Da Nang","category":"nature","name":"Son Tra Peninsula & Ban Co Peak","nameVi":"Bán đảo Sơn Trà & Đỉnh Bàn Cờ","lat":16.11893,"lng":108.272,"address":"Yet Kieu / Ban Co Peak road, Son Tra Peninsula, Da Nang","rating":4.5,"googleRating":null,"price":0,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"","desc":{"en":"A jungle-clad 'monkey mountain' minutes from downtown, home to rare red-shanked douc langurs; the winding road climbs to Ban Co (Chessboard) Peak with 360° views over the bay.","uk":"Вкрита джунглями «мавпяча гора» за кілька хвилин від центру, де живуть рідкісні червононогі дуки; серпантин веде на пік Бан Ко (Шахова дошка) з панорамою 360° на затоку."},"tip":{"en":"Go by scooter early morning (06:00–08:00) to spot douc langurs near the road; cars are restricted on the upper road and it closes in bad weather.","uk":"Їдьте на скутері рано вранці (06:00–08:00), щоб побачити дуків біля дороги; на верхню дорогу авто обмежено, у негоду її закривають."},"hours":"Daylight hours","website":"https://en.wikipedia.org/wiki/S%C6%A1n_Tr%C3%A0_Peninsula","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Red-shanked_douc_langur_%28Pygathrix_nemaeus%29_juvenile_Son_Tra.jpg/960px-Red-shanked_douc_langur_%28Pygathrix_nemaeus%29_juvenile_Son_Tra.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/Red-shanked_douc_langur_%28Pygathrix_nemaeus%29_female_Son_Tra.jpg/960px-Red-shanked_douc_langur_%28Pygathrix_nemaeus%29_female_Son_Tra.jpg"]},{"id":"my-khe-beach","region":"central","area":"Da Nang","category":"beaches","name":"My Khe Beach","nameVi":"Bãi biển Mỹ Khê","lat":16.07563,"lng":108.24688,"address":"Vo Nguyen Giap / Pham Van Dong beach, Son Tra, Da Nang","rating":4.6,"googleRating":null,"price":0,"mustSee":true,"hiddenGem":false,"viral":false,"hype":"Once dubbed by Forbes among the most attractive beaches on the planet","desc":{"en":"Kilometres of soft white sand and rolling surf right in the city, framed by Son Tra's green hills; locals swim and play volleyball at dawn.","uk":"Кілометри м'якого білого піску та хвиль прямо в місті, на тлі зелених пагорбів Шонча; місцеві плавають і грають у волейбол на світанку."},"tip":{"en":"Swim between the lifeguard flags; sunrise (05:00–06:30) is the magic hour when locals flood the beach. Sep–Dec brings rough seas.","uk":"Купайтеся між прапорцями рятувальників; світанок (05:00–06:30) — чарівна година, коли на пляж виходять місцеві. З вересня по грудень море бурхливе."},"hours":"24 h (lifeguards ~06:00–18:00)","website":"https://en.wikipedia.org/wiki/M%E1%BB%B9_Kh%C3%AA_Beach","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/c/c0/My_Khe_Beach%2C_Da_Nang%2C_Vietnam.jpg/960px-My_Khe_Beach%2C_Da_Nang%2C_Vietnam.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/e/e5/My_Khe_Beach_Danang_Coastline.jpg/960px-My_Khe_Beach_Danang_Coastline.jpg","https://goodmorning-hoian.com/wp-content/uploads/plage-de-my-khe-da-nang.jpg"]},{"id":"dragon-bridge-fire-show","region":"central","area":"Da Nang","category":"experiences","name":"Dragon Bridge Fire & Water Show","nameVi":"Cầu Rồng phun lửa","lat":16.06117,"lng":108.2279,"address":"Dragon Bridge, Han River (best view from Tran Hung Dao riverside, east bank), Da Nang","rating":4.5,"googleRating":null,"price":0,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Viral weekend show: a 666 m steel dragon that breathes fire and water","desc":{"en":"Every weekend night the 666 m golden steel dragon spanning the Han River roars into life, spitting fireballs and then spraying water over the cheering crowd.","uk":"Щовихідних уночі 666-метровий золотий сталевий дракон над річкою Хан оживає: спершу вивергає вогняні кулі, а потім поливає водою натовп."},"tip":{"en":"Show is Sat & Sun at 21:00 (~15 min); stand near the dragon's head on the east bank — and expect to get wet in the water finale.","uk":"Шоу в суботу й неділю о 21:00 (~15 хв); ставайте біля голови дракона на східному березі — і готуйтеся промокнути у фіналі."},"hours":"Fire show Sat–Sun 21:00; lit nightly","website":"https://en.wikipedia.org/wiki/Dragon_Bridge_(Da_Nang)","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/C%E1%BA%A7u_R%E1%BB%93ng.jpg/960px-C%E1%BA%A7u_R%E1%BB%93ng.jpg","https://goodmorning-hoian.com/wp-content/uploads/pont-du-dragon-danang-feu.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Da_Nang_Dragon_Bridge.jpg/960px-Da_Nang_Dragon_Bridge.jpg"]},{"id":"han-market","region":"central","area":"Da Nang","category":"markets","name":"Han Market","nameVi":"Chợ Hàn","lat":16.06835,"lng":108.22428,"address":"119 Tran Phu, Hai Chau, Da Nang","rating":4.0,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"","desc":{"en":"Da Nang's century-old central market: dried squid and fish sauce downstairs, rolls of fabric and fast tailors upstairs, plus snack stalls everywhere.","uk":"Столітній центральний ринок Дананґа: сушені кальмари й рибний соус унизу, рулони тканин і швидкі кравці нагорі, а всюди — лотки з перекусами."},"tip":{"en":"Haggle politely (start ~50%); the upstairs tailors can make clothes in 24 h. Morning is best for the food floor.","uk":"Ввічливо торгуйтеся (починайте з ~50%); кравці нагорі пошиють одяг за 24 год. Харчовий поверх найкращий зранку."},"hours":"06:00–19:00","website":"https://vi.wikipedia.org/wiki/Ch%E1%BB%A3_H%C3%A0n","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Han_Market_Da_Nang.JPG/960px-Han_Market_Da_Nang.JPG","https://upload.wikimedia.org/wikipedia/commons/thumb/8/8a/Han_Market_-_Da_Nang%2C_Vietnam_-_DSC02375.JPG/960px-Han_Market_-_Da_Nang%2C_Vietnam_-_DSC02375.JPG","https://upload.wikimedia.org/wikipedia/commons/thumb/6/66/Fabric_in_Han_Market_-_Da_Nang%2C_Vietnam_-_DSC02377.JPG/960px-Fabric_in_Han_Market_-_Da_Nang%2C_Vietnam_-_DSC02377.JPG"]},{"id":"da-nang-pink-cathedral","region":"central","area":"Da Nang","category":"sights","name":"Da Nang Cathedral (Pink 'Rooster' Church)","nameVi":"Nhà thờ Chính tòa Đà Nẵng (Nhà thờ Con Gà)","lat":16.06668,"lng":108.22306,"address":"156 Tran Phu, Hai Chau, Da Nang","rating":4.3,"googleRating":null,"price":0,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Instagram-famous pink church built in 1923","desc":{"en":"A candy-pink Gothic church from the French era, crowned by a rooster weathervane that gave it its local nickname 'Chicken Church'.","uk":"Цукерково-рожевий готичний храм французьких часів, увінчаний флюгером-півнем, через якого місцеві прозвали його «Курячою церквою»."},"tip":{"en":"Enter via the side gate on Yen Bai St; the interior is open only outside Mass times, so check before going in.","uk":"Заходьте через бічну браму з вулиці Єн Бай; всередину пускають лише поза месами, тож уточнюйте розклад."},"hours":"Grounds ~08:00–11:30, 13:30–16:30 (outside Mass)","website":"https://en.wikipedia.org/wiki/Da_Nang_Cathedral","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/Da_Nang_Cathedral_20190919.jpg/960px-Da_Nang_Cathedral_20190919.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/f/fe/Da_Nang_Cathedral_-_Da_Nang%2C_Vietnam_-_DSC02464.JPG/960px-Da_Nang_Cathedral_-_Da_Nang%2C_Vietnam_-_DSC02464.JPG"]},{"id":"museum-of-cham-sculpture","region":"central","area":"Da Nang","category":"museums","name":"Museum of Cham Sculpture","nameVi":"Bảo tàng Điêu khắc Chăm Đà Nẵng","lat":16.06012,"lng":108.22308,"address":"02 2 Thang 9 St (corner Bach Dang), Hai Chau, Da Nang","rating":4.4,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"World's largest collection of Cham art","desc":{"en":"A 1915 French-colonial pavilion housing the world's finest collection of Cham sandstone carvings — dancing apsaras, Shiva lingas and Ganeshas from My Son and other temples.","uk":"Колоніальний павільйон 1915 року з найкращою у світі колекцією чамської скульптури з пісковику — танцюючі апсари, лінгами Шиви та Ганеші з Мішона й інших храмів."},"tip":{"en":"Visit before My Son to understand what you'll see there; the free app/audio guide is worth downloading.","uk":"Відвідайте перед поїздкою в Мішон, щоб розуміти побачене; варто завантажити безкоштовний аудіогід."},"hours":"07:30–17:00","website":"https://www.chammuseum.vn","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/b/be/Le_mus%C3%A9e_Cham_%28Da_Nang%29_%284395751687%29.jpg/960px-Le_mus%C3%A9e_Cham_%28Da_Nang%29_%284395751687%29.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/f/fe/Ganesha%2C_Champa_Hindu_artwork%2C_Museum_of_Cham_Sculpture%2C_Da_Nang_Vietnam.jpg/960px-Ganesha%2C_Champa_Hindu_artwork%2C_Museum_of_Cham_Sculpture%2C_Da_Nang_Vietnam.jpg","https://goodmorning-hoian.com/wp-content/uploads/musee-danang-cham-2.jpg"]},{"id":"hai-van-pass","region":"central","area":"Hai Van Pass","category":"nature","name":"Hai Van Pass","nameVi":"Đèo Hải Vân","lat":16.18775,"lng":108.13129,"address":"QL1A between Da Nang and Lang Co (summit: Hai Van Gate)","rating":4.8,"googleRating":null,"price":0,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Top Gear Vietnam Special: 'a deserted ribbon of perfection'","desc":{"en":"A 21 km coastal mountain road snaking over the 'Pass of Ocean Clouds', with emerald bays below and the old Hai Van Gate fortress at the 496 m summit.","uk":"21-кілометрова гірська дорога над морем через «Перевал морських хмар» — смарагдові бухти внизу й стара фортеця Хайван-Ґейт на вершині 496 м."},"tip":{"en":"Ride it by motorbike or Easy Rider on the way between Da Nang and Hue, stopping at Lang Co lagoon; clouds often clear after 10:00.","uk":"Проїдьте його на мотоциклі чи з Easy Rider дорогою між Дананґом і Хюе із зупинкою біля лагуни Лангко; хмари часто розходяться після 10:00."},"hours":"24 h","website":"https://en.wikipedia.org/wiki/H%E1%BA%A3i_V%C3%A2n_Pass","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/L%C4%83ng_C%C3%B4%2C_H%E1%BA%A3i_V%C3%A2n_Pass%2C_2020-01_CN-01.jpg/960px-L%C4%83ng_C%C3%B4%2C_H%E1%BA%A3i_V%C3%A2n_Pass%2C_2020-01_CN-01.jpg","https://goodmorning-hoian.com/wp-content/uploads/sommet-col-des-nuages-vietnam.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/L%C4%83ng_C%C3%B4%2C_H%E1%BA%A3i_V%C3%A2n_Pass%2C_2020-01_CN-04.jpg/960px-L%C4%83ng_C%C3%B4%2C_H%E1%BA%A3i_V%C3%A2n_Pass%2C_2020-01_CN-04.jpg"]},{"id":"my-son-sanctuary","region":"central","area":"My Son","category":"temples","name":"My Son Sanctuary","nameVi":"Thánh địa Mỹ Sơn","lat":15.76552,"lng":108.12345,"address":"Duy Phu, ~40 km SW of Hoi An (now Da Nang city)","rating":4.5,"googleRating":null,"price":2,"mustSee":true,"hiddenGem":false,"viral":false,"hype":"UNESCO World Heritage Site","desc":{"en":"Moss-covered red-brick Hindu temple towers of the Champa kingdom (4th–13th c.) scattered through a jungle valley beneath Cat's Tooth Mountain.","uk":"Порослі мохом цегляні індуїстські вежі королівства Тямпа (IV–XIII ст.), розкидані в джунглевій долині під горою Котячий Зуб."},"tip":{"en":"Arrive at 06:00 opening to beat heat and tour buses; stay for the Apsara dance performance (several times daily).","uk":"Приїжджайте до відкриття о 06:00, щоб уникнути спеки й автобусів; лишіться на танець апсар (кілька разів на день)."},"hours":"06:00–17:30","website":"https://en.wikipedia.org/wiki/M%E1%BB%B9_S%C6%A1n","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/2024_-_M%E1%BB%B9_S%C6%A1n_Sanctuary_Temple_E7_-_img_01.jpg/960px-2024_-_M%E1%BB%B9_S%C6%A1n_Sanctuary_Temple_E7_-_img_01.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/My_Son_Sanctuary_Vietnam_06.jpg/960px-My_Son_Sanctuary_Vietnam_06.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/e/ed/My_Son_Sanctuary_Vietnam_07.jpg/960px-My_Son_Sanctuary_Vietnam_07.jpg"]},{"id":"hoi-an-ancient-town","region":"central","area":"Hoi An","category":"sights","name":"Hoi An Ancient Town","nameVi":"Phố cổ Hội An","lat":15.877,"lng":108.328,"address":"Tran Phu / Nguyen Thai Hoc / Bach Dang streets, Hoi An","rating":4.8,"googleRating":null,"price":1,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"UNESCO World Heritage Site; lantern photos flood Instagram","desc":{"en":"A remarkably preserved 15th–19th-century trading port of mustard-yellow merchant houses, Chinese assembly halls and silk lanterns that glow over the Thu Bon River at night.","uk":"Дивовижно збережений торговий порт XV–XIX ст.: гірчично-жовті купецькі будинки, китайські зали громад і шовкові ліхтарі, що світяться над річкою Тхубон уночі."},"tip":{"en":"Buy the heritage ticket (5 sights); stroll at 06:00 for empty streets, return after 18:00 for lanterns. The centre is car-free.","uk":"Купіть квиток на спадщину (5 об'єктів); гуляйте о 06:00 порожніми вулицями й поверніться після 18:00 до ліхтарів. Центр закритий для авто."},"hours":"24 h (ticketed sights ~07:00–21:30)","website":"https://en.wikipedia.org/wiki/H%E1%BB%99i_An_Old_Town","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/10549-Hoi-An_%2837621348460%29.jpg/960px-10549-Hoi-An_%2837621348460%29.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/b/b0/H%E1%BB%99i_An%2C_Ancient_Town%2C_2020-01_CN-10.jpg/960px-H%E1%BB%99i_An%2C_Ancient_Town%2C_2020-01_CN-10.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/H%E1%BB%99i_An%2C_Ancient_Town%2C_2020-01_CN-04.jpg/960px-H%E1%BB%99i_An%2C_Ancient_Town%2C_2020-01_CN-04.jpg"]},{"id":"japanese-covered-bridge","region":"central","area":"Hoi An","category":"sights","name":"Japanese Covered Bridge","nameVi":"Chùa Cầu","lat":15.87715,"lng":108.326,"address":"Nguyen Thi Minh Khai / Tran Phu, Hoi An","rating":4.6,"googleRating":null,"price":1,"mustSee":true,"hiddenGem":false,"viral":false,"hype":"Pictured on the 20,000 VND banknote","desc":{"en":"Hoi An's 1590s symbol: a vermilion wooden bridge with a tiny pagoda inside, guarded by monkey and dog statues; freshly restored in 2024.","uk":"Символ Хойана з 1590-х: червоний дерев'яний міст із крихітною пагодою всередині, який стережуть статуї мавп і собак; реставрований у 2024 році."},"tip":{"en":"Walking across uses a heritage-ticket coupon; for photos, come at dawn or shoot it lit-up from the riverbank at night.","uk":"Прохід мостом списує купон квитка спадщини; для фото приходьте на світанку або знімайте підсвічений міст із берега вночі."},"hours":"07:00–21:30","website":"https://en.wikipedia.org/wiki/Japanese_Bridge","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/b/b8/2024_H%E1%BB%99i_An_-_Japanese_Covered_Bridge_%28Ch%C3%B9a_C%E1%BA%A7u%29_after_renovation_-_img_11.jpg/960px-2024_H%E1%BB%99i_An_-_Japanese_Covered_Bridge_%28Ch%C3%B9a_C%E1%BA%A7u%29_after_renovation_-_img_11.jpg","https://goodmorning-hoian.com/wp-content/uploads/hoi-an-pont-couvert-japonais.jpg"]},{"id":"hoi-an-lantern-boat-ride","region":"central","area":"Hoi An","category":"experiences","name":"Lantern Boat Ride on the Thu Bon River","nameVi":"Thả đèn hoa đăng sông Hoài","lat":15.8763,"lng":108.327,"address":"Bach Dang riverside / An Hoi bridge, Hoi An","rating":4.4,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"TikTok/Instagram favourite: floating wishing lanterns","desc":{"en":"Drift along the Hoai River at dusk in a wooden sampan lit with lanterns and release a paper candle-lantern for luck among hundreds of flickering lights.","uk":"Пропливіть річкою Хоай у сутінках дерев'яним сампаном з ліхтариками й відпустіть на воду паперовий ліхтарик-свічку на щастя серед сотень вогників."},"tip":{"en":"Agree on the price per boat (not per person) before boarding — ~150,000–200,000 VND for 15–20 min is normal; full-moon nights are magical but packed.","uk":"Домовтеся про ціну за човен (а не за людину) до посадки — нормально ~150–200 тис. VND за 15–20 хв; ночі повного місяця чарівні, але людні."},"hours":"~17:30–22:00","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/c/cc/Boats_with_lanterns_on_the_Thu_Bon_river_IMG_3864.jpg/960px-Boats_with_lanterns_on_the_Thu_Bon_river_IMG_3864.jpg","https://goodmorning-hoian.com/wp-content/uploads/festival-hoi-an-lanternes.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Hoi_An_-_HoiAn1441.jpg/960px-Hoi_An_-_HoiAn1441.jpg"]},{"id":"hoi-an-night-market","region":"central","area":"Hoi An","category":"markets","name":"Hoi An Night Market","nameVi":"Chợ đêm Hội An","lat":15.87578,"lng":108.32593,"address":"Nguyen Hoang St, An Hoi islet, Hoi An","rating":4.0,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"","desc":{"en":"A lantern-canopied street of souvenir stalls and sizzling snacks across the An Hoi bridge — grilled pork skewers, banh xeo and mango sticky rice.","uk":"Вулиця під навісом із ліхтарів за мостом Ан Хой: сувенірні лотки й шиплячі закуски — шашлички зі свинини, баньсео та манго з клейким рисом."},"tip":{"en":"Eat here, shop elsewhere: food is fair, souvenirs are marked up 2–3×. Go around 18:00 before the crush.","uk":"Їжте тут, а сувеніри купуйте деінде: їжа за чесною ціною, сувеніри — у 2–3 рази дорожче. Приходьте близько 18:00, до тисняви."},"hours":"17:00–22:00","website":"","images":["https://goodmorning-hoian.com/wp-content/uploads/marche-de-nuit-hoi-an-lanternes.jpg","https://goodmorning-hoian.com/wp-content/uploads/2019/10/marche-de-nuit-hoi-an.jpg","https://goodmorning-hoian.com/wp-content/uploads/2019/10/marche-nocturne-hoi-an-vietnam.jpg"]},{"id":"an-bang-beach","region":"central","area":"Hoi An","category":"beaches","name":"An Bang Beach","nameVi":"Bãi biển An Bàng","lat":15.91418,"lng":108.33966,"address":"Hai Ba Trung (north end), Cam An, Hoi An","rating":4.4,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"CNN-listed among Asia's best beaches","desc":{"en":"Hoi An's laid-back beach, 4 km from the old town: soft sand, sun loungers free with a drink, and barefoot seafood shacks facing Cu Lao Cham islands.","uk":"Розслаблений пляж Хойана за 4 км від старого міста: м'який пісок, шезлонги безкоштовно при замовленні напою й прості морські ресторанчики з видом на острови Кулаочам."},"tip":{"en":"Cycle there via the rice paddies of Tra Que; erosion has narrowed the sand in places, so walk north for wider stretches.","uk":"Їдьте велосипедом через рисові поля Чакуе; ерозія місцями звузила пляж, тож ідіть північніше — там ширше."},"hours":"24 h","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/b/b0/2024-11-23_An_Bang_Beach_in_Hoi_An_in_November.jpg/960px-2024-11-23_An_Bang_Beach_in_Hoi_An_in_November.jpg","https://goodmorning-hoian.com/wp-content/uploads/plage-de-an-bang-hoi-an.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/4/40/Playa_An_Bang%2C_Hoi_An%2C_Vietnam_%2839510560665%29.jpg/960px-Playa_An_Bang%2C_Hoi_An%2C_Vietnam_%2839510560665%29.jpg"]},{"id":"cam-thanh-basket-boats","region":"central","area":"Hoi An","category":"experiences","name":"Cam Thanh Coconut Forest Basket Boats","nameVi":"Rừng dừa Bảy Mẫu Cẩm Thanh","lat":15.88556,"lng":108.36788,"address":"Bay Mau Coconut Forest, Cam Thanh, Hoi An","rating":4.3,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Viral 'spinning basket boat' videos on TikTok","desc":{"en":"Paddle through water-coconut palm channels in a round bamboo thung chai; boatmen spin you like a top to blaring music and fold palm-leaf crabs and rings for you.","uk":"Пропливіть каналами серед водяних пальм у круглому бамбуковому човні-кошику: човнярі крутять вас дзиґою під гучну музику й плетуть із листя крабів і каблучки."},"tip":{"en":"Book direct at the forest (~150,000–200,000 VND/person) rather than via touts on the road; the 'spinning' and fishing add-ons cost extra tips.","uk":"Купуйте прямо біля лісу (~150–200 тис. VND з особи), а не в зазивал на дорозі; «кручення» й риболовля — за додаткові чайові."},"hours":"08:00–17:00","website":"","images":["https://goodmorning-hoian.com/wp-content/uploads/cam-thanh-village-hoi-an.jpeg","https://upload.wikimedia.org/wikipedia/commons/thumb/8/82/Basket_Boat_and_the_Bamboo_forest_%28Unsplash%29.jpg/960px-Basket_Boat_and_the_Bamboo_forest_%28Unsplash%29.jpg"]},{"id":"tra-que-vegetable-village","region":"central","area":"Hoi An","category":"experiences","name":"Tra Que Vegetable Village","nameVi":"Làng rau Trà Quế","lat":15.90271,"lng":108.33602,"address":"Cam Ha, between Hoi An and An Bang Beach","rating":4.3,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"","desc":{"en":"A 300-year-old organic herb village where farmers water fragrant basil and mint beds by hand with shoulder-pole cans, fertilised with lagoon seaweed.","uk":"300-річне органічне село трав, де фермери вручну поливають грядки запашного базиліку й м'яти з лійок на коромислі, удобрюючи водоростями з лагуни."},"tip":{"en":"Cycle in early morning or late afternoon; a farm-and-cooking class here includes planting with a farmer and a herb foot massage.","uk":"Їдьте велосипедом рано вранці або надвечір; кулінарний клас тут включає садіння з фермером і масаж ніг травами."},"hours":"Daylight hours","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Tra_Que_Village%2C_Hoi_An_%2846404326471%29.jpg/960px-Tra_Que_Village%2C_Hoi_An_%2846404326471%29.jpg","https://goodmorning-hoian.com/wp-content/uploads/tra-que-vegetable-village.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/Tra_Que_Village%2C_Hoi_An_%2846404328621%29.jpg/960px-Tra_Que_Village%2C_Hoi_An_%2846404328621%29.jpg"]},{"id":"thanh-ha-pottery-village","region":"central","area":"Hoi An","category":"experiences","name":"Thanh Ha Pottery Village & Terracotta Park","nameVi":"Làng gốm Thanh Hà","lat":15.87713,"lng":108.29899,"address":"Pham Phan, Thanh Ha, 3 km west of Hoi An","rating":4.1,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"","desc":{"en":"A 500-year-old riverside potters' village where artisans still throw clay on foot-powered wheels; the brick Terracotta Park displays miniature world landmarks in clay.","uk":"500-річне гончарне село на березі річки, де майстри досі ліплять на ножному гончарному крузі; цегляний Парк теракоти показує мініатюри світових пам'яток із глини."},"tip":{"en":"Try the wheel yourself at a family workshop and buy a clay whistle — small purchases are the main income for the elderly potters.","uk":"Спробуйте гончарний круг у сімейній майстерні й купіть глиняну свистульку — дрібні покупки є головним доходом літніх гончарів."},"hours":"08:00–17:30","website":"","images":["https://goodmorning-hoian.com/wp-content/uploads/village-de-poteries-thanh-ha-hoi-an-.jpg"]},{"id":"cu-lao-cham-islands","region":"central","area":"Cu Lao Cham","category":"nature","name":"Cu Lao Cham Islands","nameVi":"Cù Lao Chàm","lat":15.96107,"lng":108.50238,"address":"Bai Lang, Tan Hiep island commune (speedboat from Cua Dai, Hoi An)","rating":4.4,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"UNESCO World Biosphere Reserve","desc":{"en":"Eight jungle-topped islands 15 km off Hoi An with clear water, coral gardens for snorkelling, plastic-bag-free fishing villages and quiet coves.","uk":"Вісім вкритих джунглями островів за 15 км від Хойана: прозора вода, коралові сади для снорклінгу, рибальські села без пластикових пакетів і тихі бухти."},"tip":{"en":"Go Mar–Aug only; boats stop in rough season (~Sep–Jan). Stay overnight in a Bai Huong homestay to enjoy it after the day-trippers leave.","uk":"Їдьте лише з березня по серпень; у сезон штормів (~вересень–січень) човни не ходять. Заночуйте в homestay у Бай Хионг, коли поїдуть одноденні туристи."},"hours":"Boats ~07:30–16:00 (Mar–Aug)","website":"https://en.wikipedia.org/wiki/C%C3%B9_Lao_Ch%C3%A0m","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/5/58/Cu_Lao_Cham_Marine_Park%2C_Vietnam.jpg/960px-Cu_Lao_Cham_Marine_Park%2C_Vietnam.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/8/8a/Cu_Lao_Cham%2C_6740-4.jpg/960px-Cu_Lao_Cham%2C_6740-4.jpg"]},{"id":"hue-imperial-city","region":"central","area":"Hue","category":"sights","name":"Imperial City (Hue Citadel)","nameVi":"Đại Nội Huế","lat":16.46773,"lng":107.57915,"address":"Ngo Mon Gate, 23/8 St, Phu Xuan, Hue","rating":4.6,"googleRating":null,"price":2,"mustSee":true,"hiddenGem":false,"viral":false,"hype":"UNESCO World Heritage Site; seat of the Nguyen emperors","desc":{"en":"The walled seat of Vietnam's last dynasty: moats, the grand Ngo Mon gate, lacquered throne halls and gardens of the Forbidden Purple City, part restored, part atmospheric ruin.","uk":"Обнесена мурами резиденція останньої династії В'єтнаму: рови, величні ворота Нгомон, лаковані тронні зали й сади Пурпурового Забороненого міста — частково відновлені, частково атмосферні руїни."},"tip":{"en":"Allow at least 3 h and rent an electric buggy or bike in the heat; on certain nights the palace opens until 22:00 with lighting.","uk":"Закладіть щонайменше 3 год і в спеку візьміть електрокар чи велосипед; у деякі вечори палац працює до 22:00 з підсвіткою."},"hours":"07:00–17:30 (some nights to 22:00)","website":"https://en.wikipedia.org/wiki/Imperial_City_of_Hu%E1%BA%BF","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/Meridian_Gate%2C_Hue_%28I%29.jpg/960px-Meridian_Gate%2C_Hue_%28I%29.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Vietnam%2C_Hue%2C_Imperial_City_of_Hue%2C_Meridian_Gate_2.jpg/960px-Vietnam%2C_Hue%2C_Imperial_City_of_Hue%2C_Meridian_Gate_2.jpg","https://goodmorning-hoian.com/wp-content/uploads/cite-imperiale-hue.jpg"]},{"id":"tomb-of-tu-duc","region":"central","area":"Hue","category":"sights","name":"Tomb of Tu Duc","nameVi":"Lăng Tự Đức","lat":16.43304,"lng":107.56552,"address":"17/69 Le Ngo Cat, Thuy Xuan, Hue","rating":4.5,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"UNESCO (Complex of Hue Monuments)","desc":{"en":"The poet-emperor's romantic retreat: lotus lake, pavilions and frangipani-shaded pine groves where Tu Duc wrote verse — though he was never buried here.","uk":"Романтичний притулок імператора-поета: лотосове озеро, павільйони й соснові гаї з франжипані, де Ти Дик писав вірші, хоча похований він не тут."},"tip":{"en":"Combine with Khai Dinh and Minh Mang by bike or car; pick up a combo ticket at the Imperial City to save money.","uk":"Поєднайте з гробницями Кхай Дінь і Мінь Манг на велосипеді чи авто; комбінований квиток в Імператорському місті дешевший."},"hours":"07:00–17:30","website":"https://en.wikipedia.org/wiki/Tomb_of_T%E1%BB%B1_%C4%90%E1%BB%A9c","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/8/8c/Hue_Vietnam_Tomb-of-Emperor-Tu-Duc-05.jpg/960px-Hue_Vietnam_Tomb-of-Emperor-Tu-Duc-05.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/0/09/Hue_-_Tomb_of_Emperor_Tu_Duc_-_002.jpg/960px-Hue_-_Tomb_of_Emperor_Tu_Duc_-_002.jpg"]},{"id":"tomb-of-khai-dinh","region":"central","area":"Hue","category":"sights","name":"Tomb of Khai Dinh","nameVi":"Lăng Khải Định","lat":16.39902,"lng":107.59034,"address":"Khai Dinh St, Thuy Bang, Hue","rating":4.7,"googleRating":null,"price":2,"mustSee":true,"hiddenGem":false,"viral":false,"hype":"","desc":{"en":"A dramatic hillside mausoleum of blackened concrete outside and a dazzling glass-and-porcelain mosaic interior — East meets art-deco Europe.","uk":"Драматичний мавзолей на схилі: ззовні почорнілий бетон, усередині — сліпуча мозаїка зі скла й порцеляни; Схід зустрічається з європейським ар-деко."},"tip":{"en":"127 steep steps lead up — go early morning; the mosaic burial chamber is best seen when sunlight hits it before noon.","uk":"Нагору ведуть 127 крутих сходинок — ідіть зранку; мозаїчну залу найкраще видно, коли до полудня туди падає сонце."},"hours":"07:00–17:30","website":"https://en.wikipedia.org/wiki/Tomb_of_Kh%E1%BA%A3i_%C4%90%E1%BB%8Bnh","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/6/6b/Hu%E1%BA%BF_%282024%29_-_Mausoleum_of_Emperor_Kh%E1%BA%A3i_%C4%90%E1%BB%8Bnh_-_exterior_-_img_01.jpg/960px-Hu%E1%BA%BF_%282024%29_-_Mausoleum_of_Emperor_Kh%E1%BA%A3i_%C4%90%E1%BB%8Bnh_-_exterior_-_img_01.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/Emperor_Khai_Dinh_in_Hue_%2839543600561%29.jpg/960px-Emperor_Khai_Dinh_in_Hue_%2839543600561%29.jpg"]},{"id":"tomb-of-minh-mang","region":"central","area":"Hue","category":"sights","name":"Tomb of Minh Mang","nameVi":"Lăng Minh Mạng","lat":16.38775,"lng":107.56778,"address":"Huong Tho, on the Perfume River ~12 km south of Hue","rating":4.5,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"","desc":{"en":"The most harmonious of Hue's royal tombs: a symmetrical axis of gates, courtyards and pavilions mirrored in crescent lakes amid pine forest.","uk":"Найгармонійніша з королівських гробниць Хюе: симетрична вісь воріт, дворів і павільйонів, що віддзеркалюються в серпоподібних озерах серед соснового лісу."},"tip":{"en":"Fewer crowds than Khai Dinh; arrive by Perfume River dragon boat for the classic approach.","uk":"Тут менше людей, ніж у Кхай Діня; припливіть драконовим човном по Ароматній річці — класичний маршрут."},"hours":"07:00–17:30","website":"https://en.wikipedia.org/wiki/Tomb_of_Minh_M%E1%BA%A1ng","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Hue_Vietnam_Tomb-of-Emperor-Minh-Mang-03a.jpg/960px-Hue_Vietnam_Tomb-of-Emperor-Minh-Mang-03a.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Hue_Vietnam_Tomb-of-Emperor-Minh-Mang-01.jpg/960px-Hue_Vietnam_Tomb-of-Emperor-Minh-Mang-01.jpg"]},{"id":"thien-mu-pagoda","region":"central","area":"Hue","category":"temples","name":"Thien Mu Pagoda","nameVi":"Chùa Thiên Mụ","lat":16.45372,"lng":107.54458,"address":"Nguyen Phuc Nguyen St, Kim Long, Hue","rating":4.6,"googleRating":null,"price":0,"mustSee":true,"hiddenGem":false,"viral":false,"hype":"","desc":{"en":"Hue's 1601 seven-storey Phuoc Duyen tower rises over the Perfume River; the temple also keeps the Austin car that monk Thich Quang Duc drove to his 1963 self-immolation.","uk":"Семиповерхова вежа Фуок Зуєн (1601) височіє над Ароматною річкою; у храмі також зберігається «Остін», на якому монах Тхить Куанг Дик приїхав на самоспалення 1963 року."},"tip":{"en":"Go around 16:00 to hear the monks' chanting and watch sunset over the river; arrive by boat from the city for the best view.","uk":"Приходьте близько 16:00, щоб почути спів ченців і побачити захід над річкою; найкращий вид — якщо припливти човном із міста."},"hours":"08:00–18:00","website":"https://en.wikipedia.org/wiki/Thi%C3%AAn_M%E1%BB%A5_Temple","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/ThienMuPagoda.jpg/960px-ThienMuPagoda.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/4/46/Thien_mu_5v.jpg/960px-Thien_mu_5v.jpg"]},{"id":"ho-thuy-tien-abandoned-water-park","region":"central","area":"Hue","category":"sights","name":"Ho Thuy Tien Abandoned Water Park","nameVi":"Hồ Thủy Tiên","lat":16.40993,"lng":107.57632,"address":"Thuy Bang, off QL49, ~8 km south of Hue","rating":4.2,"googleRating":null,"price":0,"mustSee":false,"hiddenGem":true,"viral":true,"hype":"Viral urban-exploration spot; featured in UK press and countless YouTube vlogs","desc":{"en":"A jungle-swallowed water park abandoned around 2011, where a giant concrete dragon rises from a lake — the eeriest photo op in Vietnam.","uk":"Покинутий близько 2011 року аквапарк, поглинутий джунглями, де з озера здіймається велетенський бетонний дракон — найзловісніша фотолокація В'єтнаму."},"tip":{"en":"The city is converting the site into a public park (paths, lighting), so access and fees may change — check recent reviews; go in daylight with sturdy shoes.","uk":"Місто перетворює територію на громадський парк (доріжки, освітлення), тож доступ і плата можуть змінитися — перевірте свіжі відгуки; ідіть удень у міцному взутті."},"hours":"Daylight hours","website":"https://en.wikipedia.org/wiki/H%E1%BB%93_Th%E1%BB%A7y_Ti%C3%AAn","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/8/87/Ho_Thuy_Tien_water_park.jpg/960px-Ho_Thuy_Tien_water_park.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/Ho_Thuy_Tien_water_park_entrance.jpg/960px-Ho_Thuy_Tien_water_park_entrance.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/2/2f/S%C3%A2n_kh%E1%BA%A5u_c%C3%B4ng_vi%C3%AAn_h%E1%BB%93_Th%E1%BB%A7y_Ti%C3%AAn%2C_Hu%E1%BA%BF_%2850800093051%29.jpg/960px-S%C3%A2n_kh%E1%BA%A5u_c%C3%B4ng_vi%C3%AAn_h%E1%BB%93_Th%E1%BB%A7y_Ti%C3%AAn%2C_Hu%E1%BA%BF_%2850800093051%29.jpg"]},{"id":"dong-ba-market","region":"central","area":"Hue","category":"markets","name":"Dong Ba Market","nameVi":"Chợ Đông Ba","lat":16.47245,"lng":107.58865,"address":"Tran Hung Dao St, Phu Xuan, Hue","rating":4.0,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Bourdain filmed Hue's bun bo here (Parts Unknown)","desc":{"en":"Hue's biggest market by the Perfume River: conical hats, sesame candy and mè xửng, and a hectic food section serving bun bo Hue and banh beo.","uk":"Найбільший ринок Хюе біля Ароматної річки: конічні капелюхи, кунжутні цукерки ме сунг і гамірний харчовий ряд із бун бо Хюе та бань бео."},"tip":{"en":"Head straight to the food stalls at the back for breakfast before 09:00; buy nón lá hats here for a fraction of tourist-shop prices.","uk":"Ідіть одразу до харчових лотків у глибині на сніданок до 09:00; конічні капелюхи нон ла тут коштують у рази менше, ніж у сувенірних крамницях."},"hours":"06:00–19:00","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/Dong_Ba_Market_%28Hue%29_-_Ch%E1%BB%A3_%C4%90%C3%B4ng_Ba_Hu%E1%BA%BF_%28July_2024%29_-_img_02.jpg/960px-Dong_Ba_Market_%28Hue%29_-_Ch%E1%BB%A3_%C4%90%C3%B4ng_Ba_Hu%E1%BA%BF_%28July_2024%29_-_img_02.jpg"]},{"id":"thanh-toan-tile-roofed-bridge","region":"central","area":"Hue","category":"sights","name":"Thanh Toan Tile-Roofed Bridge","nameVi":"Cầu ngói Thanh Toàn","lat":16.46679,"lng":107.6427,"address":"Thanh Toan village, Thuy Thanh, ~8 km east of Hue","rating":4.3,"googleRating":null,"price":0,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"","desc":{"en":"A 1776 wooden bridge with a tiled roof spanning a canal amid rice fields, where villagers nap on its benches — a peaceful rural cousin of Hoi An's Japanese Bridge.","uk":"Дерев'яний міст 1776 року під черепичним дахом над каналом серед рисових полів, де селяни дрімають на лавках — тихий сільський «родич» Японського мосту в Хойані."},"tip":{"en":"Cycle out through the rice paddies in the late afternoon; the small farming-tools museum nearby is free.","uk":"Їдьте велосипедом через рисові поля надвечір; невеликий музей сільськогосподарського знаряддя поруч безкоштовний."},"hours":"24 h","website":"https://vi.wikipedia.org/wiki/C%E1%BA%A7u_ng%C3%B3i_Thanh_To%C3%A0n","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/2/25/C%E1%BA%A7u_ng%C3%B3i_Thanh_To%C3%A0n1.jpg/960px-C%E1%BA%A7u_ng%C3%B3i_Thanh_To%C3%A0n1.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/Thanh_Toan_tile-roofed_bridge_%2839598974915%29.jpg/960px-Thanh_Toan_tile-roofed_bridge_%2839598974915%29.jpg"]},{"id":"bun-cha-ca-109","region":"central","area":"Da Nang","category":"streetfood","name":"Bun Cha Ca 109","nameVi":"Bún Chả Cá 109","lat":16.07452,"lng":108.22075,"address":"109 Nguyen Chi Thanh, Hai Chau, Da Nang","rating":4.5,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"MICHELIN Bib Gourmand","desc":{"en":"Da Nang's signature fish-cake noodle soup: a sweet-savoury broth of fish bones and pumpkin with springy fried and steamed cha ca slices.","uk":"Фірмовий суп Дананґа з рибними котлетками: солодкувато-пряний бульйон із риб'ячих кісток і гарбуза з пружними смаженими й паровими шматочками ча ка."},"tip":{"en":"Add a spoon of the house chilli-shrimp paste and a squeeze of lime; it's busiest at breakfast, so go mid-morning.","uk":"Додайте ложку фірмової пасти з чилі та креветок і вичавіть лайм; найбільше людей на сніданок, тож приходьте ближче до обіду."},"hours":"06:30–22:00","website":"https://guide.michelin.com/en/da-nang-region/da-nang/restaurant/bun-cha-ca-109","images":["https://prod-pics.guide.michelin.com/api/public/content/3c9f1bd7c4704f7da901b1a1ecb4489e.jpeg"]},{"id":"mi-quang-1a","region":"central","area":"Da Nang","category":"streetfood","name":"Mi Quang 1A","nameVi":"Mì Quảng 1A","lat":16.07227,"lng":108.21917,"address":"1A Hai Phong, Hai Chau, Da Nang","rating":4.3,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"MICHELIN Selected; Da Nang institution since 1975","desc":{"en":"The classic address for mì Quảng — wide turmeric rice noodles in a shallow, intense broth with shrimp, pork, quail egg, peanuts and a sesame cracker.","uk":"Класична адреса для мі Куанг — широка рисова локшина з куркумою в невеликій кількості насиченого бульйону з креветками, свининою, перепелиним яйцем, арахісом і кунжутним крекером."},"tip":{"en":"Break the sesame cracker over the bowl and toss in the fresh herbs; try the 'đặc biệt' (special) with chicken and pork.","uk":"Покришіть кунжутний крекер у миску й додайте свіжу зелень; спробуйте «дак бьєт» (спеціальну) з куркою та свининою."},"hours":"06:00–21:00","website":"https://guide.michelin.com/en/da-nang-region/da-nang/restaurant/mi-quang-1a","images":["https://prod-pics.guide.michelin.com/api/public/content/c03a7bef0dbb47fe8381d1fd4bc5f813.jpeg"]},{"id":"banh-xeo-ba-duong","region":"central","area":"Da Nang","category":"streetfood","name":"Banh Xeo Ba Duong","nameVi":"Bánh Xèo Bà Dưỡng","lat":16.05884,"lng":108.21605,"address":"K280/23 Hoang Dieu (end of the alley), Hai Chau, Da Nang","rating":4.5,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"MICHELIN Selected; alley legend","desc":{"en":"Hidden at the end of a narrow alley, this family joint fries crispy turmeric pancakes with shrimp and pork, rolled with herbs in rice paper and dunked in a famous liver-peanut sauce.","uk":"Захований у кінці вузького провулка сімейний заклад смажить хрусткі млинці з куркумою, креветками та свининою; їх загортають із зеленню в рисовий папір і вмочають у знаменитий соус з печінки та арахісу."},"tip":{"en":"Don't fill up on the nem lui (lemongrass pork skewers) brought automatically — you pay only for what you eat.","uk":"Не наїдайтеся нем луй (шашличками зі свинини на лемонграсі), які приносять автоматично, — платите лише за з'їдене."},"hours":"09:30–21:30","website":"https://guide.michelin.com/en/da-nang-region/da-nang/restaurant/banh-xeo-ba-duong","images":["https://prod-pics.guide.michelin.com/api/public/content/4a6360958af84e40a16e3c4b1c6fdc25.jpeg","https://prod-pics.guide.michelin.com/api/public/content/269050418640442ebd85ad66a4dd4c78.jpeg"]},{"id":"madame-lan","region":"central","area":"Da Nang","category":"restaurants","name":"Madame Lân","nameVi":"Nhà hàng Madame Lân","lat":16.0813,"lng":108.22329,"address":"4 Bach Dang, Hai Chau, Da Nang","rating":4.2,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"MICHELIN Selected","desc":{"en":"A grand Indochine-style courtyard restaurant on the Han River serving a huge menu of central Vietnamese specialities — a one-stop tasting of the region.","uk":"Велика ресторанна садиба в стилі Індокитаю на річці Хан з величезним меню страв Центрального В'єтнаму — уся кухня регіону в одному місці."},"tip":{"en":"Great first-night intro to local dishes for groups; order banh xeo, mi Quang and grilled fish to share.","uk":"Чудове знайомство з місцевою кухнею першого вечора для компанії; замовте на всіх баньсео, мі Куанг і рибу на грилі."},"hours":"06:30–21:30","website":"https://guide.michelin.com/en/da-nang-region/da-nang/restaurant/madame-lan","images":["https://prod-pics.guide.michelin.com/api/public/content/81718ce3068c4de284235e8c453929eb.jpeg","https://prod-pics.guide.michelin.com/api/public/content/b05d140447e244ac8e8006706b1c2f79.jpeg","https://prod-pics.guide.michelin.com/api/public/content/d5ba20a7a0c94724a9b05f5dc8dde0c3.jpeg"]},{"id":"la-maison-1888","region":"central","area":"Da Nang","category":"restaurants","name":"La Maison 1888","nameVi":"La Maison 1888","lat":16.12189,"lng":108.30664,"address":"InterContinental Danang Sun Peninsula Resort, Son Tra Peninsula, Da Nang","rating":4.8,"googleRating":null,"price":4,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"One MICHELIN Star (Da Nang's only starred restaurant)","desc":{"en":"Fine French-Indochine dining in a colonial-style villa perched on Son Tra's jungle slopes above the sea, inside the Bill Bensley-designed InterContinental.","uk":"Вишукана франко-індокитайська кухня у віллі в колоніальному стилі на джунглевих схилах Шонча над морем, у курорті InterContinental за проєктом Білла Бенслі."},"tip":{"en":"Book weeks ahead and arrive before sunset for cocktails with the bay view; smart dress code.","uk":"Бронюйте за кілька тижнів і приїжджайте до заходу сонця на коктейль із видом на затоку; дрес-код smart."},"hours":"Dinner ~18:00–22:00 (closed some weekdays)","website":"https://guide.michelin.com/en/da-nang-region/da-nang/restaurant/la-maison-1888","images":["https://prod-pics.guide.michelin.com/api/public/content/a618abad7df7432284735395bd42aedd.jpeg","https://prod-pics.guide.michelin.com/api/public/content/e631ea29ba5e4678867e4c048c44d7e5.jpeg","https://prod-pics.guide.michelin.com/api/public/content/a749bbf5ef3b4d678017092b7055d7ed.jpg"]},{"id":"nen-danang","region":"central","area":"Da Nang","category":"restaurants","name":"Nén Danang","nameVi":"Nhà hàng Nén Đà Nẵng","lat":16.03466,"lng":108.24062,"address":"16 My Da Tay 2, Ngu Hanh Son, Da Nang","rating":4.7,"googleRating":null,"price":4,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"MICHELIN Green Star","desc":{"en":"Chef Summer Le's seasonal tasting menu reinterprets Vietnamese heritage and foraged local produce with fermentation and storytelling — sustainable, playful, unforgettable.","uk":"Сезонне дегустаційне меню шефа Саммер Ле переосмислює в'єтнамську спадщину та місцеві дикорослі продукти через ферментацію й історії — екологічно, грайливо, незабутньо."},"tip":{"en":"Dinner-only tasting menu — reserve online well in advance and mention dietary needs; the drinks pairing uses local fruit wines.","uk":"Лише дегустаційна вечеря — бронюйте онлайн заздалегідь і вкажіть дієтичні обмеження; пейринг напоїв — на місцевих фруктових винах."},"hours":"Dinner ~17:30–22:00 (closed Mon)","website":"https://guide.michelin.com/en/da-nang-region/da-nang/restaurant/nen-danang","images":["https://prod-pics.guide.michelin.com/api/public/content/500f1aa5a83048e8bbb70af05235a7c0.jpeg","https://prod-pics.guide.michelin.com/api/public/content/0f48fb022b494e429883f40f13c32701.jpg","https://prod-pics.guide.michelin.com/api/public/content/c4490f32127047d4af67984603ceed9d.jpg"]},{"id":"cong-caphe-da-nang","region":"central","area":"Da Nang","category":"cafes","name":"Cong Caphe (coconut coffee)","nameVi":"Cộng Cà Phê Bạch Đằng","lat":16.06903,"lng":108.22497,"address":"98-96 Bach Dang, Hai Chau, Da Nang","rating":4.3,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Social-media famous coconut coffee","desc":{"en":"Retro communist-chic décor, Han River views and the city's favourite cốt dừa cà phê — strong Vietnamese coffee blended with frozen coconut cream.","uk":"Ретро-декор у стилі соцреалізму, вид на річку Хан і улюблена кава міста — міцна в'єтнамська кава, збита із замороженими кокосовими вершками."},"tip":{"en":"Grab a balcony seat on the upper floor at sunset to watch the Dragon Bridge light up.","uk":"Займіть місце на балконі верхнього поверху під час заходу сонця й дивіться, як вмикається підсвітка Мосту Дракона."},"hours":"07:00–23:00","website":"https://congcaphe.com","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/b/b4/C%C3%A0_Ph%C3%AA_S%E1%BB%AFa_%C4%90%C3%A1_V%E1%BB%8B_Coconut.jpg/960px-C%C3%A0_Ph%C3%AA_S%E1%BB%AFa_%C4%90%C3%A1_V%E1%BB%8B_Coconut.jpg"]},{"id":"sky36-da-nang","region":"central","area":"Da Nang","category":"bars","name":"Sky36","nameVi":"Sky36 Bar","lat":16.07746,"lng":108.22356,"address":"Floors 35–37, Novotel Danang Premier Han River, 36 Bach Dang, Da Nang","rating":4.2,"googleRating":null,"price":3,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Da Nang's highest rooftop bar","desc":{"en":"The city's highest rooftop bar, 36 floors up, with neon-lit lounge, DJs and a 360° panorama of the Han River's illuminated bridges.","uk":"Найвищий бар на даху в місті, на 36-му поверсі: неонова лаунж-зона, діджеї та панорама 360° на підсвічені мости річки Хан."},"tip":{"en":"Go around 18:00–19:00 for sunset without a cover; dress code applies (no flip-flops or shorts for men).","uk":"Приходьте о 18:00–19:00 на захід сонця без плати за вхід; діє дрес-код (чоловікам без шльопанців і шортів)."},"hours":"18:00–02:00","website":"https://danangfantasticity.com/sky-bar-36","images":["https://danangfantasticity.com/wp-content/uploads/2015/10/sky36-da-nang-04-1.jpg","https://goodmorning-hoian.com/wp-content/uploads/sky-36-rooftop-bar-da-nang.jpg","https://goodmorning-hoian.com/wp-content/uploads/sky36-bar-de-nuit-danang.jpg"]},{"id":"east-west-brewing","region":"central","area":"Da Nang","category":"bars","name":"East West Brewing Co.","nameVi":"East West Brewing","lat":16.06759,"lng":108.24606,"address":"1A Vo Nguyen Giap, Phuoc My, Son Tra (My Khe Beach), Da Nang","rating":4.4,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"","desc":{"en":"A big beachfront craft brewery on My Khe with a rooftop terrace, a dozen house beers on tap and good burgers and pizzas.","uk":"Велика пивоварня просто на пляжі Мі Кхе з терасою на даху, десятком власних сортів пива на крані та непоганими бургерами й піцою."},"tip":{"en":"Order a tasting flight on the rooftop at sunset; happy-hour deals usually run in the late afternoon.","uk":"Замовте дегустаційний сет на даху під час заходу сонця; щасливі години зазвичай пізно вдень."},"hours":"11:00–24:00","website":"https://www.eastwestbrewing.vn","images":["https://cdn2.tuoitre.vn/zoom/1200_630/ttnew/r/2023/04/20/5-1681975418.jpg"]},{"id":"banh-mi-phuong","region":"central","area":"Hoi An","category":"streetfood","name":"Banh Mi Phuong","nameVi":"Bánh Mì Phượng","lat":15.87848,"lng":108.33201,"address":"2B Phan Chau Trinh, Hoi An","rating":4.5,"googleRating":null,"price":1,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Anthony Bourdain: 'a symphony in a sandwich'","desc":{"en":"The world's most famous bánh mì: a crackly baguette stuffed with pâté, roast pork, char siu, herbs, pickles and Mrs Phuong's secret sauce.","uk":"Найвідоміший бань мі у світі: хрусткий багет із паштетом, запеченою свининою, ча сіу, зеленню, маринадами й секретним соусом пані Фионг."},"tip":{"en":"Order the 'thập cẩm' (mixed/special); the queue moves fast — or take a seat inside to eat at the tables.","uk":"Замовляйте «тхап кам» (мікс/спеціальний); черга рухається швидко — або сядьте всередині за столик."},"hours":"06:30–21:30","website":"https://en.wikipedia.org/wiki/B%C3%A1nh_m%C3%AC","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/f/fb/B%C3%A1nh_M%C3%AC_Ph%C6%B0%E1%BB%A3ng_%282024%29_-_img_01.jpg/960px-B%C3%A1nh_M%C3%AC_Ph%C6%B0%E1%BB%A3ng_%282024%29_-_img_01.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/d/d2/Banh_My_Phuong_Hoi_An_quay_banh.jpg/960px-Banh_My_Phuong_Hoi_An_quay_banh.jpg","https://goodmorning-hoian.com/wp-content/uploads/2015/06/banh-mi-phuong-hoi-an-.jpg"]},{"id":"madam-khanh-banh-mi-queen","region":"central","area":"Hoi An","category":"streetfood","name":"Madam Khanh – The Banh Mi Queen","nameVi":"Bánh Mì Madam Khánh","lat":15.88063,"lng":108.32791,"address":"115 Tran Cao Van, Hoi An","rating":4.6,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"'Banh Mi Queen' — beloved by travel bloggers and YouTubers","desc":{"en":"Madam Khanh has been assembling bánh mì at this counter for decades; many locals rate her house sauce and grilled pork above the famous rival.","uk":"Мадам Кхань десятиліттями збирає бань мі за цим прилавком; багато місцевих ставлять її фірмовий соус і смажену свинину вище, ніж у знаменитого конкурента."},"tip":{"en":"Ask for the 'special' with everything; it's just outside the old town, so queues are shorter than at Phuong.","uk":"Просіть «спешл» з усім; заклад трохи за межами старого міста, тож черги коротші, ніж у Фионг."},"hours":"07:00–19:00","website":"","images":["https://goodmorning-hoian.com/wp-content/uploads/banh-mi-queen-hoi-an.jpg"]},{"id":"com-ga-ba-buoi","region":"central","area":"Hoi An","category":"streetfood","name":"Com Ga Ba Buoi","nameVi":"Cơm Gà Bà Buội","lat":15.87849,"lng":108.33043,"address":"22 Phan Chau Trinh, Hoi An","rating":4.2,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Hoi An's most famous chicken rice","desc":{"en":"Hoi An's legendary cơm gà: turmeric-tinted rice cooked in chicken broth, topped with shredded free-range chicken, papaya pickle and Vietnamese mint.","uk":"Легендарний хойанський ком га: рис із куркумою, зварений на курячому бульйоні, з шматочками домашньої курки, маринованою папаєю та в'єтнамською м'ятою."},"tip":{"en":"Order 'cơm gà xé' (shredded) plus a side of the giblet soup; go at lunch, they can sell out by evening.","uk":"Замовте «ком га се» (з шматочками) і суп з потрухів; приходьте в обід — до вечора може все закінчитися."},"hours":"10:30–20:00","website":"","images":["https://goodmorning-hoian.com/wp-content/uploads/com-ga-hoi-an-riz-poulet.jpg"]},{"id":"morning-glory-hoi-an","region":"central","area":"Hoi An","category":"restaurants","name":"Morning Glory Original","nameVi":"Nhà hàng Morning Glory","lat":15.87662,"lng":108.32766,"address":"106 Nguyen Thai Hoc, Hoi An","rating":4.3,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Ms Vy's original restaurant — a Hoi An dining pioneer","desc":{"en":"Trailblazing chef Trinh Diem Vy's elegant shophouse elevates Hoi An street food — cao lầu, white rose dumplings, morning glory stir-fry.","uk":"Елегантний ресторан у старовинному будинку піонерки шефа Чінь Зьєм Ві підносить вуличну їжу Хойана — као лау, пельмені «біла троянда», смажений іпомея."},"tip":{"en":"Reserve for dinner or join Ms Vy's cooking class; try the local trio: cao lầu, white rose and hoành thánh chiên.","uk":"Бронюйте на вечерю або запишіться на кулінарний клас пані Ві; спробуйте місцеве тріо: као лау, «білу троянду» й смажені вонтони."},"hours":"10:00–22:00","website":"https://msvy-tastevietnam.com","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/6/62/Morning_Glory_Street_Food_Restaurant_and_Cooking_School%2C_Hoi_An%2C_Vietnam_%286944520984%29.jpg/960px-Morning_Glory_Street_Food_Restaurant_and_Cooking_School%2C_Hoi_An%2C_Vietnam_%286944520984%29.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/Morning_Glory_Street_Food_Restaurant_and_Cooking_School%2C_Hoi_An%2C_Vietnam_%287090587149%29.jpg/960px-Morning_Glory_Street_Food_Restaurant_and_Cooking_School%2C_Hoi_An%2C_Vietnam_%287090587149%29.jpg"]},{"id":"mango-mango-hoi-an","region":"central","area":"Hoi An","category":"restaurants","name":"Mango Mango","nameVi":"Nhà hàng Mango Mango","lat":15.87601,"lng":108.32582,"address":"45 Nguyen Phuc Chu, An Hoi, Hoi An","rating":4.1,"googleRating":null,"price":3,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Celebrity chef Duc Tran's riverside fusion","desc":{"en":"Colourful riverside restaurant by Viet-Kieu chef Duc Tran serving bold Vietnamese-Latin fusion and inventive cocktails facing the lantern-lit old town.","uk":"Яскравий ресторан на березі річки від шефа-в'єткьєу Дика Чана: смілива в'єтнамсько-латиноамериканська кухня й авторські коктейлі з видом на старе місто в ліхтарях."},"tip":{"en":"Book a balcony table upstairs for the best river view at dusk; cocktails are the highlight.","uk":"Бронюйте столик на балконі нагорі — найкращий вид на річку в сутінках; коктейлі тут — головна родзинка."},"hours":"10:00–22:30","website":"https://mangomangohoian.com","images":["https://static.wixstatic.com/media/f0d1fa_d2e9829416fa4d33acfb2bc9717400e4~mv2.jpg/v1/fit/w_2500,h_1330,al_c/f0d1fa_d2e9829416fa4d33acfb2bc9717400e4~mv2.jpg"]},{"id":"reaching-out-tea-house","region":"central","area":"Hoi An","category":"cafes","name":"Reaching Out Tea House","nameVi":"Reaching Out Tea House","lat":15.87704,"lng":108.32724,"address":"131 Tran Phu, Hoi An","rating":4.8,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Social enterprise run by speech- and hearing-impaired staff","desc":{"en":"A hushed, candlelit tea house in an old shophouse where staff with hearing impairments serve tasting sets of Vietnamese teas and coffee — you order with word blocks.","uk":"Тихий чайний будиночок у старовинній крамниці при свічках, де персонал із вадами слуху подає дегустаційні сети в'єтнамського чаю й кави — замовлення робите дерев'яними блоками зі словами."},"tip":{"en":"Order the tea tasting set and stay quiet to respect the silent concept; the attached crafts shop sells fair-trade souvenirs.","uk":"Замовте дегустаційний сет чаю й дотримуйтеся тиші — це концепція закладу; у крамниці поруч продають сувеніри справедливої торгівлі."},"hours":"08:30–21:00 (Sat–Sun from 10:00)","website":"https://reachingoutvietnam.com/teahouse/the-teahouse/","images":["https://reachingoutvietnam.com/wp-content/uploads/2017/12/ro_web_slices_20160301_image_teahouse1a.jpg","https://reachingoutvietnam.com/wp-content/uploads/2017/12/ro_web_slices_20160301_image_teahouse2a.jpg","https://reachingoutvietnam.com/wp-content/uploads/2016/01/ro_web_slices_20160301_cover_teahouse-information-edit.jpg"]},{"id":"faifo-coffee","region":"central","area":"Hoi An","category":"cafes","name":"Faifo Coffee (rooftop)","nameVi":"Faifo Coffee","lat":15.87723,"lng":108.32813,"address":"130 Tran Phu, Hoi An","rating":4.2,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Instagram-famous rooftop over Hoi An's tiled roofs","desc":{"en":"A narrow café with a tiny third-floor rooftop that delivers Hoi An's most-photographed view: mossy yin-yang tiled roofs and lanterns stretching to the river.","uk":"Вузька кав'ярня з крихітним дахом на третьому поверсі, звідки відкривається найфотографованіший вид Хойана: замшілі черепичні дахи інь-ян і ліхтарі аж до річки."},"tip":{"en":"Come at 07:00 opening or at sunset; you must order a drink (coconut coffee is good) to access the roof, and it's tight — expect to wait.","uk":"Приходьте до відкриття о 07:00 або на захід сонця; щоб піднятися на дах, потрібно замовити напій (кокосова кава непогана), місця мало — можливе очікування."},"hours":"07:00–21:30","website":"","images":["https://goodmorning-hoian.com/wp-content/uploads/2019/01/cafe-faifo-rooftop-hoi-an.jpg","https://goodmorning-hoian.com/wp-content/uploads/faifoo-coffee-hoi-an.jpg"]},{"id":"hoi-an-roastery","region":"central","area":"Hoi An","category":"cafes","name":"Hoi An Roastery","nameVi":"Hoi An Roastery","lat":15.87703,"lng":108.32711,"address":"135 Tran Phu, Hoi An (several branches in the old town)","rating":4.4,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"","desc":{"en":"Hoi An's homegrown specialty roaster in restored yellow shophouses, pouring Vietnamese robusta and arabica as phin drip, egg coffee or espresso.","uk":"Місцева спешелті-обсмажувальня у відреставрованих жовтих будиночках: в'єтнамська робуста й арабіка у фіні, яєчна кава чи еспресо."},"tip":{"en":"Try the Vietnamese 'egg coffee' or 'salted coffee' here if you won't make it to Hanoi or Hue; air-conditioned refuge from midday heat.","uk":"Спробуйте тут яєчну чи солону каву, якщо не потрапите в Ханой чи Хюе; кондиціонований прихисток від полуденної спеки."},"hours":"07:00–22:00","website":"https://www.hoianroastery.com","images":["https://hoianroastery.com/_astro/hero-shopfront.aKMHAZOT_1hr392.jpg","https://goodmorning-hoian.com/wp-content/uploads/hoi-an-roastery.jpg"]},{"id":"tadioto-hoi-an","region":"central","area":"Hoi An","category":"bars","name":"Tadioto","nameVi":"Tadioto Hội An","lat":15.87708,"lng":108.33442,"address":"54 Phan Boi Chau, Hoi An (down a laneway)","rating":4.3,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Lonely Planet pick; founded by writer-artist Nguyen Qui Duc","desc":{"en":"A bohemian gallery-bar tucked down a laneway: craft gin and whisky list, a Japanese ramen and sushi counter and a zen rock garden.","uk":"Богемний бар-галерея, захований у провулку: добірка крафтового джину й віскі, японська стійка з раменом і суші та дзен-сад каменів."},"tip":{"en":"Ask for a cocktail with Song Cai Vietnamese gin; quieter than the riverside bars, ideal for a nightcap.","uk":"Попросіть коктейль із в'єтнамським джином Song Cai; тут тихіше, ніж у барах на набережній, — ідеально для келиха на ніч."},"hours":"09:00–23:00","website":"","images":["https://itin-dev.wanderlogstatic.com/freeImageSmall/W07ZrpXvzbXjHimIPKqGbnvs2DMa1pAI"]},{"id":"bun-bo-hue-o-cuong-chu-diep","region":"central","area":"Hue","category":"streetfood","name":"Bun Bo Hue O Cuong Chu Diep","nameVi":"Bún Bò Huế O Cương Chú Điệp","lat":16.45754,"lng":107.58267,"address":"6 Tran Thuc Nhan, Vinh Ninh, Hue","rating":4.4,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Bourdain: bun bo Hue is 'the greatest soup in the world'","desc":{"en":"A beloved local spot for Hue's fiery lemongrass beef noodle soup, simmered for hours with beef shank, crab cake and pork knuckle, served with banana blossom and herbs.","uk":"Улюблене місцевими місце для пекучого супу з яловичиною та лемонграсом із Хюе, що вариться годинами з яловичою гомілкою, крабовою котлетою та свинячою рулькою, подається з бананово-квітковим салатом і зеленню."},"tip":{"en":"In Hue bun bo is a breakfast dish — go 06:30–09:00; ask 'không huyết' to skip the blood cubes if you prefer.","uk":"У Хюе бун бо їдять на сніданок — ідіть о 06:30–09:00; скажіть «хонг хует», якщо не хочете кубиків із крові."},"hours":"06:00–11:00, 15:00–21:00 (approx.)","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/B%C3%BAn_b%C3%B2_Hu%E1%BA%BF_minh28397.jpg/960px-B%C3%BAn_b%C3%B2_Hu%E1%BA%BF_minh28397.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Bun_Bo_Hue_1.jpg/960px-Bun_Bo_Hue_1.jpg"]},{"id":"cafe-muoi-hue-salt-coffee","region":"central","area":"Hue","category":"cafes","name":"Cafe Muoi – Birthplace of Salt Coffee","nameVi":"Cà Phê Muối (10 Nguyễn Lương Bằng)","lat":16.46275,"lng":107.59889,"address":"10 Nguyen Luong Bang, Hue (2nd branch: 142 Dang Thai Than, Citadel)","rating":4.4,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"CNN: the shop that invented salt coffee; viral trend worldwide","desc":{"en":"The humble shop credited with inventing cà phê muối (around 2010): dark phin coffee topped with a lightly salted cream foam — sweet, savoury and addictive.","uk":"Скромна кав'ярня, яку вважають винахідницею ка фе муой (близько 2010 р.): темна кава з фіна під злегка солоною вершковою піною — солодко, солоно й затягує."},"tip":{"en":"Stir only gently so you get coffee and salty foam in each sip; it closes in the early afternoon (≈11:15–14:00).","uk":"Розмішуйте обережно, щоб у кожному ковтку були і кава, і солона піна; удень є перерва (≈11:15–14:00)."},"hours":"06:30–11:15, 14:00–22:00","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/0/0d/Ly_c%C3%A0_ph%C3%AA_mu%E1%BB%91i_%E1%BB%9F_T%C3%A2n_Ph%C3%BA_ng14th5n2023_%281%29.jpg/960px-Ly_c%C3%A0_ph%C3%AA_mu%E1%BB%91i_%E1%BB%9F_T%C3%A2n_Ph%C3%BA_ng14th5n2023_%281%29.jpg"]},{"id":"hoan-kiem-lake-ngoc-son-temple","region":"hanoi","area":"Hoan Kiem","category":"sights","name":"Hoan Kiem Lake & Ngoc Son Temple","nameVi":"Hồ Hoàn Kiếm & Đền Ngọc Sơn","lat":21.02883,"lng":105.85254,"address":"Dinh Tien Hoang St, Hoan Kiem (temple via red The Huc Bridge)","rating":4.7,"googleRating":null,"price":1,"mustSee":true,"hiddenGem":false,"viral":false,"hype":"Legend of the Restored Sword; Hanoi's symbolic heart","desc":{"en":"The emerald 'Lake of the Returned Sword' is Hanoi's beating heart, with the little Turtle Tower on its islet and the scarlet The Huc Bridge leading to 18th-century Ngoc Son Temple.","uk":"Смарагдове «Озеро поверненого меча» — серце Ханоя: на острівці стоїть Черепахова вежа, а червоний міст Тхе Хук веде до храму Нгок Шон XVIII століття."},"tip":{"en":"Come Friday–Sunday evening when the streets around the lake become a car-free walking zone, or at 6 am to watch locals do tai chi.","uk":"Приходьте у п’ятницю–неділю ввечері, коли вулиці довкола озера стають пішохідними, або о 6-й ранку — подивитися, як місцеві займаються тайчі."},"hours":"Lake 24h; temple ~07:00–18:00","website":"https://en.wikipedia.org/wiki/Ho%C3%A0n_Ki%E1%BA%BFm_Lake","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Thap_Rua.jpg/960px-Thap_Rua.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Ngoc_Son_Temple%2C_Hanoi_%2815%29_%2837780892234%29.jpg/960px-Ngoc_Son_Temple%2C_Hanoi_%2815%29_%2837780892234%29.jpg"]},{"id":"temple-of-literature","region":"hanoi","area":"Dong Da","category":"temples","name":"Temple of Literature","nameVi":"Văn Miếu – Quốc Tử Giám","lat":21.02861,"lng":105.83556,"address":"58 Quoc Tu Giam St, Van Mieu – Quoc Tu Giam Ward","rating":4.7,"googleRating":null,"price":1,"mustSee":true,"hiddenGem":false,"viral":false,"hype":"Vietnam's first university (1076); on the 100,000-dong note","desc":{"en":"Founded in 1070 to honour Confucius, this serene sequence of courtyards, gates and ponds housed Vietnam's first national university; stone turtles carry steles naming centuries of doctoral laureates.","uk":"Заснований 1070 року на честь Конфуція, цей спокійний ансамбль дворів, брам і ставків був першим національним університетом В’єтнаму; кам’яні черепахи тримають стели з іменами докторів наук минулих століть."},"tip":{"en":"Arrive at 8 am opening to beat tour groups; in exam season students come to touch the turtles' heads for luck (now fenced off — don't).","uk":"Приходьте до відкриття о 8:00, поки немає груп; у сесію студенти приходять сюди по удачу — черепах зараз огороджено, не торкайтеся їх."},"hours":"08:00–17:00 (seasonal night tours)","website":"https://en.wikipedia.org/wiki/Temple_of_Literature,_Hanoi","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/Hanoi_Temple_of_Literature_%28cropped%29.jpg/960px-Hanoi_Temple_of_Literature_%28cropped%29.jpg"]},{"id":"ho-chi-minh-mausoleum","region":"hanoi","area":"Ba Dinh","category":"sights","name":"Ho Chi Minh Mausoleum & Ba Dinh Square","nameVi":"Lăng Chủ tịch Hồ Chí Minh","lat":21.03678,"lng":105.83469,"address":"1 Hung Vuong St, Ba Dinh Square","rating":4.5,"googleRating":null,"price":0,"mustSee":true,"hiddenGem":false,"viral":false,"hype":"Embalmed body of 'Uncle Ho' since 1975","desc":{"en":"A monumental granite mausoleum on vast Ba Dinh Square, where Ho Chi Minh read the 1945 declaration of independence; inside, his embalmed body lies under a silent honour guard.","uk":"Монументальний гранітний мавзолей на величезній площі Бадінь, де Хо Ши Мін 1945 року проголосив незалежність; усередині під мовчазною почесною вартою лежить його забальзамоване тіло."},"tip":{"en":"Open mornings only (Tue–Thu, Sat–Sun), closed for maintenance roughly mid-June to mid-August; wear covered shoulders/knees, no bags or cameras inside. The flag-lowering ceremony at ~21:00 is free.","uk":"Відкрито лише вранці (вт–чт, сб–нд), приблизно з середини червня до середини серпня — на обслуговуванні; закриті плечі й коліна, без сумок і камер. Спуск прапора близько 21:00 — безкоштовно."},"hours":"Tue–Thu, Sat–Sun 07:30–10:30 (07:00–10:30 summer)","website":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Mausoleum","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/f/fd/L%C4%83ng_B%C3%A1c_-_NKS.jpg/960px-L%C4%83ng_B%C3%A1c_-_NKS.jpg"]},{"id":"one-pillar-pagoda","region":"hanoi","area":"Ba Dinh","category":"temples","name":"One Pillar Pagoda","nameVi":"Chùa Một Cột","lat":21.03586,"lng":105.83361,"address":"Ong Ich Khiem St, behind the Ho Chi Minh Mausoleum","rating":4.1,"googleRating":null,"price":0,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Iconic lotus-shaped pagoda from 1049","desc":{"en":"A tiny wooden shrine perched on a single stone pillar in a lotus pond, designed to resemble a lotus rising from the water — one of Vietnam's most iconic temples.","uk":"Крихітне дерев’яне святилище на одній кам’яній колоні посеред ставка, що нагадує лотос, який підіймається з води, — один із найвідоміших храмів В’єтнаму."},"tip":{"en":"It's small — combine it with the mausoleum and Presidential Palace grounds in one morning.","uk":"Пагода маленька — поєднайте її з мавзолеєм і територією Президентського палацу за один ранок."},"hours":"07:00–18:00","website":"https://en.wikipedia.org/wiki/One_Pillar_Pagoda","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Hanoi%2C_Vietnam_%2812041825854%29.jpg/960px-Hanoi%2C_Vietnam_%2812041825854%29.jpg"]},{"id":"tran-quoc-pagoda","region":"hanoi","area":"Tay Ho","category":"temples","name":"Tran Quoc Pagoda","nameVi":"Chùa Trấn Quốc","lat":21.04788,"lng":105.83684,"address":"Thanh Nien Rd, West Lake","rating":4.5,"googleRating":null,"price":0,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Hanoi's oldest pagoda; Instagram sunset spot on West Lake","desc":{"en":"Hanoi's oldest Buddhist pagoda (6th century) sits on a tiny island in West Lake, its 11-tier red stupa glowing against the water at sunset.","uk":"Найстаріша буддійська пагода Ханоя (VI ст.) стоїть на острівці на Західному озері; її 11-ярусна червона ступа палає на тлі води під час заходу сонця."},"tip":{"en":"Go late afternoon, then walk the Thanh Nien causeway for sunset and a West Lake shrimp cake (bánh tôm).","uk":"Ідіть надвечір, а потім прогуляйтеся дамбою Тхань Ньєн на захід сонця й скуштуйте креветкові оладки (bánh tôm)."},"hours":"~07:30–18:00","website":"https://en.wikipedia.org/wiki/Tr%E1%BA%A5n_Qu%E1%BB%91c_Pagoda","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Tran_Quoc_Pagoda%2C_Hanoi%2C_Vietnam.jpg/960px-Tran_Quoc_Pagoda%2C_Hanoi%2C_Vietnam.jpg"]},{"id":"hanoi-old-quarter","region":"hanoi","area":"Hoan Kiem","category":"sights","name":"Old Quarter (36 Streets)","nameVi":"Phố cổ Hà Nội (36 phố phường)","lat":21.03419,"lng":105.8513,"address":"Area north of Hoan Kiem Lake (Hang Dao, Hang Bac, Ma May…)","rating":4.6,"googleRating":null,"price":0,"mustSee":true,"hiddenGem":false,"viral":false,"hype":"1,000-year-old guild streets; backpacker hub","desc":{"en":"A dense maze of narrow 'tube houses' where each street once belonged to a single guild — silk, silver, paper votives — now buzzing with scooters, street kitchens and tiny cafés.","uk":"Щільний лабіринт вузьких «будинків-труб», де кожна вулиця колись належала одному цеху — шовк, срібло, паперові підношення; тепер тут гудуть скутери, вуличні кухні та крихітні кав’ярні."},"tip":{"en":"Visit restored tube house 87 Ma May and Bach Ma Temple; cross roads slowly and steadily — scooters flow around you.","uk":"Загляньте до відреставрованого будинку на Ма Май, 87 і храму Бать Ма; переходьте дорогу повільно й рівно — скутери об’їдуть вас."},"hours":"24h","website":"https://en.wikipedia.org/wiki/Old_Quarter,_Hanoi","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/d/da/Old_Quarter_Street_Scene_-_Hanoi_-_Vietnam_%2848256301206%29.jpg/960px-Old_Quarter_Street_Scene_-_Hanoi_-_Vietnam_%2848256301206%29.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/f/f6/2024-11-03_Hanoi%27s_Old_Quarter_7.jpg/960px-2024-11-03_Hanoi%27s_Old_Quarter_7.jpg"]},{"id":"hanoi-train-street","region":"hanoi","area":"Hoan Kiem","category":"experiences","name":"Hanoi Train Street","nameVi":"Phố cà phê đường tàu","lat":21.03015,"lng":105.84407,"address":"Railway between Tran Phu & Phung Hung St (Le Duan crossing)","rating":4.3,"googleRating":null,"price":1,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Viral TikTok/Instagram spot — trains pass inches from café tables","desc":{"en":"Rows of tiny cafés line a working railway through tight residential lanes; when a train thunders through, everyone pulls back their stools as carriages pass inches away.","uk":"Крихітні кав’ярні вишикувалися вздовж діючої залізниці у вузьких житлових провулках; коли проїжджає потяг, усі відсувають стільчики, а вагони минають за кілька сантиметрів."},"tip":{"en":"Status 2025–26: police cleared the cafés on 27 Nov 2025 but they reopened within days; in Feb 2026 authorities cut passenger train frequency and suspended freight here (a full halt is proposed). As of Aug 2026 it was still bustling — check train times at your café and expect occasional police sweeps.","uk":"Статус 2025–26: 27 листопада 2025 поліція закрила кав’ярні, але за кілька днів вони знову відкрилися; у лютому 2026 скоротили кількість пасажирських потягів і припинили вантажні (обговорюють повне припинення руху). Станом на серпень 2026 тут було людно — уточнюйте розклад у кав’ярні й будьте готові до рейдів поліції."},"hours":"Cafés ~08:00–22:00; train times vary","website":"https://en.wikipedia.org/wiki/Hanoi_Train_Street","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/e/e8/Hanoi_Train_Street_%2820231225b%29_%2853489076293%29.jpg/960px-Hanoi_Train_Street_%2820231225b%29_%2853489076293%29.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/DSVN_Class_D12_1200hp_Bo-Bo_E-622_diesel_electric_on_Train_Street%2C_Hanoi.jpg/960px-DSVN_Class_D12_1200hp_Bo-Bo_E-622_diesel_electric_on_Train_Street%2C_Hanoi.jpg"]},{"id":"long-bien-bridge","region":"hanoi","area":"Hoan Kiem / Long Bien","category":"sights","name":"Long Bien Bridge","nameVi":"Cầu Long Biên","lat":21.04314,"lng":105.85817,"address":"Over the Red River, from Phuc Xa / Dong Xuan to Long Bien","rating":4.4,"googleRating":null,"price":0,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"French-built 1903 bridge that survived US bombing","desc":{"en":"A rusty 1.7 km cantilever bridge designed in the 1890s and battered in the American War; scooters, trains and pedestrians share its narrow lanes high above the Red River and its banana-field islands.","uk":"Іржавий 1,7-кілометровий консольний міст 1890-х років, сильно побитий під час війни зі США; скутери, потяги й пішоходи ділять його вузькі смуги високо над Червоною річкою з банановими острівцями."},"tip":{"en":"Walk out at sunrise or sunset on the pedestrian edge; the early-morning wholesale market under the bridge is a photographer's dream.","uk":"Пройдіться пішохідним краєм на світанку чи заході; ранковий гуртовий ринок під мостом — мрія фотографа."},"hours":"24h","website":"https://en.wikipedia.org/wiki/Long_Bi%C3%AAn_Bridge","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/9/92/Long_Bi%C3%AAn_Bridge_-_panoramio.jpg/960px-Long_Bi%C3%AAn_Bridge_-_panoramio.jpg"]},{"id":"hoa-lo-prison","region":"hanoi","area":"Hoan Kiem","category":"museums","name":"Hoa Lo Prison ('Hanoi Hilton')","nameVi":"Di tích Nhà tù Hỏa Lò","lat":21.0257,"lng":105.8461,"address":"1 Hoa Lo St, Hoan Kiem","rating":4.5,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"'Hanoi Hilton' where John McCain was held","desc":{"en":"A French colonial prison where Vietnamese revolutionaries were jailed and later US pilots like John McCain; the guillotine and shackled cells make for a sobering visit.","uk":"Французька колоніальна в’язниця, де тримали в’єтнамських революціонерів, а згодом американських пілотів, зокрема Джона Маккейна; гільйотина та камери з кайданами справляють гнітюче враження."},"tip":{"en":"Rent the audio guide; the evening 'Sacred Night' tour (selected nights) is atmospheric and needs booking.","uk":"Візьміть аудіогід; вечірній тур «Священна ніч» (у певні дні) дуже атмосферний, але потребує бронювання."},"hours":"08:00–17:00","website":"https://en.wikipedia.org/wiki/H%E1%BB%8Fa_L%C3%B2_Prison","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/HanoiHilton.jpg/960px-HanoiHilton.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/Hoa_Lo_Prison_Maison_Centrale_Museum_%2839543736421%29.jpg/960px-Hoa_Lo_Prison_Maison_Centrale_Museum_%2839543736421%29.jpg"]},{"id":"vietnam-museum-of-ethnology","region":"hanoi","area":"Cau Giay","category":"museums","name":"Vietnam Museum of Ethnology","nameVi":"Bảo tàng Dân tộc học Việt Nam","lat":21.04008,"lng":105.79884,"address":"Nguyen Van Huyen St, Cau Giay","rating":4.6,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Often rated Hanoi's best museum","desc":{"en":"A superb museum of Vietnam's 54 ethnic groups, whose garden holds full-size stilt houses, a soaring Bahnar communal house and Cham tombs you can walk into.","uk":"Чудовий музей 54 етнічних груп В’єтнаму: у його саду стоять справжні будинки на палях, величний общинний дім банарів і гробниці тямів, до яких можна зайти."},"tip":{"en":"It's 8 km west of the centre — take a Grab and allow 2–3 hours; catch a water-puppet show in the garden on weekends.","uk":"Музей за 8 км на захід від центру — їдьте на Grab і закладіть 2–3 години; у вихідні в саду бувають вистави водяних ляльок."},"hours":"Tue–Sun 08:30–17:30","website":"https://www.vme.org.vn/","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/Dan_toc_hoc_1.jpg/960px-Dan_toc_hoc_1.jpg"]},{"id":"st-josephs-cathedral","region":"hanoi","area":"Hoan Kiem","category":"sights","name":"St. Joseph's Cathedral","nameVi":"Nhà thờ Lớn Hà Nội","lat":21.02865,"lng":105.84886,"address":"40 Nha Chung St, Hoan Kiem","rating":4.4,"googleRating":null,"price":0,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Neo-Gothic 1886 cathedral; trendy lemon-tea hangout","desc":{"en":"A soot-darkened neo-Gothic cathedral from 1886 modelled on Notre-Dame; the square in front is Hanoi's favourite spot for sipping lemon tea on plastic stools.","uk":"Потемнілий від часу неоготичний собор 1886 року, створений за зразком Нотр-Даму; площа перед ним — улюблене місце ханойців для лимонного чаю на пластикових стільчиках."},"tip":{"en":"The main doors open only for Mass (e.g. ~17:30 weekdays); enter via the side gate otherwise. Grab a trà chanh on Nha Tho street afterwards.","uk":"Головні двері відчиняють лише на месу (у будні близько 17:30); в інший час заходьте через бічну браму. Потім візьміть trà chanh на вулиці Нья Тхо."},"hours":"~08:00–11:00, 14:00–19:00; Mass times vary","website":"https://en.wikipedia.org/wiki/St._Joseph%27s_Cathedral,_Hanoi","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/St._Joseph%27s_Cathedral_-_Hanoi%2C_Vietnam.jpg/960px-St._Joseph%27s_Cathedral_-_Hanoi%2C_Vietnam.jpg"]},{"id":"hanoi-opera-house","region":"hanoi","area":"Hoan Kiem","category":"sights","name":"Hanoi Opera House","nameVi":"Nhà hát Lớn Hà Nội","lat":21.0242,"lng":105.85783,"address":"1 Trang Tien St, August Revolution Square","rating":4.5,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"1911 French colonial landmark modelled on Palais Garnier","desc":{"en":"A grand 1911 opera house in French Neoclassical style, glowing golden at night at the end of elegant Trang Tien street.","uk":"Розкішний оперний театр 1911 року у французькому неокласичному стилі, що вночі сяє золотом наприкінці елегантної вулиці Чанг Тьєн."},"tip":{"en":"The interior is only open on guided tours or for performances — book the Lune Production bamboo-circus show or a symphony night.","uk":"Усередину можна потрапити лише з екскурсією чи на виставу — забронюйте бамбуковий цирк від Lune Production або симфонічний вечір."},"hours":"Box office ~08:00–17:00; shows evenings","website":"https://hanoioperahouse.org.vn/","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Hanoi_Opera_House%2C_24_December_2016.jpg/960px-Hanoi_Opera_House%2C_24_December_2016.jpg"]},{"id":"ta-hien-beer-street","region":"hanoi","area":"Hoan Kiem","category":"experiences","name":"Ta Hien Beer Street","nameVi":"Phố bia Tạ Hiện","lat":21.0348,"lng":105.85203,"address":"Ta Hien & Luong Ngoc Quyen St, Old Quarter","rating":4.2,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Backpacker 'beer street'; viral nightlife spot","desc":{"en":"Every night this short Old Quarter lane overflows with plastic stools, cheap draught bia hơi, grilled skewers and a noisy global crowd.","uk":"Щовечора цей короткий провулок Старого кварталу переповнений пластиковими стільчиками, дешевим розливним bia hơi, шашличками на грилі та галасливим інтернаціональним натовпом."},"tip":{"en":"Agree on prices before ordering and watch your phone; for a more local bia hơi, try the corners of nearby Hang Buom or Bat Dan.","uk":"Узгоджуйте ціну до замовлення й пильнуйте телефон; більш автентичний bia hơi — на сусідніх Ханг Буом чи Бат Дан."},"hours":"~17:00–00:00 (later on weekends)","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Ph%E1%BB%91_T%E1%BA%A1_Hi%E1%BB%87n_-_NKS.jpg/960px-Ph%E1%BB%91_T%E1%BA%A1_Hi%E1%BB%87n_-_NKS.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Ta-hien-street-3559133.jpg/960px-Ta-hien-street-3559133.jpg"]},{"id":"thang-long-water-puppet-theatre","region":"hanoi","area":"Hoan Kiem","category":"experiences","name":"Thang Long Water Puppet Theatre","nameVi":"Nhà hát Múa rối nước Thăng Long","lat":21.0317,"lng":105.85345,"address":"57B Dinh Tien Hoang St, Hoan Kiem","rating":4.2,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"1,000-year-old Red River Delta art form","desc":{"en":"Lacquered wooden puppets dance, fish and fight dragons across a pool of water to live traditional music — a quirky art born in Red River Delta rice paddies.","uk":"Лаковані дерев’яні ляльки танцюють, ловлять рибу й б’ються з драконами на поверхні води під живу традиційну музику — дивовижне мистецтво з рисових полів дельти Червоної річки."},"tip":{"en":"Shows last ~50 min and sell out in high season — buy tickets a day ahead; front rows can get splashed.","uk":"Вистава триває близько 50 хв і в сезон розпродується — купіть квитки за день; у перших рядах можуть забризкати."},"hours":"Several shows daily ~15:00–20:30","website":"https://thanglongwaterpuppet.org/","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Thang_Long_Water_Puppet_Theatre2.JPG/960px-Thang_Long_Water_Puppet_Theatre2.JPG"]},{"id":"dong-xuan-market","region":"hanoi","area":"Hoan Kiem","category":"markets","name":"Dong Xuan Market & Night Market","nameVi":"Chợ Đồng Xuân","lat":21.03826,"lng":105.84967,"address":"Dong Xuan St, north end of Old Quarter","rating":4.0,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Hanoi's largest covered market (1889)","desc":{"en":"Hanoi's biggest wholesale market, a three-storey warren of fabrics, dried goods and kitchenware, with a food alley out back and a weekend night market stretching to the lake.","uk":"Найбільший гуртовий ринок Ханоя — триповерховий лабіринт тканин, сухофруктів і посуду, з фуд-провулком позаду та нічним ринком у вихідні, що тягнеться аж до озера."},"tip":{"en":"Head to the food stalls behind the market for bún riêu and nem; the night market runs Fri–Sun from ~19:00.","uk":"Ідіть до фуд-кіосків позаду ринку по bún riêu і nem; нічний ринок працює пт–нд приблизно з 19:00."},"hours":"06:00–18:00; night market Fri–Sun 19:00–23:00","website":"https://en.wikipedia.org/wiki/%C4%90%E1%BB%93ng_Xu%C3%A2n_Market","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/3/3b/Dong_Xuan_market.jpg/960px-Dong_Xuan_market.jpg"]},{"id":"ha-long-bay","region":"hanoi","area":"Ha Long","category":"nature","name":"Ha Long Bay","nameVi":"Vịnh Hạ Long","lat":20.84361,"lng":107.09129,"address":"Quang Ninh; cruises depart Tuan Chau / Ha Long International Cruise Port (~2.5 h from Hanoi)","rating":4.7,"googleRating":null,"price":3,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"UNESCO World Heritage; Top Gear & countless cruise reels","desc":{"en":"Nearly 2,000 jungle-topped limestone islets rise from jade water — cruise past floating villages, kayak into hidden lagoons and explore vast caves like Sung Sot.","uk":"Майже 2000 вапнякових острівців, укритих джунглями, здіймаються з нефритової води — пливіть повз плавучі села, на каяку пропливайте в приховані лагуни та досліджуйте гігантські печери на кшталт Сунг Шот."},"tip":{"en":"Choose an overnight cruise (2D1N) for sunrise without the day-tripper crowds; routes via Bai Tu Long are quieter than the main loop.","uk":"Обирайте круїз із ночівлею (2 дні/1 ніч), щоб зустріти світанок без натовпів; маршрути через Бай Ту Лонг спокійніші за основне коло."},"hours":"Day cruises ~08:00–17:00","website":"https://en.wikipedia.org/wiki/H%E1%BA%A1_Long_Bay","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Ha_Long_Bay_in_2019.jpg/960px-Ha_Long_Bay_in_2019.jpg"]},{"id":"lan-ha-bay","region":"hanoi","area":"Cat Ba","category":"nature","name":"Lan Ha Bay","nameVi":"Vịnh Lan Hạ","lat":20.75157,"lng":107.10428,"address":"Off Cat Ba Island, Hai Phong (boats from Cat Ba or Ha Long)","rating":4.7,"googleRating":null,"price":3,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Quieter twin of Ha Long Bay","desc":{"en":"Ha Long's southern neighbour has the same karst scenery but fewer boats, with tiny white-sand coves, floating fish farms and superb kayaking.","uk":"Південний сусід Халонгу має такі самі карстові пейзажі, але менше суден — крихітні бухти з білим піском, плавучі рибні ферми й чудовий каякінг."},"tip":{"en":"Base yourself on Cat Ba Island and book a small-boat kayak day tour, or pick a Ha Long cruise that routes through Lan Ha.","uk":"Зупиніться на острові Катба й візьміть денний тур на маленькому човні з каяками, або оберіть халонгський круїз із маршрутом через Лан Ха."},"hours":"","website":"https://en.wikipedia.org/wiki/Lan_H%E1%BA%A1_Bay","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/6/63/Lan_Ha_Bay_and_Ha_Long_Bay.jpg/960px-Lan_Ha_Bay_and_Ha_Long_Bay.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/Lan_Ha_bay_jonques.jpg/960px-Lan_Ha_bay_jonques.jpg"]},{"id":"trang-an","region":"hanoi","area":"Ninh Binh","category":"nature","name":"Trang An Scenic Landscape Complex","nameVi":"Quần thể danh thắng Tràng An","lat":20.25269,"lng":105.91808,"address":"Trang An boat wharf, Hoa Lu, Ninh Binh (~2 h from Hanoi)","rating":4.8,"googleRating":null,"price":1,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"UNESCO site; filming location of Kong: Skull Island","desc":{"en":"Rowing boats glide between towering karst cliffs and through low water caves to hidden temples — 'Ha Long Bay on land' and a UNESCO World Heritage Site.","uk":"Весельні човни ковзають між стрімкими карстовими скелями та крізь низькі водяні печери до прихованих храмів — «Халонг на суші» та об’єкт Світової спадщини ЮНЕСКО."},"tip":{"en":"Start at 7–8 am before tour buses arrive; the ~2.5 h Route 1 has the most caves. Boats take 4 people, so solo travellers get paired up.","uk":"Починайте о 7–8 ранку, до туристичних автобусів; маршрут 1 (~2,5 год) має найбільше печер. У човен сідає 4 людини — соло-мандрівників об’єднують."},"hours":"~07:00–16:00","website":"https://en.wikipedia.org/wiki/Tr%C3%A0ng_An_Scenic_Landscape_Complex","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Trang_An_Landscape_Complex%2C_Ninh_Binh_Province%2C_Vietnam%2C_20240202_1433_5284.jpg/960px-Trang_An_Landscape_Complex%2C_Ninh_Binh_Province%2C_Vietnam%2C_20240202_1433_5284.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/Tour_boats_at_Trang_An_Landscape_Complex%2C_Ninh_Binh_Province%2C_Vietnam%2C_20240202_1346_5149.jpg/960px-Tour_boats_at_Trang_An_Landscape_Complex%2C_Ninh_Binh_Province%2C_Vietnam%2C_20240202_1346_5149.jpg"]},{"id":"hang-mua-viewpoint","region":"hanoi","area":"Ninh Binh","category":"nature","name":"Hang Mua Viewpoint","nameVi":"Hang Múa","lat":20.22867,"lng":105.93516,"address":"Khe Dau Ha, Ninh Xuan (Nam Hoa Lu), Ninh Binh","rating":4.7,"googleRating":null,"price":1,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Instagram-famous Lying Dragon summit view","desc":{"en":"Climb about 500 stone steps to a dragon-crowned summit for the classic panorama over Tam Coc's rice paddies and the winding Ngo Dong River.","uk":"Підніміться приблизно 500 кам’яними сходинками до вершини з драконом — звідти відкривається класична панорама рисових полів Тамкок і звивистої річки Нго Донг."},"tip":{"en":"Go at sunrise or an hour before sunset; rice is greenest in May–June and golden in late May / early June and September.","uk":"Ідіть на світанку або за годину до заходу; рис найзеленіший у травні–червні, а золотий — наприкінці травня / на початку червня та у вересні."},"hours":"~06:00–19:00","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/2/2f/View_from_Hang_Mua.jpg/960px-View_from_Hang_Mua.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/Lying_Dragon_%28Unsplash%29.jpg/960px-Lying_Dragon_%28Unsplash%29.jpg"]},{"id":"tam-coc","region":"hanoi","area":"Ninh Binh","category":"nature","name":"Tam Coc","nameVi":"Tam Cốc – Bích Động","lat":20.21634,"lng":105.93746,"address":"Van Lam boat pier, Ninh Hai, Ninh Binh","rating":4.6,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Boat rowers who paddle with their feet","desc":{"en":"A gentle river ride through rice paddies and three low caves, with local women famously rowing the sampans with their feet.","uk":"Неспішна прогулянка річкою серед рисових полів і крізь три низькі печери; місцеві жінки славляться тим, що гребуть сампанами ногами."},"tip":{"en":"Cycle the quiet lanes around Tam Coc village and add Bich Dong Pagoda; politely decline vendor boats selling drinks mid-river.","uk":"Покатайтеся велосипедом тихими дорогами довкола села Тамкок і загляньте до пагоди Бік Донг; ввічливо відмовляйтеся від човнів-продавців напоїв посеред річки."},"hours":"~07:00–17:00","website":"https://en.wikipedia.org/wiki/Tam_C%E1%BB%91c_%E2%80%93_B%C3%ADch_%C4%90%E1%BB%99ng","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/b/b4/Tam_Coc_from_Summit_-_August_2023.jpg/960px-Tam_Coc_from_Summit_-_August_2023.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/Rameuse_%C3%A0_Tam_Coc_%281%29.jpg/960px-Rameuse_%C3%A0_Tam_Coc_%281%29.jpg"]},{"id":"bai-dinh-pagoda","region":"hanoi","area":"Ninh Binh","category":"temples","name":"Bai Dinh Pagoda","nameVi":"Chùa Bái Đính","lat":20.27694,"lng":105.86278,"address":"Gia Sinh, Gia Vien (Tay Hoa Lu), Ninh Binh","rating":4.5,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Vietnam's largest Buddhist complex — record-breaking statues","desc":{"en":"A colossal modern temple complex on a hillside, with a 100-ton bronze Buddha, 500 stone arhats lining kilometre-long corridors and a 13-storey stupa.","uk":"Величезний сучасний храмовий комплекс на схилі пагорба: 100-тонний бронзовий Будда, 500 кам’яних архатів уздовж кілометрових галерей і 13-поверхова ступа."},"tip":{"en":"Entry is free but take the electric cart from the car park (~30k VND); combine with Trang An, 15 minutes away.","uk":"Вхід безкоштовний, але від парковки їдьте електрокаром (~30 тис. донгів); поєднайте з Чанган, що за 15 хвилин."},"hours":"~06:00–18:00","website":"https://en.wikipedia.org/wiki/B%C3%A1i_%C4%90%C3%ADnh_Temple","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/M%E1%BB%98T_G%C3%93C_CH%C3%99A_B%C3%81I_%C4%90%C3%8DNH_-_panoramio.jpg/960px-M%E1%BB%98T_G%C3%93C_CH%C3%99A_B%C3%81I_%C4%90%C3%8DNH_-_panoramio.jpg"]},{"id":"sapa","region":"hanoi","area":"Sapa (Lao Cai)","category":"nature","name":"Sapa & Muong Hoa Valley (far trip)","nameVi":"Sa Pa","lat":22.33337,"lng":103.84266,"address":"Sa Pa, Lao Cai (~5–6 h from Hanoi by bus or night train + transfer)","rating":4.6,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Rice-terrace trekking; Fansipan 'Roof of Indochina'","desc":{"en":"A misty mountain town above spectacular rice terraces, base for treks through Hmong and Red Dao villages and the cable car up Fansipan (3,143 m).","uk":"Туманне гірське містечко над приголомшливими рисовими терасами — база для трекінгу селами хмонгів і червоних дао та канатної дороги на Фансіпан (3143 м)."},"tip":{"en":"Worth it only with 2+ nights; terraces are greenest June–July and golden in September. Book a local guide for Lao Chai – Ta Van treks.","uk":"Варто їхати мінімум на 2 ночі; тераси найзеленіші в червні–липні, золоті — у вересні. Беріть місцевого гіда на трек Лао Чай – Та Ван."},"hours":"","website":"https://en.wikipedia.org/wiki/Sa_Pa","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/5/56/Sa_Pa.jpg/960px-Sa_Pa.jpg"]},{"id":"bun-cha-huong-lien","region":"hanoi","area":"Hai Ba Trung","category":"streetfood","name":"Bun Cha Huong Lien ('Bun Cha Obama')","nameVi":"Bún Chả Hương Liên","lat":21.01809,"lng":105.85386,"address":"24 Le Van Huu St, Hai Ba Trung","rating":4.4,"googleRating":null,"price":1,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Obama & Bourdain dinner 2016 (Parts Unknown); Michelin Selected","desc":{"en":"The no-frills canteen where Barack Obama and Anthony Bourdain shared bún chả and Hanoi beer on plastic stools — their table is now preserved behind glass.","uk":"Простенька їдальня, де Барак Обама та Ентоні Бурден їли bún chả і пили ханойське пиво на пластикових стільчиках, — їхній стіл тепер зберігають під склом."},"tip":{"en":"Order the 'Combo Obama' (bún chả, seafood nem roll and Hanoi beer); come before 11:30 or after 13:30 to avoid queues.","uk":"Замовте «Комбо Обама» (bún chả, нем із морепродуктами та ханойське пиво); приходьте до 11:30 або після 13:30, щоб уникнути черг."},"hours":"08:00–20:00","website":"https://guide.michelin.com/vn/en/ha-noi/ha-noi_2974158/restaurant/bun-cha-huong-lien","images":["https://prod-pics.guide.michelin.com/api/public/content/a07d335f58114c3c856afbaea73668aa.jpeg?format=jpeg&w=1000&h=1000","https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/President_Barack_Obama_with_Anthony_Bourdain_at_B%C3%BAn_cha_Huong_Lien_Restaurant_in_Hanoi%2C_Vietnam.jpg/960px-President_Barack_Obama_with_Anthony_Bourdain_at_B%C3%BAn_cha_Huong_Lien_Restaurant_in_Hanoi%2C_Vietnam.jpg"]},{"id":"pho-gia-truyen-bat-dan","region":"hanoi","area":"Hoan Kiem","category":"streetfood","name":"Pho Gia Truyen (49 Bat Dan)","nameVi":"Phở Gia Truyền Bát Đàn","lat":21.0336,"lng":105.84619,"address":"49 Bat Dan St, Hoan Kiem","rating":4.6,"googleRating":null,"price":1,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Michelin Bib Gourmand; legendary queue, self-service","desc":{"en":"Hanoi's most famous bowl of beef phở: a clear, deeply beefy broth ladled by a family that has done it for generations — you queue, pay, carry your own bowl and sit on a bench.","uk":"Найвідоміша ханойська тарілка яловичого фо: прозорий насичений бульйон від родини, що варить його поколіннями, — стаєте в чергу, платите, самі несете миску й сідаєте на лавку."},"tip":{"en":"Order 'tái nạm' (rare + flank); arrive near 6–7 am opening — it closes when the broth runs out, then reopens for dinner.","uk":"Замовте «tái nạm» (слабосмажена + пашина); приходьте до відкриття о 6–7 ранку — закриваються, коли закінчується бульйон, а ввечері відкриваються знову."},"hours":"06:00–11:00, 17:00–21:30","website":"https://guide.michelin.com/vn/en/ha-noi/ha-noi_2974158/restaurant/pho-gia-truyen","images":["https://prod-pics.guide.michelin.com/api/public/content/561b23b5e539471d9e7ea1fe1968946e.jpeg?format=jpeg&w=1000&h=1000"]},{"id":"pho-thin-lo-duc","region":"hanoi","area":"Hai Ba Trung","category":"streetfood","name":"Pho Thin (13 Lo Duc)","nameVi":"Phở Thìn Lò Đúc","lat":21.01704,"lng":105.856,"address":"13 Lo Duc St, Hai Ba Trung","rating":4.3,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Since 1979; wok-seared beef phở, branches in Tokyo & Melbourne","desc":{"en":"A smoky 1979 shophouse famous for phở tái lăn — beef flash-fried with garlic in a wok before going into a rich broth heaped with spring onion.","uk":"Задимлена закусочна з 1979 року, відома phở tái lăn — яловичину швидко обсмажують із часником у воку, а потім кладуть у насичений бульйон із горою зеленої цибулі."},"tip":{"en":"Make sure you're at the original 13 Lo Duc (several copycats use the name); go down the narrow alley to the back room.","uk":"Переконайтеся, що ви в оригінальному закладі на Ло Дик, 13 (назву використовують кілька копій); пройдіть вузьким проходом у задню залу."},"hours":"~06:00–21:00","website":"","images":["https://flavorsofhanoi.com/wp-content/uploads/2020/11/Pho-Thin-13-Lo-Duc.jpg","https://flavorsofhanoi.com/wp-content/uploads/2021/06/A-bowl-of-Pho-Thin.jpg"]},{"id":"bun-cha-dac-kim","region":"hanoi","area":"Hoan Kiem","category":"streetfood","name":"Bun Cha Dac Kim","nameVi":"Bún Chả Đắc Kim","lat":21.03235,"lng":105.84817,"address":"1 Hang Manh St, Hoan Kiem","rating":4.2,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Michelin Selected; Old Quarter bún chả institution since 1965","desc":{"en":"A narrow multi-storey Old Quarter shop serving huge portions of charcoal-grilled pork patties and belly in sweet-sour broth with noodles and crab spring rolls.","uk":"Вузький багатоповерховий заклад у Старому кварталі з величезними порціями котлеток і грудинки з вугільного гриля в кисло-солодкому бульйоні з локшиною та крабовими спрінг-ролами."},"tip":{"en":"One portion easily feeds two — order one bún chả plus a nem cua bể (crab roll) to share.","uk":"Однієї порції легко вистачить на двох — замовте один bún chả і nem cua bể (крабовий рол) навпіл."},"hours":"09:00–21:00","website":"https://guide.michelin.com/vn/en/ha-noi/ha-noi_2974158/restaurant/bun-cha-%C4%91ac-kim","images":["https://prod-pics.guide.michelin.com/api/public/content/36c6a979a935439ab6e29102522b327b.jpeg?format=jpeg&w=1000&h=1000"]},{"id":"banh-mi-25","region":"hanoi","area":"Hoan Kiem","category":"streetfood","name":"Banh Mi 25","nameVi":"Bánh Mì 25","lat":21.03608,"lng":105.84869,"address":"25 Hang Ca St, Old Quarter","rating":4.3,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"TripAdvisor & blogger favourite — the Old Quarter's most-photographed bánh mì","desc":{"en":"A cheerful stall turning out crackly baguettes stuffed with pâté, grilled pork, egg or tofu and fresh herbs, with an English menu and constant queues.","uk":"Жвавий кіоск, де готують хрусткі багети з паштетом, смаженою свининою, яйцем чи тофу та свіжою зеленню; є англійське меню й постійні черги."},"tip":{"en":"Order at No. 25 and sit across the road at No. 30; try the 'mixed' or the tofu-mushroom for vegetarians. Cash is safest.","uk":"Замовляйте на № 25, а сідайте навпроти, на № 30; спробуйте «mixed» або тофу з грибами для вегетаріанців. Найнадійніше — готівка."},"hours":"07:00–21:00","website":"","images":["https://flavorsofhanoi.com/wp-content/uploads/2020/09/Banh-Mi-25.jpg"]},{"id":"xoi-yen","region":"hanoi","area":"Hoan Kiem","category":"streetfood","name":"Xoi Yen","nameVi":"Xôi Yến","lat":21.03377,"lng":105.85454,"address":"35B Nguyen Huu Huan St, Hoan Kiem","rating":4.1,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Hanoi's best-known sticky-rice shop","desc":{"en":"A bustling corner shop dishing up xôi xéo — turmeric sticky rice with shaved mung bean and crispy shallots — topped with caramel pork, Chinese sausage or a fried egg.","uk":"Жвавий кутовий заклад, де подають xôi xéo — клейкий рис із куркумою, тертою машем і хрусткою цибулею-шалот — зі свининою в карамелі, китайською ковбаскою чи смаженим яйцем."},"tip":{"en":"Perfect early breakfast or late-night snack — pick 'xôi xéo' with 'thịt kho' (braised pork) and a pâté slice.","uk":"Ідеально на ранній сніданок чи пізню перекуску — беріть «xôi xéo» з «thịt kho» (тушкованою свининою) та скибочкою паштету."},"hours":"~06:00–00:00","website":"","images":["https://static.vinwonders.com/production/Xoi-xeo-Hanoi-thumb.jpg"]},{"id":"banh-cuon-ba-hoanh","region":"hanoi","area":"Hai Ba Trung","category":"streetfood","name":"Banh Cuon Ba Hoanh","nameVi":"Bánh Cuốn Bà Hoành","lat":21.01357,"lng":105.84969,"address":"66 To Hien Thanh St, Hai Ba Trung","rating":4.3,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Michelin Selected; local favourite since the 1980s","desc":{"en":"Locals pack this family shop for silky steamed rice rolls filled with minced pork and wood-ear mushroom, freshly made in front of you and served with dipping fish sauce and chả.","uk":"Місцеві обожнюють цей сімейний заклад за ніжні рисові роли на пару з фаршем і грибами муер, які готують просто перед вами й подають із соусом ніок-мам і chả."},"tip":{"en":"Add a 'trứng' (egg) bánh cuốn and a side of chả quế (cinnamon pork sausage); it's off the tourist trail, so point at what others are eating.","uk":"Додайте bánh cuốn із яйцем («trứng») і chả quế (свинячу ковбаску з корицею); туристів тут мало, тож просто покажіть на те, що їдять інші."},"hours":"06:00–20:00","website":"https://guide.michelin.com/vn/en/ha-noi/ha-noi_2974158/restaurant/banh-cuon-ba-hoanh","images":["https://prod-pics.guide.michelin.com/api/public/content/1c03287d1c4a438b9b8af53cb9948f3c.jpeg?format=jpeg&w=1000&h=1000"]},{"id":"cha-ca-thang-long","region":"hanoi","area":"Hoan Kiem","category":"restaurants","name":"Cha Ca Thang Long","nameVi":"Chả Cá Thăng Long","lat":21.03304,"lng":105.84615,"address":"6B Duong Thanh St, Hoan Kiem","rating":4.4,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Michelin Bib Gourmand; Hanoi's signature turmeric fish","desc":{"en":"Hanoi's signature dish done right: turmeric-marinated fish sizzles at your table in a pan of dill and spring onion, eaten with rice noodles, peanuts and shrimp paste.","uk":"Фірмова страва Ханоя як вона є: риба в куркумі шкварчить просто на вашому столі на сковороді з кропом і зеленою цибулею, її їдять із рисовою локшиною, арахісом і креветковою пастою."},"tip":{"en":"There's only one dish — just say how many people. Try the mắm tôm (shrimp paste) dip at least once; ask for fish sauce if it's too pungent.","uk":"Тут лише одна страва — просто скажіть, скільки вас. Спробуйте хоча б раз соус mắm tôm (креветкову пасту); якщо надто різко — попросіть рибний соус."},"hours":"06:00–21:00","website":"https://guide.michelin.com/vn/en/ha-noi/ha-noi_2974158/restaurant/cha-ca-thang-long","images":["https://prod-pics.guide.michelin.com/api/public/content/b82d3b38976c405786044e6f365a76d1.jpeg?format=jpeg&w=1000&h=1000"]},{"id":"gia-restaurant","region":"hanoi","area":"Dong Da","category":"restaurants","name":"Gia","nameVi":"Nhà hàng Gia","lat":21.02742,"lng":105.83596,"address":"61 Van Mieu St, opposite the Temple of Literature","rating":4.8,"googleRating":null,"price":4,"mustSee":true,"hiddenGem":false,"viral":false,"hype":"One Michelin Star (2023–2026); Asia's 50 Best Restaurants list","desc":{"en":"Chef Sam Tran's intimate dining room reinterprets Vietnamese ingredients and memories in an elegant tasting menu with native-botanical drink pairings.","uk":"Затишна зала шефині Сем Чан по-новому інтерпретує в’єтнамські продукти та спогади в елегантному дегустаційному меню з напоями на місцевих травах."},"tip":{"en":"Dinner only, Tue–Sun; book weeks ahead and try the non-alcoholic pairing.","uk":"Лише вечеря, вт–нд; бронюйте за кілька тижнів і спробуйте безалкогольний пейринг."},"hours":"Tue–Sun 18:00–21:00","website":"https://guide.michelin.com/vn/en/ha-noi/ha-noi_2974158/restaurant/gia-1202148","images":["https://prod-pics.guide.michelin.com/api/public/content/0e5e954271464108bfd6a3ba19fbe460.jpg?format=jpeg&w=1000&h=1000"]},{"id":"hibana-by-koki","region":"hanoi","area":"Hoan Kiem","category":"restaurants","name":"Hibana by Koki","nameVi":"Hibana by Koki","lat":21.02584,"lng":105.85657,"address":"B1F, Capella Hanoi, 11 Le Phung Hieu St","rating":4.7,"googleRating":null,"price":4,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"One Michelin Star (2023–2026)","desc":{"en":"A hushed 14-seat teppanyaki counter in the basement of the opulent Capella, where chefs grill Japanese wagyu and premium seafood with theatrical precision.","uk":"Тиха теппаньякі-стійка на 14 місць у підвалі розкішного Capella, де кухарі з театральною точністю готують японське вагю та елітні морепродукти."},"tip":{"en":"Book a counter seat; pair it with a drink upstairs at The Hudson Rooms, Asia's 50 Best Bars #46.","uk":"Бронюйте місце біля стійки; поєднайте з коктейлем нагорі в The Hudson Rooms — №46 у списку Asia's 50 Best Bars."},"hours":"Tue–Sun 11:30–13:30, 18:00–22:00","website":"https://guide.michelin.com/vn/en/ha-noi/ha-noi_2974158/restaurant/hibana-by-koki","images":["https://prod-pics.guide.michelin.com/api/public/content/4cd62940bc5c48fc9d91322d5f31a994.jpg?format=jpeg&w=1000&h=1000"]},{"id":"tam-vi","region":"hanoi","area":"Ba Dinh","category":"restaurants","name":"Tam Vi","nameVi":"Tầm Vị","lat":21.02903,"lng":105.83947,"address":"4B Yen The St, Ba Dinh","rating":4.7,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"One Michelin Star (2023–2026) at moderate prices","desc":{"en":"A wood-panelled room filled with antiques serving homely northern Vietnamese family dishes — braised pork, crab soup, fried tofu — good enough for a Michelin star.","uk":"Зала з дерев’яними панелями й антикваріатом, де подають домашні північнов’єтнамські страви — тушковану свинину, крабовий суп, смажений тофу — настільки добре, що отримали зірку Michelin."},"tip":{"en":"One of the world's most affordable Michelin-starred meals — reserve, go with a group and share 5–6 dishes.","uk":"Одна з найдоступніших зіркових вечер Michelin у світі — бронюйте, ідіть компанією й беріть 5–6 страв на всіх."},"hours":"11:00–14:30, 17:00–21:50","website":"https://guide.michelin.com/vn/en/ha-noi/ha-noi_2974158/restaurant/tam-vi","images":["https://prod-pics.guide.michelin.com/api/public/content/5f2a542de9d143dbb7f5ed3eae320daa.jpeg?format=jpeg&w=1000&h=1000"]},{"id":"onvit","region":"hanoi","area":"Cau Giay","category":"restaurants","name":"ONVIT","nameVi":"ONVIT","lat":21.00743,"lng":105.79682,"address":"3F, Grand Plaza Hotel, 117 Tran Duy Hung St, Yen Hoa","rating":4.6,"googleRating":null,"price":4,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"New One Michelin Star 2026 — Vietnam's first starred Korean restaurant","desc":{"en":"Chef Joon's serene tasting room blends Korean technique with Vietnamese produce; the signature abalone porridge uses ST25 rice and abalone-liver sauce.","uk":"У спокійній залі шефа Джуна корейська техніка поєднується з в’єтнамськими продуктами; фірмова каша з морським вушком готується з рису ST25 і соусу з печінки молюска."},"tip":{"en":"It's in the west of the city (~25 min by Grab); the 2026 Michelin Sommelier Award winner works here — take the wine pairing.","uk":"Ресторан на заході міста (~25 хв на Grab); тут працює переможниця премії Michelin Sommelier 2026 — беріть винний пейринг."},"hours":"Mon–Sat 11:45–14:00, 18:00–22:00","website":"https://guide.michelin.com/vn/en/ha-noi/ha-noi_2974158/restaurant/onvit","images":["https://prod-pics.guide.michelin.com/api/public/content/41b31c6034624eb88b178b3bc19499e5.jpeg?format=jpeg&w=1000&h=1000"]},{"id":"cafe-giang","region":"hanoi","area":"Hoan Kiem","category":"cafes","name":"Cafe Giang (original egg coffee)","nameVi":"Cà Phê Giảng","lat":21.03361,"lng":105.85462,"address":"39 Nguyen Huu Huan St (down the alley), Hoan Kiem","rating":4.5,"googleRating":null,"price":1,"mustSee":true,"hiddenGem":false,"viral":true,"hype":"Birthplace of egg coffee (1946); CNN & countless TikToks","desc":{"en":"The family café where Mr Giang invented cà phê trứng in 1946, whisking egg yolk and condensed milk into a custardy foam over strong Robusta.","uk":"Сімейна кав’ярня, де пан Зянг 1946 року винайшов cà phê trứng, збиваючи жовток зі згущеним молоком у кремову піну поверх міцної робусти."},"tip":{"en":"Order the hot egg coffee served in a bowl of hot water to keep it warm; the upstairs room is calmer.","uk":"Замовте гарячу яєчну каву, яку подають у мисці з гарячою водою, щоб не холола; на другому поверсі спокійніше."},"hours":"07:00–22:00","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/Egg_coffee_Caf%C3%A9_Giang%2C_lane_39%2C_since_1946.jpg/960px-Egg_coffee_Caf%C3%A9_Giang%2C_lane_39%2C_since_1946.jpg","https://upload.wikimedia.org/wikipedia/commons/thumb/b/bf/Giang_Caf%C3%A9_%28Caf%C3%A9_Gi%E1%BA%A3ng%29_-_Nguyen_Huu_Huan_Street%2C_Hanoi%2C_Vietnam_-_DSC03676.JPG/960px-Giang_Caf%C3%A9_%28Caf%C3%A9_Gi%E1%BA%A3ng%29_-_Nguyen_Huu_Huan_Street%2C_Hanoi%2C_Vietnam_-_DSC03676.JPG"]},{"id":"cafe-dinh","region":"hanoi","area":"Hoan Kiem","category":"cafes","name":"Cafe Dinh","nameVi":"Cà Phê Đinh","lat":21.032,"lng":105.85239,"address":"13 Dinh Tien Hoang St, 2nd floor (up a dark stairway)","rating":4.4,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Run by the Giang family; secret lake-view balcony","desc":{"en":"Climb a gloomy staircase above a shop to find this shabby-chic family café with a tiny balcony overlooking Hoan Kiem Lake and egg coffee rivalling Cafe Giang's.","uk":"Підніміться темними сходами над крамницею — і знайдете обшарпано-затишну сімейну кав’ярню з крихітним балконом на озеро Хоан Кьєм і яєчною кавою, не гіршою за Cafe Giang."},"tip":{"en":"Look for the small 'Cafe Dinh – Tầng 2' sign; grab a balcony stool at dusk.","uk":"Шукайте невеличку табличку «Cafe Dinh – Tầng 2»; займіть стільчик на балконі в сутінках."},"hours":"07:00–22:00","website":"","images":["https://www.wheregoesrose.com/wp-content/uploads/2020/04/Cafe-Dinh-Hanoi-1024x768.jpeg","https://www.wheregoesrose.com/wp-content/uploads/2021/07/cafe-dinh-hanoi-egg-coffee.jpeg"]},{"id":"loading-t-cafe","region":"hanoi","area":"Hoan Kiem","category":"cafes","name":"Loading T","nameVi":"Loading T Cafe","lat":21.03053,"lng":105.84859,"address":"8 Chan Cam St, 1st floor of a French colonial villa","rating":4.4,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Hidden café in a crumbling 1920s French villa","desc":{"en":"Tucked up the stairs of a faded colonial mansion, this calm café with peeling yellow walls and old wooden shutters serves excellent coconut and egg coffee.","uk":"Сховане нагорі старого колоніального особняка, це спокійне кафе з облупленими жовтими стінами та дерев’яними віконницями подає чудову кокосову й яєчну каву."},"tip":{"en":"A peaceful escape near St. Joseph's — try the coconut coffee or salted coffee and sit by the window.","uk":"Тихий прихисток поруч із собором Святого Йосипа — спробуйте кокосову чи солону каву й сядьте біля вікна."},"hours":"~08:00–22:00","website":"","images":["https://www.wheregoesrose.com/wp-content/uploads/2020/04/Loading-T-cafe-Hanoi.jpeg"]},{"id":"note-coffee","region":"hanoi","area":"Hoan Kiem","category":"cafes","name":"The Note Coffee","nameVi":"The Note Coffee","lat":21.03162,"lng":105.85084,"address":"64 Luong Van Can St, Hoan Kiem","rating":4.4,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Instagram-famous café covered in thousands of sticky notes","desc":{"en":"Every wall, table and lampshade of this three-storey café is plastered with colourful Post-it notes left by visitors, with a balcony view of Hoan Kiem Lake.","uk":"Кожна стіна, стіл і абажур цієї триповерхової кав’ярні обклеєні кольоровими стікерами від відвідувачів, а з балкона видно озеро Хоан Кьєм."},"tip":{"en":"Leave your own note (pens provided) and head to the top floor for the lake view.","uk":"Залиште свою записку (ручки дають) і підніміться на верхній поверх заради вигляду на озеро."},"hours":"07:00–23:00","website":"","images":["https://www.wheregoesrose.com/wp-content/uploads/2020/06/Note-coffee-hanoi.jpeg"]},{"id":"cong-caphe","region":"hanoi","area":"Hai Ba Trung","category":"cafes","name":"Cong Caphe (original store)","nameVi":"Cộng Cà Phê","lat":21.01393,"lng":105.85031,"address":"152 Trieu Viet Vuong St (first branch, 2007); many others incl. Nha Tho & Trang Tien","rating":4.2,"googleRating":null,"price":1,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Retro communist-era chain famous for coconut coffee","desc":{"en":"A cult Vietnamese chain styled like a 1970s subsidy-era home — army-green walls, enamel mugs, propaganda art — famed for its icy coconut-milk coffee.","uk":"Культова в’єтнамська мережа в стилі помешкання 1970-х часів «субсидійної» епохи — стіни кольору хакі, емальовані кухлі, агітаційні плакати — славиться крижаною кавою з кокосовим молоком."},"tip":{"en":"Order 'cốt dừa cà phê' (coconut coffee smoothie); the branch on Trieu Viet Vuong 'coffee street' is the original.","uk":"Замовте «cốt dừa cà phê» (кокосовий кавовий смузі); оригінальна кав’ярня — на «кавовій вулиці» Чьєу В’єт Выонг."},"hours":"07:00–23:00","website":"https://congcaphe.com","images":["https://cong-news.appwifi.com/wp-content/uploads/2019/05/Pha-Che.jpg"]},{"id":"workshop14","region":"hanoi","area":"Tay Ho","category":"bars","name":"Workshop14","nameVi":"Workshop14","lat":21.05825,"lng":105.83245,"address":"6 Alley 5 Tu Hoa St, Quang An, Tay Ho","rating":4.8,"googleRating":null,"price":3,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Asia's 50 Best Bars 2026 #34 & Best Bar in Vietnam 2026","desc":{"en":"A tiny 14-seat cocktail lab near West Lake applying modern techniques — ferments, clarifications, distillates — to Vietnamese ingredients; Hanoi's highest-ranked bar.","uk":"Крихітна коктейльна лабораторія на 14 місць біля Західного озера, де сучасні техніки — ферментація, освітлення, дистиляти — застосовують до в’єтнамських інгредієнтів; найвище оцінений бар Ханоя."},"tip":{"en":"Only 14 seats — reserve ahead; closed Mondays.","uk":"Лише 14 місць — бронюйте заздалегідь; у понеділок вихідний."},"hours":"Tue–Sun 18:00–01:00","website":"https://www.theworlds50best.com/bars/best-in-asia/the-list/Workshop14.html","images":["https://www.the50.com/bars/best-in-asia/filestore/jpg/Workshop14-hero_A50BB26-site.jpg","https://www.the50.com/bars/best-in-asia/filestore/jpg/Workshop14-drink_A50BB26-site.jpg"]},{"id":"the-hudson-rooms","region":"hanoi","area":"Hoan Kiem","category":"bars","name":"The Hudson Rooms (Capella Hanoi)","nameVi":"The Hudson Rooms","lat":21.02571,"lng":105.85681,"address":"Rooftop, Capella Hanoi, 11 Le Phung Hieu St","rating":4.7,"googleRating":null,"price":4,"mustSee":false,"hiddenGem":false,"viral":false,"hype":"Asia's 50 Best Bars 2026 #46 — first Hanoi bar in the top 50","desc":{"en":"A Jazz Age-styled rooftop salon atop the flamboyant Capella, pouring polished signature cocktails with views over the Opera House district.","uk":"Салон на даху вишуканого Capella в стилі епохи джазу з бездоганними авторськими коктейлями та видом на квартал Оперного театру."},"tip":{"en":"Dress smart-casual and come for sunset; combine with dinner at Michelin-starred Hibana downstairs.","uk":"Одягніться в smart casual і приходьте на захід сонця; поєднайте з вечерею в зірковому Hibana поверхами нижче."},"hours":"~17:00–00:00","website":"https://www.theworlds50best.com/bars/best-in-asia/the-list/the-hudson-room.html","images":["https://www.the50.com/bars/best-in-asia/filestore/jpg/The%20hudsoon%20rooms-hero_A50BB26-site.jpg","https://www.the50.com/bars/best-in-asia/filestore/jpg/The%20hudsoon%20rooms-drink_A50BB26-site.jpg"]},{"id":"ne-cocktail-bar","region":"hanoi","area":"Hoan Kiem","category":"bars","name":"Nê Cocktail & Wine Bar","nameVi":"Nê Cocktail Bar","lat":21.02958,"lng":105.84402,"address":"3B Tong Duy Tan St, Hoan Kiem","rating":4.6,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Asia's 50 Best Bars 51–100 (2021); viral 'Phở cocktail'","desc":{"en":"A dark, intimate counter bar famous for liquid riffs on Vietnamese dishes — above all the Phở cocktail, flamed tableside with star anise and cinnamon.","uk":"Темний затишний бар зі стійкою, відомий коктейлями за мотивами в’єтнамських страв — передусім «Фо-коктейлем», який підпалюють просто перед вами з бадьяном і корицею."},"tip":{"en":"Order the Phở cocktail for the show; the larger sister bar Nê Boong-ke is at 12 Cua Dong if this one is full.","uk":"Замовте «Фо-коктейль» заради шоу; якщо тут повно, більший «сестринський» бар Nê Boong-ke — на Куа Донг, 12."},"hours":"~18:00–01:00","website":"https://www.theworlds50best.com/discovery/Establishments/Vietnam/Hanoi/N%C3%AA-Cocktail-Bar.html","images":["https://jackfruitadventure.com/wp-content/uploads/2026/05/best-cocktail-bar-in-hanoi-1-900x506.jpg","https://jackfruitadventure.com/wp-content/uploads/2026/05/best-cocktail-bar-in-hanoi-2-900x506.jpg"]},{"id":"binh-minh-jazz-club","region":"hanoi","area":"Hoan Kiem","category":"bars","name":"Binh Minh Jazz Club","nameVi":"Câu lạc bộ Jazz Bình Minh","lat":21.02402,"lng":105.85836,"address":"1 Trang Tien St (behind the Opera House)","rating":4.4,"googleRating":null,"price":2,"mustSee":false,"hiddenGem":true,"viral":false,"hype":"Founded by saxophonist Quyen Van Minh, father of Vietnamese jazz","desc":{"en":"Hanoi's legendary jazz club, opened by saxophonist Quyen Van Minh, hosts live bands nightly in a dim, old-school room just behind the Opera House.","uk":"Легендарний ханойський джаз-клуб, заснований саксофоністом Куєном Ван Міном, щовечора приймає живі гурти в напівтемній старомодній залі просто за Оперним театром."},"tip":{"en":"Music starts around 21:00; arrive by 20:30 for a table near the stage — no cover, but drinks are pricier.","uk":"Музика починається близько 21:00; приходьте до 20:30, щоб сісти ближче до сцени — вхід вільний, але напої дорожчі."},"hours":"19:00–00:00 (live music ~21:00–23:30)","website":"","images":["https://upload.wikimedia.org/wikipedia/commons/thumb/6/66/Binh_Minh_Jazz_Club_sign_in_2014.jpg/960px-Binh_Minh_Jazz_Club_sign_in_2014.jpg"]},{"id":"summit-lounge-pan-pacific","region":"hanoi","area":"Ba Dinh","category":"bars","name":"The Summit (Pan Pacific Hanoi)","nameVi":"The Summit – Pan Pacific Hà Nội","lat":21.04961,"lng":105.84013,"address":"20F, Pan Pacific Hanoi, 1 Thanh Nien Rd","rating":4.4,"googleRating":null,"price":3,"mustSee":false,"hiddenGem":false,"viral":true,"hype":"Classic Hanoi rooftop sunset over West Lake","desc":{"en":"A 20th-floor rooftop lounge with sweeping views over West Lake, Truc Bach Lake and Tran Quoc Pagoda — Hanoi's go-to sunset cocktail.","uk":"Лаунж на даху 20-го поверху з широкою панорамою Західного озера, озера Чук Бать і пагоди Чан Куок — найпопулярніше в Ханої місце для коктейлю на заході сонця."},"tip":{"en":"Arrive ~45 minutes before sunset to snag a terrace seat; happy-hour deals usually run early evening.","uk":"Приходьте приблизно за 45 хвилин до заходу сонця, щоб зайняти місце на терасі; щасливі години зазвичай ранньої вечірньої пори."},"hours":"~16:00–00:00","website":"https://www.panpacific.com/en/hotels-and-resorts/pp-hanoi/dining/the-summit.html","images":["https://www.panpacific.com/content/dam/pphg-revamp/en/pphan/pphg2-0/dining/summit/PPHAN_Summit_Listing_Image.jpg"]}];
